        /**
         * pagamento
         *
         * @param Form $form
         * @param String $T007_Id
         * @return String/bool
         */     	
        public function pagamento($form, $T007_Id)
        {
            $Total_Parcelas = $form->campoValorEnviado('Total_Parcelas');
            $D027_Id        = $form->campoValorEnviado('Portador_D027_Id');
            $IntervalorDias = $form->campoValorEnviado('IntervalorDias');
            
            $cSql_T007 = mysql_query("SELECT * FROM T007 WHERE T007_Id='{$T007_Id}'");
            $mT007     = mysql_fetch_array($cSql_T007);
            //return "Id:" . $T007_Id . " NFe:" . $mT007['T007_Numero_Nota_Fiscal'] . " Total Parcelas:" . $Total_Parcelas . " Portador:" . $Portador_D027_Id . " Intervalo Dias:" . $IntervalorDias;
            
            if ($mT007['T007_Flag_Cancelada'] != 'S' && $mT007['T007_Flag_Impresso'] == 'S') {
                return 'Nota Fiscal já foi impressa, não pode ser alterada';
            }
            
            $cSql_D006 = mysql_query("SELECT * FROM D006 WHERE D006_Id='{$mT007['T007_D006_Id']}'");
            $mD006     = mysql_fetch_array($cSql_D006);
            
            if ($mD006['D006_Flag_Gera_Contas'] != 'P' AND $mD006['D006_Flag_Gera_Contas'] != 'R') {
                return 'Esta CFOP não gera contas! Para adicionar formas de pagamento informe uma CFOP que gera contas a Receber';
            }
            
            $cSql_T118 = mysql_query("SELECT * FROM T118 WHERE T118_T007_Id='{$T007_Id}'");
            while ($mT118 = mysql_fetch_array($cSql_T118)) {
                $mNumeroAntigo[$mT118['T118_Numero_Duplicata']] = $mT118['T118_Numero_Duplicata'];
                $mPrazoAntigo[$mT118['T118_Numero_Parcela']]    = $mT118['T118_Prazos_Dias'];
                $mPortadorAntigo[$mT118['T118_Numero_Parcela']] = $mT118['T118_D027_Id'];
            }
            
            mysql_query("delete FROM T118 WHERE T118_T007_Id='{$T007_Id}'");
            
            $Valor_Total_IPI          = $mT007['T007_Valor_Total_IPI'];
            $Valor_Total_Nota_Emitida = $mT007['T007_Valor_Total'];
              
            $Valor_Titulo_Parcela = ($Valor_Total_Nota_Emitida - $Valor_Total_IPI) / $Total_Parcelas;
            $Valor_Total_Titulo   = ((round($Valor_Titulo_Parcela, 2) * $Total_Parcelas) + $Valor_Total_IPI);
            $Valor_Total_Titulo   = round($Valor_Total_Titulo, 2);
            
            if ($Valor_Total_Titulo != $Valor_Total_Nota_Emitida) {
                $Diferenca_Primeira_Parcela = $Valor_Total_Nota_Emitida - $Valor_Total_Titulo;
            }
            
            for ($x = 1; $x <= $Total_Parcelas; $x++) {
                
                if ($x == 1) {
                    $Valor_Titulo = ($Valor_Titulo_Parcela + $Valor_Total_IPI) + $Diferenca_Primeira_Parcela;
                } else {
                    $Valor_Titulo = $Valor_Titulo_Parcela;
                }
                if ($D027_Id > 0) {
                    $mPortadorAntigo[$x] = $D027_Id;
                }
                //if (empty($mPrazoAntigo[$x])) {
                $mPrazoAntigo[$x] = ($IntervalorDias * $x);
                //}
                
                $cClausula = "INSERT INTO T118 (";
                $cClausula .= "T118_T007_Id,";
                $cClausula .= "T118_D027_Id,";
                $cClausula .= "T118_Numero_Parcela,";
                $cClausula .= "T118_Numero_Duplicata,";
                $cClausula .= "T118_Prazos_Dias,";
                $cClausula .= "T118_Data_Vencimento,";
                $cClausula .= "T118_Valor_Parcela";
                $cClausula .= ") VALUES (";
                $cClausula .= "'{$T007_Id}',";
                $cClausula .= "'{$mPortadorAntigo[$x]}',";
                $cClausula .= "'{$x}',";
                $cClausula .= "'{$mNumeroAntigo[$x]}',";
                $cClausula .= "'{$mPrazoAntigo[$x]}',";
                $cClausula .= "DATE_ADD(current_date(),INTERVAL {$mPrazoAntigo[$x]} DAY),";
                $cClausula .= "'{$Valor_Titulo}'";
                $cClausula .= ")";
                mysql_query($cClausula);
                $cErro = mysql_error();
                if (!empty($cErro)) {
                    return 'Erro: ' . $cErro;
                }
            }
            return true;
        }

        /**
     * excluirProduto
     *
     * @param String $T008_Id
     * @param String $T007_Id
     * @return String/bool
     */     
    public function excluirProduto($T008_Id, $T007_Id)
    {
        global $g;
        
        $sqlT007  = "SELECT T007_Id,
                            T007_Numero_Protocolo_Nfe,
                            T007_Flag_Travar_Nota,
                            T007_Chave_Acesso_Nfe,
                            T007_Numero_Recibo_Nfe,
                            T007_Flag_ACP
                       FROM T007 
                      WHERE T007_Id = '{$T007_Id}'";

        $sqlT007  = mysql_query($sqlT007);
        $T007 = mysql_fetch_array($sqlT007);
        $rT007 = mysql_num_rows($sqlT007);

        if(!empty($T007['T007_Numero_Protocolo_Nfe'])){
            return 'Nota já transmitida. Não é possível alterar.';
        }

        if ($T007['T007_Flag_Travar_Nota'] == 'S') {
            return 'Nota já finalizada, para altera-lá utilize o botão "Habilitar edição"';
        }

        $sqlT008 = mysql_query("SELECT T008_D009_Id,
                                       T008_T006_Id,
                                       D006_Flag_Destaca_Desconto_NF
                                  FROM T008 
                             LEFT JOIN D006 ON D006_Id = T008_D006_Id
                                 WHERE T008_Id = '{$T008_Id}'");

        $T008 = mysql_fetch_array($sqlT008);
        $rT008 = mysql_num_rows($sqlT008);

        if($T007['T007_Flag_ACP'] == '8' && $g['C031']['alterarItemPdvVinculadoDav'] == 'N' && $T008['T008_T006_Id'] > 0){
            return 'Este item está vinculado a uma DAV, não é possível excluir.';
        }

        $atualizarDescontoAposExclusao = 'N';
        if($T008['D006_Flag_Destaca_Desconto_NF'] == 'S'){
            $atualizarDescontoAposExclusao = 'S';
        }

        $sqlT001  = mysql_query("SELECT T001_Id FROM T001 WHERE T001_T008_Id = '{$T008_Id}'");
        $T001 = mysql_fetch_array($sqlT001);
        $rT001 = mysql_num_rows($sqlT001);

        mysql_query("SET AUTOCOMMIT=0");
        mysql_query("START TRANSACTION");

        if ($rT001 > 0) {

            mysql_query("DELETE FROM T001 WHERE T001_Id='{$T001['T001_Id']}'");
            // return 'Produto vinculado a uma entrada no histórico do produto.';
            if (mysql_error()) {
                mysql_query("ROLLBACK");
                return 'Falha na exclusão do histórico do produto...';
            }
        }

        // deletetando os registros da tabela estendida T008A vinculados ao T008
        mysql_query("DELETE FROM T008A WHERE T008A_T008_Id='{$T008_Id}'");        

        if (mysql_error()) {
            mysql_query("ROLLBACK");
            return 'Falha na exclusão do produto (tabela T008A)';
        }
        
        mysql_query("DELETE FROM T008 WHERE T008_Id='{$T008_Id}'") ;

        if (mysql_error()) {
            mysql_query("ROLLBACK");
            return 'Falha na exclusão do produto...';
        }

        if($atualizarDescontoAposExclusao == 'S'){
            require_once('bibliotecas/classes/VEN001.php');
            $VEN001 = new VEN001();
            // Se a CFOP aplica desconto no total precisa recalcular o desconto no total
            // Esse desconto é feito pela soma dos produtos
            $VEN001->aplicaDescontoCFOP('T008', 'T007', 0, $T007_Id, 'S');	
		}
        
        // Processa estoque do produto da empresa
        require_once('bibliotecas/classes/CAD002.php');
        $CAD002 = new CAD002();

        if($T008['T008_D009_Id']>0){
            $retorno = $CAD002->D001_reprocessa_historico(false, $T008['T008_D009_Id'], 10, true);
        }else{
            $retorno=true;
        }
        

        if($retorno===true){
            mysql_query("COMMIT");
            mysql_query("SET AUTOCOMMIT=1");
            return true;
        }else{
            mysql_query("ROLLBACK");
            return $retorno;
        }
    }
        
