    /**
     * normalizarConteudoXml
     *
     * Alguns XMLs baixados de integrações/portais podem vir escapados como
     * string (ex.: \" e \/), o que invalida a abertura no parser e também
     * deixa o arquivo salvo incorreto para impressão.
     *
     * @param string $conteudoXml
     * @return string
     */
    private function normalizarConteudoXml($conteudoXml)
    {
        if (!is_string($conteudoXml) || $conteudoXml === '') {
            return $conteudoXml;
        }

        if (substr($conteudoXml, 0, 3) === "\xEF\xBB\xBF") {
            $conteudoXml = substr($conteudoXml, 3);
        }

        if (strpos($conteudoXml, '\\"') !== false || strpos($conteudoXml, '\\/') !== false || strpos($conteudoXml, '\\r') !== false || strpos($conteudoXml, '\\n') !== false || strpos($conteudoXml, '\\t') !== false) {
            $conteudoXml = str_replace(
                array('\\"', "\\'", '\\/', '\\r', '\\n', '\\t'),
                array('"', "'", '/', "\r", "\n", "\t"),
                $conteudoXml
            );
        }

        return trim($conteudoXml);
    }

    /**
     * prepararImportarXML
     *
     * @param File $arquivo
     * @return array
     */ 

        public function prepararImportarXML($arquivo, $cadastrarProdutos=false, $geraContasReceber=false, $dados=false)
        {
            global $g;
            
            $mArquivo          = $arquivo;
            $cArquivo          = $mArquivo["name"];
            $cTipo_Arquivo     = substr($cArquivo, strrpos($cArquivo, ".") + 1, 3);
            $cTipo_Arquivo     = StrToLower($cTipo_Arquivo);
            $nTotal_Importados = 0;
            $relatorio         = array();
            $relatorioCance    = array();
            
            // Valida foi enviado o arquivo
            if (empty($cArquivo)) {
                return array(
                    0,
                    0,
                    "Selecione o arquivo"
                );
            }
            // Valida se a extenção do arquivo é XML ou ZIP            
            if ($cTipo_Arquivo != 'xml' AND $cTipo_Arquivo != 'zip') {
                return array(
                    0,
                    0,
                    "O arquivo deve ser no formato XML ou ZIP ({$cTipo_Arquivo})"
                );
            }
            
            if ($cTipo_Arquivo == 'zip') {
                // Caso extensão arquivo seja ZIP

                // Valida se arquivo é realmente ZIP
                if (!extension_loaded('zip')) {
                    return array(
                        0,
                        0,
                        "Nao esta habilitado php_zip nas configuracoes do PHP (php.ini)"
                    );
                }
                
                // Valida se ocorreu erro no upload do arquivo
                if (empty($mArquivo["tmp_name"])) {
                    return array(
                        0,
                        0,
                        "Upload não pode ser concluido, provavelmente o tamanho do arquivo tenha excedido o limite padrão definido nos parametros do PHP. Diminua o tamanho do arquivo."
                    );
                }
                
                $dir = $g['pathDadosUsuario'] . "arq_temp/";
                is_dir($dir) OR mkdir($dir, 0777, true);
                $cArquivoTemp = $g['pathDadosUsuario'] . "arq_temp/" . basename($cArquivo);
                if (!@move_uploaded_file($mArquivo["tmp_name"], $cArquivoTemp)) {
                    return array(
                        0,
                        0,
                        "Erro ao tentar copiar arquivo temporario: " . $mArquivo['tmp_name'] . "para: " . $cArquivoTemp
                    );
                }
                
                $zip = zip_open($cArquivoTemp);
                if ($zip) {

                    $retorno = 'Sem XML encontrados no ZIP.';
                    //-- INICIA UMA TRANSAÇÃO NO BANCO DE DADOS

                    while ($zip_entry = zip_read($zip)) {
                        $arquivo = basename(zip_entry_name($zip_entry));
                        
                        if (strtoupper(substr($arquivo, -4)) == '.XML') {
                            
                            $fp = fopen($g['pathDadosUsuario'] . "arq_temp/" . basename($arquivo), "w+");
                            if (zip_entry_open($zip, $zip_entry, "r")) {
                                $buf = zip_entry_read($zip_entry, zip_entry_filesize($zip_entry));
                                zip_entry_close($zip_entry);
                            }
                            fwrite($fp, $buf);
                            fclose($fp);

                            mysql_query("SET AUTOCOMMIT=0");
                            mysql_query("START TRANSACTION");
                            $retorno = $this->importarXml($buf, $arquivo, 'S', $cadastrarProdutos, $geraContasReceber);
                            if ($retorno === true) {
                                $relatorio[] = true;
                            } else {
                                if (is_array($retorno)) {
                                    $relatorio[] = $retorno;
                                } else {
                                    $relatorio[] = basename($cArquivo) . ' -- ' . $retorno;
                                }
                            }
                            mysql_query("COMMIT");

                        } else {
                            
                            $relatorio[] = 'Erro, não é arquivo XML.';

                        }
                    }
                    zip_close($zip);
                    
                    $zip = zip_open($cArquivoTemp);
                    
                    // Faz um novo looping em todos os xml para verificar se existe alguma nota de cancelamento para executar o cancelamento
                    while ($zip_entry = zip_read($zip)) {
                        $arquivo = basename(zip_entry_name($zip_entry));
                        
                        if (strtoupper(substr($arquivo, -4)) == '.XML') {
                            
                            if (zip_entry_open($zip, $zip_entry, "r")) {
                                $buf = zip_entry_read($zip_entry, zip_entry_filesize($zip_entry));
                                zip_entry_close($zip_entry);
                            }
                            mysql_query("SET AUTOCOMMIT=0");
                            mysql_query("START TRANSACTION");
                            $retorno = $this->cancelarNotasImportadas($buf, $arquivo, 'S');
                            if ($retorno) {
                                $relatorioCance[] = $retorno === true ? true : basename($arquivo) . ' -- ' . $retorno;
                            }
                            mysql_query("COMMIT");
                        } else {
                            $relatorio[] = 'Erro, não é arquivo XML.';
                        }
                    }
                    
                }
                zip_close($zip);
                
            } else {
                //-- ABRE O ARQUIVO XML
                $Ponteiro      = fopen($mArquivo["tmp_name"], "r");
                $cConteudo_XML = fread($Ponteiro, filesize($mArquivo["tmp_name"]));
                
                //-- INICIA UMA TRANSA��O NO BANCO DE DADOS
                mysql_query("SET AUTOCOMMIT=0");
                mysql_query("START TRANSACTION");
                
                // O $dados somente será enviado caso o tipo do processo de importação seja do fulfillment
                // O parâmetro $ids é populado por referência, e retornado, para saber qual produto precisa o ter estoque atualizado
                $retorno = $this->importarXml($cConteudo_XML, $cArquivo, 'N', $cadastrarProdutos, $geraContasReceber, $dados, $ids);
                if ($retorno === true) {
                    $relatorio[] = true;
                } else {
                    if (is_array($retorno)) {
                        $relatorio[] = $retorno;
                    } else {
                        $relatorio[] = basename($cArquivo) . ' -- ' . $retorno;
                    }
                }
                mysql_query("COMMIT");

                mysql_query("SET AUTOCOMMIT=0");
                mysql_query("START TRANSACTION");
                $retorno = $this->cancelarNotasImportadas($cConteudo_XML, $arquivo, 'S');
                if ($retorno) {
                    $relatorioCance[] = $retorno === true ? true : basename($arquivo) . ' -- ' . $retorno;
                }
                mysql_query("COMMIT");

            }
            $erro               = 0;
            $ok                 = 0;
            $msgErro            = '';
            $logCFOPCadastradas = '';
            foreach ($relatorio as $key => $value) {
                
                if (is_array($value)) {
                    if ($value !== true) {
                        $ok++;
                        foreach ($value as $key => $linhaCFOP) {
                            $logCFOPCadastradas .= $linhaCFOP . "\\n";
                        }
                    } else {
                        $erro++;
                        $msgErro .= $value . "\\n";
                    }
                } else {
                    if ($value === true) {
                        $ok++;
                    } else {
                        $erro++;
                        $msgErro .= $value . "\\n";
                    }
                }
            }
            
            $erroCance    = 0;
            $okCance      = 0;
            $msgErroCance = '';
            foreach ($relatorioCance as $key => $value) {
                if ($value !== true) {
                    $erroCance++;
                    $msgErroCance .= $value . "\\n";
                } else {
                    $okCance++;
                }
            }
            return array(
                $ok,
                $erro,
                $msgErro,
                $okCance,
                $erroCance,
                $msgErroCance,
                $logCFOPCadastradas,
                $ids
            );
            
        }
        
        /**
         * cancelarNotasImportadas
         *
         * @param File $cConteudo_XML
         * @param File $cArquivo
         * @param String $TipoZip
         * @return String/bool
         */        
        public function cancelarNotasImportadas($cConteudo_XML, $cArquivo, $TipoZip)
        {
            global $g;
            // Require da classe CAD002 para reprocessar o histórico
            require_once('bibliotecas/classes/CAD002.php');
            $CAD002 = new CAD002();
           
            //-- INSTANCIA A CLASSE "DOM" DO PHP PARA LER OS "NÓS" DO XML
            $dom = new \DomDocument;
            @$dom->loadXML($cConteudo_XML);
            
            $retEvento  = $dom->getElementsByTagName("infEvento")->item(0);
            if (!empty($retEvento)){
                $xEvento    = $retEvento->getElementsByTagName("xEvento")->item(0);
            }
            
            if ($retEvento != null && $xEvento = 'Cancelamento') {

                $chNFe    = utf8_decode($retEvento->getElementsByTagName("chNFe")->item(0)->nodeValue);
                $nProt    = utf8_decode($retEvento->getElementsByTagName("nProt")->item(0)->nodeValue);
                $xMotivo  = utf8_decode($retEvento->getElementsByTagName("xMotivo")->item(0)->nodeValue);
                if (empty($nProt)) {
                    return "XML Cancelamento {$chNFe} não possui protocolo de cancelamento";
                }
                
                $T007 = mysql_query("SELECT * FROM T007 WHERE T007_Chave_Acesso_Nfe='{$chNFe}' AND T007_C004_Id='{$g['empresaAtual']}'");
                if (mysql_num_rows($T007) <= 0) {
                    return "XML Cancelamento {$chNFe} NFe não encontrada";
                }
                $mT007 = mysql_fetch_array($T007);
                if ($mT007['T007_Flag_Cancelada'] == "S") {
                    return "XML Cancelamento {$chNFe} Nota já cancelada";
                }

                $upT007   = <<<EOT
                                UPDATE T007 SET 
                                    T007_Flag_Cancelada='S',
                                    T007_Data_Hora_Cancelamento_Nfe='{$dhRecbto}',
                                    T007_Numero_Protocolo_Cancelamento_Nfe='{$nProt}',
                                    T007_Observacao_Cancelamento='{$xMotivo}'
                                WHERE 
                                T007_Id='{$mT007['T007_Id']}';
EOT;
                mysql_query($upT007);
                $erro     = mysql_error();
                if ($erro) {
                    mysql_query("ROLLBACK");
                    return $erro;
                }
                
                $T008 = mysql_query("SELECT * FROM T008 WHERE T008_T007_Id='{$mT007['T007_Id']}'");
                // Percorrendo todos os produtos da nota para cancelar o histórico
                while ($mT008 = mysql_fetch_array($T008)) {
                    $upHist       = <<<EOT
				UPDATE T001 SET T001_Flag_Operacao='C' WHERE T001_T008_Id='{$mT008['T008_Id']}';
EOT;
                    $resultUpHist = mysql_query($upHist);
                    $erro         = mysql_error();
                    if ($erro) {
                        mysql_query("ROLLBACK");
                        return $erro;
                    }
                    $CAD002->D001_reprocessa_historico(0, $mT008['T008_D009_Id']);
                }
                return true;
            } else {
                return false;
            }
        }
        
        /**
         * importarXml
         *
         * @param File $cConteudo_XML
         * @param File $cArquivo
         * @param String $TipoZip
         * @return String/bool
         */        
        public function importarXml($cConteudo_XML, $cArquivo=null, $TipoZip=null, $cadastrarProdutos=null, $geraContasReceber=null, $dados=null, &$ids=null)
        {
            global $g;

            $cConteudo_XML = $this->normalizarConteudoXml($cConteudo_XML);
            
            //-- INSTANCIA A CLASSE "DOM" DO PHP PARA LER OS "N�S" DO XML
            $dom = new \DomDocument;
            @$dom->loadXML($cConteudo_XML);
            
            $protNFe = $dom->getElementsByTagName("protNFe")->item(0);
            $evento  = $dom->getElementsByTagName("evento")->item(0);
            if (!empty($protNFe)) {
                $Protocolo = $protNFe->getElementsByTagName("nProt")->item(0);
                if (empty($Protocolo)) {
                    return "Este XML não possui protocolo de autorização: " . $cArquivo . ", favor verificar.";
                }
                $Protocolo = $protNFe->getElementsByTagName("nProt")->item(0)->nodeValue;
                if (empty($Protocolo)) {
