                            T001_Valor_PIS, T001_Aliquota_COFINS,
                            {$colunasFulfillment} 
                            T001_D006_Id, T001_Valor_COFINS,
                            T001_T007_Id) 
                        (SELECT 
                            T007_Data_Emissao, {$descricao}, 
                            T008_Quantidade, {$flag_operacao},
                            T008_Valor_Preco_Unitario, D006_Flag_Devolucao, 
                            T007_D024_Id, T008_D009_Id, 
                            {$T066_Id_query}, T008_Id, D006_Flag_MMF, 
                            (T008_Valor_ICMS_Substituicao_Retencao / T008_Quantidade), (T008_Valor_ICMS / T008_Quantidade), 
                            T008_Aliquota_ICMS, (T008_Valor_IPI / T008_Quantidade), 
                            T008_Aliquota_IPI, (T008_Valor_ICMS_Substituicao_Retencao / T008_Quantidade), 
                            (((T008_Valor_ICMS_Substituicao_Retencao / T008_Quantidade) / T008_Valor_Preco_Unitario) * 100), T008_Aliquota_PIS, 
                            (T008_Valor_PIS / T008_Quantidade), T008_Aliquota_COFINS, 
                            {$valoresFulfillment}
                            T008_D006_Id, (T008_Valor_COFINS / T008_Quantidade),
                            T007_Id
                        FROM 
                            T008 
                            LEFT JOIN T007 ON T007_Id = T008_T007_Id 
                            LEFT JOIN D006 ON D006_Id = T008_D006_Id 
                            LEFT JOIN T001 ON T001_T008_Id = T008_Id 
                            LEFT JOIN D009 ON D009_Id = T008_D009_Id 
                            LEFT JOIN T066 ON T066_D009_Id = D009_Id 
                        WHERE 
                            T008_T007_Id = '$nT007_Id' 
                            AND IFNULL(T001_Id, 0) <= 0 
                            AND D006_Flag_Entrada_Saida != 'N' 
                        GROUP BY 
                            T008_Id)";

                        mysql_query($T001_1);                                      
                        $cErro = mysql_error();
                        echo $cErro;
