                    mysql_query("ROLLBACK");
                    return "Não foi possível continuar, o arquivo:" . $cArquivoSalvar . "Não pode ser salvo. Verique as permissões na pasta do arquivo";
                }
            }

            $nTotal_Importados++;
            if ($novaCFOP == true) {
                return $logCFOPCadastrada;
            } else {
                return true;
            }
        }

