        /**
         * cadastrarCFOP
         *
         * @param String $cfop
         * @param String $desc
         * @param String $vICMS
         * @param String $iCST
         * @param String $vIPI
         * @param String $vPIS
         * @param String $pCST
         * @param String $vCOFINS
         * @param String $cCST
         * @return String
         */        
        public function cadastrarCFOP($cfop, $desc, $vICMS, $iCST, $vIPI, $vPIS, $pCST, $vCOFINS, $cCST, $CFOPContraPartida='')
        {
            global $g;
            $digito = substr($cfop, 0, 1);
            if ($digito == '1' || $digito == '2' || $digito == '3') {
                $ordem = "E";
            } else if ($digito == '6' || $digito == '7' || $digito == '8') {
                $ordem = "S";
            }
            
            if ($digito == '1' || $digito == '5') {
                $estado = "D";
            } else if ($digito == '2' || $digito == '6') {
                $estado = "F";
            } else if ($digito == '3' || $digito == '7') {
                $estado = "I";
            }
            
            if ($vICMS > 0) {
                $isentoICMS = "N";
            } else {
                $isentoICMS = "S";
            }
            
            if ($vIPI > 0) {
                $isentoIPI = "N";
            } else {
                $isentoIPI = "S";
            }
            
            if ($vPIS > 0) {
                $isentoPIS = "N";
            } else {
                $isentoPIS = "S";
            }
            
            if ($vCOFINS > 0) {
                $isentoCOFINS = "N";
            } else {
                $isentoCOFINS = "S";
            }
            
            $D059    = mysql_query("SELECT D059_Id FROM D059 WHERE D059_Codigo_ST = '{$iCST}'");
            $D059    = mysql_fetch_array($D059);
            $D059_Id = $D059[0];
            
            $dados = "";
            $dados .= "D006_Codigo_CFOP " . $cfop . "<br/>";
            $dados .= "D006_Descricao " . $desc . "<br/>";
            $dados .= "D006_Flag_Entrada_Saida " . $ordem . "<br/>";
            $dados .= "D006_Flag_Estado " . $estado . "<br/>";
            $dados .= "D006_Flag_Devolucao: ver CFOP <br/>";
            $dados .= "D006_Flag_Venda_Compra_Outros: ver CFOP<br/>";
            $dados .= "D006_Flag_Inativo: N<br/>";
            $dados .= "D006_Flag_Isento_ICMS " . $isentoICMS . "<br/>";
            $dados .= "D006_D059_Id " . $D059_Id . "<br/>";
            $dados .= "D006_Flag_Isento_IPI " . $isentoIPI . "<br/>";
            
            $dados .= "D006_Flag_Isento_PIS " . $isentoPIS . "<br/>";
            $dados .= "D006_Situacao_Tributaria_PIS " . $pCST . "<br/>";
            
            $dados .= "D006_Flag_Isento_COFINS " . $isentoCOFINS . "<br/>";
            $dados .= "D006_Situacao_Tributaria_COFINS " . $cCST . "<br/>";
            
            $D006 = "";
            $D006 .= "INSERT INTO D006 (";
            $D006 .= "	D006_Codigo_CFOP,";
            $D006 .= "	D006_Descricao,";
            $D006 .= "	D006_Flag_Entrada_Saida,";
            $D006 .= "	D006_Flag_Estado,";
            $D006 .= "	D006_Flag_Inativo,";
            $D006 .= "	D006_Flag_Isento_ICMS,";
            $D006 .= "	D006_D059_Id,";
            $D006 .= "	D006_Flag_Isento_IPI,";
            $D006 .= "	D006_Flag_Substituicao_Tributaria,";
            $D006 .= "	D006_Flag_Isento_PIS,";
            $D006 .= "	D006_Situacao_Tributaria_PIS,";
            $D006 .= "	D006_Flag_Isento_COFINS,";
            $D006 .= "	D006_Situacao_Tributaria_COFINS,";
            $D006 .= "	D006_Flag_Estoque,";
            $D006 .= "	D006_Flag_Gera_Contas,";
            $D006 .= "	D006_Flag_Retorno,";
            $D006 .= "	D006_Flag_Somar_IPI_Base_ICMS,";
            $D006 .= "	D006_Flag_ST_VA,";
            $D006 .= "	D006_Codigo_CFOP_Contra_Partida,";
            $D006 .= "	D006_Flag_Somar_Despesas_Base_ST";
            $D006 .= "	) VALUES (";
            $D006 .= "	'{$cfop}',";
            $D006 .= "	'{$desc}',";
            $D006 .= "	'{$ordem}',";
            $D006 .= "	'{$estado}',";
            $D006 .= "	'N',";
            $D006 .= "	'{$isentoICMS}',";
            $D006 .= "	'{$D059_Id}',";
            $D006 .= "	'{$isentoIPI}',";
            
            if ($iCST == "40") {
                $D006 .= "	'N',";
            } else {
                $D006 .= "	'S',";
            }
            $D006 .= "	'{$isentoPIS}',";
            $D006 .= "	'{$pCST}',";
            $D006 .= "	'{$isentoCOFINS}',";
            $D006 .= "	'{$cCST}',";
            $D006 .= "	'N',";
            $D006 .= "	'N',";
            $D006 .= "	'N',";
            $D006 .= "	'N',";
            $D006 .= "	'N',";
            $D006 .= "	'{$CFOPContraPartida}',";
            $D006 .= "	'N'";
            $D006 .= "   )";
            mysql_query($D006);
            $erro = mysql_error();
            if(!empty($erro)){
                log("Erro ao cadastrar CFOP SQL = " . $D006);
            }
            return $g['mysqlLastId'];
        }
        
       /**
         * importarTXT
         *
         * @param File $arquivo
         * @return String/bool/array
         */        
        public function importarTXT($arquivo, $cadastrarProdutos, $calcularTotalProduto)
        {
            global $g;
            
            $mArquivo      = $arquivo;
            $cArquivo      = $mArquivo["name"];
            $cTipo_Arquivo = StrToLower($cTipo_Arquivo);
            $cTipo_Arquivo = substr($cArquivo, strrpos($cArquivo, ".") + 1, 3);
            $cTipo_Arquivo = StrToLower($cTipo_Arquivo);
            
            if (empty($cArquivo)) {
                return "Selecione o arquivo!";
            }
            
            if ($cTipo_Arquivo != 'txt' ) {
                return "O arquivo deve estar no formato TXT! ";
                
            }

            //echo "Abrindo arquivo <br>".$mArquivo["tmp_name"];
            
            //-- ABRE O ARQUIVO XML
            $Ponteiro = fopen($mArquivo["tmp_name"], "r");
            
            if (!$Ponteiro) {
                return false;
            }
            $primeiraNota = true;

            //-- INICIA UMA TRANSA��O NO BANCO DE DADOS
