                $errosLinhasCabecalho .= '----------------------------------------------------------------------------\\n\\n';                
                return $errosLinhasCabecalho.$errosLinhas;
            } else {
                return 'NOTAS FISCAIS IMPORTADAS COM SUSCESSO:: '.$totalNotasImportadas;
            }

        }       
        /**
         * ven003AtualizarParcelas
         *
         * @param String $T118_Id
         * @param String $campoEditado
         * @param String $valorAntigo
         * @param String $novoValor
         * @return String/bool
         */        
        public function ven003AtualizarParcelas($T118_Id, $campoEditado, $valorAntigo, $novoValor)
        {
            
            $query            = "SELECT * FROM T118 LEFT JOIN T007 ON T118_T007_Id='{$T118_Id}' WHERE T118_Id='{$T118_Id}'";
            $retorno          = mysql_query($query);
            $linha            = mysql_fetch_assoc($retorno);
            $dataVelhaT007    = $linha['T007_Data_Emissao'];
            $prazosDiasAntigo = $linha['T118_Prazos_Dias'];
            
            if ($campoEditado == 'T118_Prazos_Dias') {
                // if($valorAntigo == $novoValor){
                // return "O prazo é o mesmo";
                // }
                
                $date = new \DateTime($dataVelhaT007);
                $date->modify('+' . $novoValor . ' days');
                $query = "UPDATE T118 SET T118_Data_Vencimento='{$date->format('Y-m-d')}' WHERE T118_Id='{$T118_Id}'";
                mysql_query($query);
            } else if ($campoEditado == 'T118_Data_Vencimento') {
                
                $dataAntiga = gCorrigeDataInverte($valorAntigo);
                $dataNova   = gCorrigeDataInverte($novoValor);
                
                $timeStampDataNova   = strtotime($dataNova);
                $timeStampDataAntiga = strtotime($dataAntiga);
                
                
                if ($timeStampDataAntiga == $timeStampDataNova) {
                    return 'Datas Iguais';
                } else if ($timeStampDataAntiga < $timeStampDataNova) {
                    $novaData = ($timeStampDataNova - $timeStampDataAntiga);
                    $dias     = date('d', $novaData);
                    
                    $total = ($prazosDiasAntigo + $dias);
                    $query = "UPDATE T118 SET T118_Prazos_Dias='{$total}' WHERE T118_Id='{$T118_Id}'";
                    mysql_query($query);
                    return true;
                } else if ($timeStampDataAntiga > $timeStampDataNova) {
                    $novaData = ($timeStampDataAntiga - $timeStampDataNova);
                    $dias     = date('d', $novaData);
                    $total    = ($prazosDiasAntigo - $dias);
                    $query    = "UPDATE T118 SET T118_Prazos_Dias='{$total}' WHERE T118_Id='{$T118_Id}'";
                    mysql_query($query);
                    return true;
                }
                
            } else if ($campoEditado == 'T118_Valor_Parcela') {
                
                $query      = "SELECT * FROM T118 WHERE T118_Id='{$T118_Id}'";
                $retorno    = mysql_query($query);
                $linha      = mysql_fetch_assoc($retorno);
                $T007_Id    = $linha['T118_T007_Id'];
                $numParcela = $linha['T118_Numero_Parcela'];
                
                $query      = "SELECT T007_Valor_Total FROM T007 WHERE T007_Id='{$T007_Id}'";
                $retorno    = mysql_query($query);
                $linha      = mysql_fetch_assoc($retorno);
                $valorTotal = $linha['T007_Valor_Total'];
                
                $query                  = "SELECT SUM(T118_Valor_Parcela) FROM T118 WHERE T118_T007_Id='{$T007_Id}' AND T118_Numero_Parcela<='{$numParcela}'";
                $retorno                = mysql_query($query);
                $linha                  = mysql_fetch_assoc($retorno);
                $valorParcelasRestantes = $linha['SUM(T118_Valor_Parcela)'];
                $valorRestante          = $valorTotal - $valorParcelasRestantes;
                
                $query                  = "SELECT * FROM T118 WHERE T118_T007_Id='{$T007_Id}' AND T118_Numero_Parcela>'{$numParcela}'";
                $retorno                = mysql_query($query);
                $parcelasRestantes      = mysql_num_rows($retorno);
                $valorParcelasRestantes = $valorRestante / $parcelasRestantes;
                if ($valorParcelasRestantes < 0) {
                    $query = "UPDATE T118 SET T118_Valor_Parcela='{$valorAntigo}' WHERE T118_Id='{$T118_Id}'";
                    mysql_query($query);
                    return 'O valor inserido irá gerar parcelas negativas...<br>Favor alterar novamente';
                }
                //return 'valorTotal='.$valorTotal.'<br>valorRestante='.$valorRestante.'<br>ValorParcelasRestantes='.$valorParcelasRestantes;
                while ($linha = mysql_fetch_assoc($retorno)) {
                    $query = "UPDATE T118 SET T118_Valor_Parcela='{$valorParcelasRestantes}' WHERE T118_Id='{$linha['T118_Id']}'";
                    mysql_query($query);
                }
                
                return true;
                
            }
            
            return true;
        }
        
