            }

            //Retorna os erros dos produtos
            if(!empty($errosProduto)){
                $errosProduto = "<b><font style='color:red'>NOTA NÃO FINALIZADA, VERIFICAR ERROS ABAIXO: </font></b><br>" . $errosProduto;
                return $errosProduto;
            }

            
            //$retorno = $this->continuarLiberacao($T007_Id);
            //return $retorno;
            return true;
        }

        /**
         * validarEstoqueNotaFiscal
         *
         * Para NF manual/devolução sem vínculo com pedido, valida o saldo da locação
         * selecionada antes de finalizar a nota. Se não houver T066, utiliza o saldo
         * líquido do D009 como contingência.
         *
         * @param array $mT007
         * @return true|string
         */
        public function validarEstoqueNotaFiscal($mT007)
        {
            global $g;

            if (!empty($mT007['T007_T005_Id'])) {
                return true;
            }

            if ($g['C031']['permitirFinalizarNotaSemEstoque'] == 'S') {
                return true;
            } 
            
            $sql = <<<EOT
                SELECT T008_D009_Id,
                       IFNULL(T008_T066_Id, 0) AS T008_T066_Id,
                       D001_Codigo_Produto,
                       T008_Descricao_Produto,
                       SUM(T008_Quantidade) AS T008_Quantidade,
                       IFNULL(T066_Quantidade_Estoque_Liquido, D009_Quantidade_Estoque_Liquido) AS Estoque_Disponivel,
                       IFNULL(T066_Id, 0) AS T066_Id,
                       D004_Local
                  FROM T008
             LEFT JOIN D006 ON D006_Id = T008_D006_Id
             LEFT JOIN D009 ON D009_Id = T008_D009_Id
             LEFT JOIN D049 ON D049_Id = D009_D049_Id
             LEFT JOIN D001 ON D001_Id = D049_D001_Id
             LEFT JOIN T066 ON T066_Id = T008_T066_Id
             LEFT JOIN D004 ON D004_Id = T066_D004_Id
             LEFT JOIN T001 ON T008_Id = T001_T008_Id
                 WHERE T008_T007_Id = '{$mT007['T007_Id']}'
                   AND T008_Quantidade > 0
                   AND D006_Flag_Estoque = 'D'
                   AND IFNULL(T008_T006_Id, 0) = 0
                   AND IFNULL(T001_Id, 0) = 0
              GROUP BY T008_D009_Id,
                       IFNULL(T008_T066_Id, 0)
                HAVING SUM(T008_Quantidade) > Estoque_Disponivel
EOT;
            $resValidacao = mysql_query($sql);
            if (mysql_error()) {
                return mysql_error();
            }

            $itensSemEstoque = array();
            while ($row = mysql_fetch_assoc($resValidacao)) {
                $quantidadeSolicitada = gCorrigeNumero($row['T008_Quantidade']);
                $estoqueDisponivel    = gCorrigeNumero($row['Estoque_Disponivel']);

                if (!empty($row['T066_Id'])) {
                    $local = !empty($row['D004_Local']) ? " <b>LOCAÇÃO: {$row['D004_Local']}</b>" : '';
                    $itensSemEstoque[] = "{$row['D001_Codigo_Produto']} - {$row['T008_Descricao_Produto']}: {$local} Disponível: {$estoqueDisponivel} / Solicitado: {$quantidadeSolicitada}";
                } else {
                    $itensSemEstoque[] = "{$row['D001_Codigo_Produto']} - {$row['T008_Descricao_Produto']} - Disponível: {$estoqueDisponivel} / Solicitado: {$quantidadeSolicitada}";
                }
            }

            if (!empty($itensSemEstoque)) {
                return "Existem itens sem estoque suficiente para finalizar a NF.<br><br>" . implode("<br>", $itensSemEstoque);
            }

            return true;
        }

