        /**
         * continuarLiberacao
         *
         * @param String $T007_Id
         * @return String/bool
         */        
        public function continuarLiberacao($T007_Id)
        {
            global $g;
            require_once("bibliotecas/classes/VEN012.php");
            $VEN012 = new VEN012();
            require_once('bibliotecas/classes/FIN001.php');
            $FIN001 = new FIN001();

            //ESSE ID VEIO FIXO DO SCRIPT DO SISTEMA ANTIGO
            $D048_Id = 1;
            
            //esse select deve possuir asterisco para que que pegue todos os campos e substitua os valores na observação da cfop
            $cSql_T007 = mysql_query("SELECT *
                                        FROM T007
                                        LEFT JOIN T008 ON T007_Id=T008_T007_Id
                                        LEFT JOIN D024 ON D024_Id=T007_D024_Id
                                        LEFT JOIN D018 ON D018_Id=D024_D018_Id
                                        LEFT JOIN D006 ON D006_Id=T007_D006_Id
                                        LEFT JOIN C007 ON C007_Id=T007_C007_Id_Vendedor_Interno
                                        LEFT JOIN D024A ON D024_Id=D024A_D024_Id
                                        WHERE T007_Id='{$T007_Id}'");
            $mT007     = mysql_fetch_array($cSql_T007);

            if (!empty($mT007['T007_D148_Id_Entrega'])) {
                $sqlEntrega = mysql_query("SELECT D148_Nome,
                                                  D148_Rua,
                                                  D148_Numero,
                                                  D148_Bairro,
                                                  D148_Cnpj,
                                                  D148_Cpf,
                                                  D148_D018_Id,
                                                  D148_D020_Id,
                                                  D148_D030_Id,
                                                  D020_Nome_Cidade,
                                                  D018_UF
                                             FROM D148
                                        LEFT JOIN D020 ON D020_Id = D148_D020_Id
                                        LEFT JOIN D018 ON D018_Id = D148_D018_Id
                                            WHERE D148_Id = '{$mT007['T007_D148_Id_Entrega']}'");
                $mEntrega = mysql_fetch_array($sqlEntrega);

                $camposEntregaObrigatorios = array();
                if (empty($mEntrega['D148_Nome'])) {
                    $camposEntregaObrigatorios[] = 'nome';
                }
                if (empty($mEntrega['D148_Cnpj']) && empty($mEntrega['D148_Cpf'])) {
                    $camposEntregaObrigatorios[] = 'CPF/CNPJ';
                }
                if (empty($mEntrega['D148_Rua'])) {
                    $camposEntregaObrigatorios[] = 'logradouro';
                }
                if (empty($mEntrega['D148_Numero'])) {
                    $camposEntregaObrigatorios[] = 'numero';
                }
                if (empty($mEntrega['D148_Bairro'])) {
                    $camposEntregaObrigatorios[] = 'bairro';
                }
                if (empty($mEntrega['D148_D020_Id']) || empty($mEntrega['D020_Nome_Cidade'])) {
                    $camposEntregaObrigatorios[] = 'cidade';
                }
                if (empty($mEntrega['D148_D018_Id']) || empty($mEntrega['D018_UF'])) {
                    $camposEntregaObrigatorios[] = 'UF';
                }
                if (empty($mEntrega['D148_D030_Id'])) {
                    $camposEntregaObrigatorios[] = 'pais';
                }

                if (!empty($camposEntregaObrigatorios)) {
                    return "O endereço de entrega selecionado está com campos obrigatórios para NF-e não preenchidos: " . implode(', ', $camposEntregaObrigatorios) . ".";
                }
            }
            
            $cC004 = mysql_query("SELECT C004_Ambiente_NFe,
                                         C004_Banco_Dados,
                                         C004_Cnpj,
                                         C004_Codigo_Regime_Tributario,
                                         C004_Observacao_Fiscal,
                                         C004_Ultimo_Numero_Nota_Fiscal_Eletronica,
                                         C004_Ultimo_Numero_NFCe,     
                                         C004_Ultimo_Numero_ACP,
                                         C004_Ultimo_Numero_Cupom_Fiscal,
                                         C004_Ultimo_Numero_Nota_Fiscal
                                    FROM C004 
                                   WHERE C004_Id='{$mT007['T007_C004_Id']}'");
            $mC004 = mysql_fetch_array($cC004);
            
            // $cC020 = mysql_query("SELECT * FROM C020 WHERE C020_C004_Id='{$mT007['T007_C004_Id']}'");
            // $mC020 = mysql_fetch_array($cC020);
            /*
            //-- OBSERVACAO: DESENVOLVER SCRIPT PARA MUDAR O NUMERO DE SERIE CASO O TOTAL DE NOTAS ULTRAPASSE 999.999.999 (nossa!!!)
            if ($mC004['C004_Ambiente_NFe'] == '3') {
                $mC004['C004_Ambiente_NFe'] = '1';
                $nNumero_Serie              = 900;
            } else {
                $nNumero_Serie = 1;
            }
            */
                       
            mysql_query("SET AUTOCOMMIT=0");
            mysql_query("START TRANSACTION");
            
            // ************************************************************************************************************************
            // Exclui qualquer Estoque, Títulos, Boletos, etc (a nota pode estar sendo refeita)
            // ************************************************************************************************************************
            //Verifica se a nota fiscal possuí uma remessa bancária
            $sqlT007 = mysql_query("SELECT T007_Id 
                                      FROM T007 
                                 LEFT JOIN T002 ON T002_T007_Id = T007_Id 
                                     WHERE T007_Id = '{$T007_Id}' 
                                       AND T002_T035_Id > 0 AND T002_Flag_Cancelada !='S'");
            if (mysql_num_rows($sqlT007) > 0) {
                return (mysql_num_rows($sqlT007) > 1) ? "Existem títulos a receber que estão em remessa bancária, por favor verifique." : "Existe título a receber que está em remessa bancária, por favor verifique.";
            }
            
            $sqlT002 = mysql_query("SELECT T002_Id 
                                      FROM T002 
                                     WHERE T002_T007_Id != '{$T007_Id}' 
                                       AND IFNULL(T002_T117_Id)>0 
                                       AND T002_T117_Id IN (SELECT DISTINCT T002_T117_Id FROM T002 WHERE T002_T007_Id = '{$T007_Id}')");
            if (mysql_num_rows($sqlT002) > 0) {
                return (mysql_num_rows($sqlT002) > 1) ? "Existem boletos que estão relacionados a outras notas fiscais, por favor verifique." : "Existe boleto relacionado a outra nota fiscal, por favor verifique.";
            }
            
            $cClausula = "DELETE FROM T001 WHERE T001_T007_Id='{$T007_Id}'";
            mysql_query($cClausula);
            $cErro = mysql_error();
            if (!empty($cErro)) {
                mysql_query("ROLLBACK");
                return "Erro: $cErro <br /><br /> $cClausula";
            }
            
            $sqlT002 = mysql_query("SELECT DISTINCT T002_T117_Id FROM T002 WHERE T002_T007_Id = '{$T007_Id}' AND T002_T117_Id > 0");
            while ($T002 = mysql_fetch_array($sqlT002)) {
                mysql_query("DELETE FROM T117 WHERE T117_Id = '{$T002['T002_T117_Id']}'");
                if (mysql_error()) {
                    mysql_query("ROLLBACK");
                    return "Erro: " . mysql_error();
                }
            }

            $sqlT002 = mysql_query("SELECT T002_Id FROM T002 WHERE T002_T007_Id = '{$T007_Id}'");
            while ($mT002 = mysql_fetch_array($sqlT002)) {
                mysql_query("DELETE FROM T019 WHERE T019_T002_Id = '{$mT002['T002_Id']}'");
                if (mysql_error()) {
                    mysql_query("ROLLBACK");
                    return "Erro: " . mysql_error();
                }
            }
            
            $cClausula = "DELETE FROM T002 WHERE T002_T007_Id = '{$T007_Id}'";
            mysql_query($cClausula);
            $cErro = mysql_error();
            if (!empty($cErro)) {
                mysql_query("ROLLBACK");
                return "Erro: $cErro <br /><br /> $cClausula";
            }

            $cClausula = "DELETE FROM T015 WHERE T015_T007_Id='{$T007_Id}'";
            mysql_query($cClausula);
            $cErro = mysql_error();
            if (!empty($cErro)) {
                mysql_query("ROLLBACK");
                return "Erro: $cErro <br /><br /> $cClausula";
            }
            
            $cClausula = "DELETE FROM T019 WHERE T019_T007_Id='{$T007_Id}'";
            mysql_query($cClausula);
            $cErro = mysql_error();
            if (!empty($cErro)) {
                mysql_query("ROLLBACK");
                return "Erro: $cErro<br /><br />$cClausula";
            }

            //Atualiza a CFOP do cabeçalho com a CFOP do primeiro produto
            $sqlT008 = mysql_query("SELECT T008_D006_Id FROM T008 WHERE T008_T007_Id = '{$T007_Id}' LIMIT 1");
            $rowT008 = mysql_fetch_array($sqlT008);
            mysql_query("UPDATE T007 SET T007_D006_Id = '{$rowT008['T008_D006_Id']}' WHERE T007_Id = '{$T007_Id}'");
            // ************************************************************************************************************************
            
            if (empty($mT007['T007_Numero_Nota_Fiscal'])) {
                
                //retorna a proxima numeração e série da nota fiscal
                $proximoNumeroSerie = $VEN012->retornaProximaNF($mT007['T007_Flag_ACP'], $mT007['T007_C004_Id']);

                list($proximoNumero,$retorno1) = $proximoNumeroSerie;
                if($proximoNumero === false){
                    return $retorno1;
                }
                
                if ($mT007['T007_Flag_ACP'] == 6) {

                    $dataFiltroNota     = strtotime("-15 day", strtotime(date("Y-m-d")));
                    $dataFiltroNota = date("Y-m-d", $dataFiltroNota);

                    $notaf = mysql_query("SELECT T007_Numero_Nota_Fiscal, 
                                                 T007_Empresa_Usuaria_Cnpj,
                                                 T007_Data_Emissao
                                            FROM T007
                                           WHERE T007_Data_Emissao >= '{$dataFiltroNota}'
                                             AND T007_Flag_ACP='6'
                                             AND T007_C004_Id='{$mT007['T007_C004_Id']}'
                                             AND T007_Serie='{$retorno1}'
                                             AND T007_Flag_Emitida_Recebida!='R'
                                             AND round(T007_Numero_Nota_Fiscal) > 0
                                        ORDER BY round(T007_Numero_Nota_Fiscal) DESC LIMIT 1");
        
                    if (mysql_num_rows($notaf) <= 0) {

                        $dataFiltroNota = strtotime("-30 day", strtotime(date("Y-m-d")));
                        $dataFiltroNota = date("Y-m-d", $dataFiltroNota);
                        $notaf = mysql_query("SELECT T007_Numero_Nota_Fiscal, 
                                                     T007_Empresa_Usuaria_Cnpj,
                                                     T007_Data_Emissao
                                                FROM T007
                                               WHERE T007_Data_Emissao >= '{$dataFiltroNota}'
                                                 AND T007_Flag_ACP='6'
                                                 AND T007_C004_Id='{$mT007['T007_C004_Id']}'
                                                 AND T007_Serie='{$retorno1}'
                                                 AND T007_Flag_Emitida_Recebida!='R'
                                            ORDER BY round(T007_Numero_Nota_Fiscal) DESC LIMIT 1");
                    }
                    
                    $mT007_Numero = mysql_fetch_array($notaf);

                    $sqlCheckDB                = mysql_query("SELECT DATABASE()");
                    $rowCheckDB                = mysql_fetch_array($sqlCheckDB);
                    $dbCheck                   = strtolower($rowCheckDB[0]);
                    $dbCheck                   = str_replace('_novo', '', $dbCheck); //Removendo _novo da base das empresa que foram atualizadas
                    $C004dbCheck               = strtolower($mC004['C004_Banco_Dados']);
                    $C004dbCheck               = str_replace('_novo', '', $C004dbCheck);
                    $C004_Cnpj                 = str_replace(array(".","-","/"), "", $mC004['C004_Cnpj']);
                    $T007_Empresa_Usuaria_Cnpj = str_replace(array(".","-","/"), "", $mT007_Numero['T007_Empresa_Usuaria_Cnpj']);

                    if(($C004_Cnpj != $T007_Empresa_Usuaria_Cnpj && !empty($mT007_Numero['T007_Numero_Nota_Fiscal']))){
                        return "O CNPJ da última nota fiscal emitida (".$T007_Empresa_Usuaria_Cnpj.") está diferente do CNPJ (".$C004_Cnpj.") do cadastro da empresa. Verifique!";
                    }
        
                    //VP36 - se o banco de dados aberto for diferente do que esta configurado na empresa
                    if($C004dbCheck != $dbCheck){
                        return "O banco de dados atual (".$dbCheck.") é diferente do banco de dados configurado nesta empresa (".$C004dbCheck."). Informar o suporte técnico.";
                    }
                }

                mysql_query("UPDATE T007 SET T007_Numero_Nota_Fiscal='{$proximoNumero}', T007_Serie='{$retorno1}'  WHERE T007_Id='{$T007_Id}'");
                $cErro = mysql_error();
                if (!empty($cErro)) {
                    return 'Erro: ' . $cErro;
                }
            }
            
            //////////////////////////////////////////////////////////////////////////////////////
            //-- VALIDACAO DA CFOP, VERIFICA SE TODAS AS CFOPS ESTAO GERANDO CONTAS OU NAO
            //////////////////////////////////////////////////////////////////////////////////////
            
            $cSql_T008_CFOP = mysql_query("SELECT D006_Flag_Gera_Contas, 
                                                  D006_D014_Id, 
                                                  D006_D073_Id 
                                             FROM T008 
                                        LEFT JOIN D006 ON D006_Id=T008_D006_Id 
                                            WHERE T008_T007_Id='{$T007_Id}' 
                                         GROUP BY D006_Flag_Gera_Contas");
            $cErro          = mysql_error();
            if (!empty($cErro)) {
                return 'Erro: ' . $cErro;
            }
            if (mysql_num_rows($cSql_T008_CFOP) == 0) {
                $cSql_T008_CFOP = mysql_query("SELECT D006_Flag_Gera_Contas, 
                                                      D006_D014_Id, 
                                                      D006_D073_Id 
                                                 FROM T007 
                                            LEFT JOIN D006 ON D006_Id=T007_D006_Id 
                                                WHERE T007_Id='{$T007_Id}' 
                                             GROUP BY D006_Flag_Gera_Contas");
                $cErro          = mysql_error();
                if (!empty($cErro)) {
                    return 'Erro: ' . $cErro;
                }
            }

            if (mysql_num_rows($cSql_T008_CFOP) > 1) {
                return "Foi selecionada mais de uma CFOP com o parametro gerar contas DIFERENTE";
            } else {
                $mT008_CFOP        = mysql_fetch_array($cSql_T008_CFOP);
                $cFlag_Gera_Contas = $mT008_CFOP['D006_Flag_Gera_Contas'];

                if($mT008_CFOP['D006_Flag_Gera_Contas'] == 'P' && (empty($mT008_CFOP['D006_D073_Id']) || $mT008_CFOP['D006_D073_Id'] <= 0)) {
                    mysql_query("ROLLBACK");
                    return "A CFOP gera contas a pagar e está sem um centro de custo definido! Verifique o cadastro da CFOP.";
                } else {
                    $CentroCusto = $mT008_CFOP['D006_D073_Id'];
                }

                if(($mT008_CFOP['D006_Flag_Gera_Contas'] == 'P' || $mT008_CFOP['D006_Flag_Gera_Contas'] == 'R') && (empty($mT008_CFOP['D006_D014_Id']) || $mT008_CFOP['D006_D014_Id'] <= 0)){
                    $tipoConta = ($mT008_CFOP['D006_Flag_Gera_Contas'] == 'P') ? 'pagar' : 'receber';
                    mysql_query("ROLLBACK");
                    return "A CFOP gera contas a {$tipoConta} e está sem uma conta definida! Verifique o cadastro da CFOP.";
                } else {
                    $Conta = $mT008_CFOP['D006_D014_Id'];
                    $sqlD032 = mysql_query("SELECT D014_D032_Id FROM D014 WHERE D014_Id = '{$Conta}'");
                    $D032 = mysql_fetch_array($sqlD032);
                    $Grupo = $D032['D014_D032_Id'];
                }
            }
            
            if (($cFlag_Gera_Contas != 'N') AND ($cFlag_Gera_Contas != 'P') AND ($cFlag_Gera_Contas != 'R')) {
                return "O campo: D006_Flag_Gera_Contas (" . $cFlag_Gera_Contas . ") está incorreto";
            }
            
            
            //////////////////////////////////////////////////////////////////////////////////////
            // INCLUSAO DOS ITENS NO HISTORICO
            //////////////////////////////////////////////////////////////////////////////////////
            
            $resT008   = mysql_query("SELECT D006_Flag_Atualiza_Custo,
                                             D006_Flag_Credita_IPI,
                                             D006_Flag_Estoque,
                                             D006_Flag_MMF,
                                             D006_Observacao_Produto,
                                             D009_Id,
                                             D049_D024_Id,   
                                             T007_D024_Id,
                                             T007_Id,
                                             T007_Numero_Nota_Fiscal,
                                             T008_Aliquota_COFINS,
                                             T008_Aliquota_ICMS,  
                                             T008_Aliquota_IPI,  
                                             T008_Aliquota_PIS,
                                             T008_C004_Id,
                                             T008_Codigo_Produto,
                                             T008_D009_Id,
                                             T008_Id,
                                             T008_Percentual_Reducao_ICMS,    
                                             T008_Percentual_Reducao_IPI,
                                             T008_Quantidade,
                                             T008_T006_Id,    
                                             T008_T055_Id,   
                                             T008_T066_Id,
                                             T008_Valor_Acrescimo_Custo,
                                             T008_Valor_Base_ICMS,    
                                             T008_Valor_Base_IPI,
                                             T008_Valor_COFINS,
                                             T008_Valor_Custo_Unitario,
                                             T008_Valor_Desconto_Unitario,
                                             T008_Valor_Despesas_Acessorias_Unitario,
                                             T008_Valor_Frete_Unitario,
                                             T008_Valor_ICMS,
                                             T008_Valor_ICMS_Substituicao,
                                             T008_Valor_ICMS_Substituicao_Retencao,  
                                             T008_Valor_ICMS_Substituicao_Unitario,
                                             T008_Valor_IPI, 
                                             T008_Valor_PIS,
                                             T008_Valor_Preco_Sem_Desconto_Unitario,
                                             T008_Valor_Preco_Unitario,   
                                             T008_Valor_Total_Desconto,   
                                             T008_Valor_Total_Despesas_Acessorias,
                                             T008_Valor_Total_Frete,  
                                             T008_Valor_Total_Preco, 
                                             T008_Valor_Total_Seguro,  
                                             D009_Custo_Unitario(D009_Id) Custo_Unitario, 
                                             (D009_Custo_Unitario(D009_Id)*T008_Quantidade) Custo_Total, 
                                             D009_Local(D009_Id,1) Local_1,
                                             T008_Valor_Base_ICMS_Substituicao_Retido,
                                             T008_Valor_ICMS_Substituicao_Retido,
                                             T008_Informacoes_Adicionais,
                                             T008_Valor_FCP,
                                             T008_Valor_FCP_ST,
                                             T006_Flag_Pdv_Importado,
                                             T290_Valor_Base_ICMS_Substituicao AS T008_BC_ICMS_ST_Compra, 
				                             T290_Valor_ICMS_Substituicao AS T008_Valor_ICMS_ST_Compra,
                                             T008_Numero_Pedido_Compra,
                                             T008_Item_Pedido_Compra,
                                             T008_Codigo_Cliente,
                                             T008_Codigo_Substituto,
                                             T008_T008_Id
                                        FROM T008
                                   LEFT JOIN T007 ON T007_Id=T008_T007_Id
                                   LEFT JOIN D009 ON D009_Id=T008_D009_Id
                                   LEFT JOIN D049 ON D049_Id=D009_D049_Id
                                   LEFT JOIN D001 ON D001_Id=D049_D001_Id
                                   LEFT JOIN D006 ON D006_Id=T008_D006_Id
                                   LEFT JOIN T006 ON T006_Id=T008_T006_Id
                                   LEFT JOIN T290 ON T008_Id=T290_T008_Id
                                       WHERE T008_T007_Id='{$T007_Id}'
                                         AND T008_Quantidade>0
                                    GROUP BY T008_Id
                                    ORDER BY Local_1,T008_Id");
            $cErro = mysql_error();
