                mysql_query("UPDATE T007 SET T007_Observacao_Nota_Fiscal_1 = '{$Observacao_Fiscal}' WHERE T007_Id = '{$T007_Id}'");
            }
            
            // Verifica se vai escriturar no SPED Contribuições no último ponto antes de travar a nota
            $sqlContribuicoes = mysql_query("SELECT T008_Id FROM T008 LEFT JOIN D006 ON D006_Id = T008_D006_Id WHERE T008_T007_Id = '{$T007_Id}' AND D006_Flag_Escritura_Sped_Contribuicoes = 'S' LIMIT 1");

