            $camposEspeciaisRTC = [
                'T008A_Valor_IBS_Transferido' => $zT008A_Valor_IBS_Transferido,
                'T008A_Valor_CBS_Transferido' => $zT008A_Valor_CBS_Transferido,
                'T008A_Competencia_Ajuste' => $zT008A_Competencia_Ajuste,
                'T008A_Valor_IBS_Ajuste_Competencia' => $zT008A_Valor_IBS_Ajuste_Competencia,
                'T008A_Valor_CBS_Ajuste_Competencia' => $zT008A_Valor_CBS_Ajuste_Competencia,
                'T008A_Valor_IBS_Estornado' => $zT008A_Valor_IBS_Estornado,
                'T008A_Valor_CBS_Estornado' => $zT008A_Valor_CBS_Estornado,
            ];
