                    continue;
                }
                if ($campoRTC === 'T008A_Competencia_Ajuste') {
                    $valorRTC = trim($valorRTC);
                } else {
                    $valorRTC = trim((string) $valorRTC) === '' ? '0' : formata_valor_gravar($valorRTC, 3);
                }
                $atribuicoesEspeciaisRTC[] = $campoRTC . "='" . mysql_real_escape_string($valorRTC) . "'";
            }
            if ($atribuicoesEspeciaisRTC) {
                $cClausula = 'UPDATE T008A SET ' . implode(', ', $atribuicoesEspeciaisRTC)
                    . " WHERE T008A_T008_Id='$T008_Id'";
                if (!mysql_query($cClausula)) {
                    return 'Erro ao gravar os valores especiais de IBS/CBS: ' . mysql_error();
                }
            }
            // END NFDC CAMPOS ESPECIAIS

            $cSql = mysql_query("call T008_Gravar_Totalizacao_4('$T008_Id');");

