                mysqli_query("CALL T008_Gravar_Totalizacao_4('{$T008_Id}')");
                mysql_query("UPDATE T008 SET T008_Valor_Preco_Sem_Desconto_Unitario = T008_Valor_Preco_Sem_Desconto_Unitario/((T008_Valor_Preco_Sem_Desconto_Unitario+(T008_Valor_IPI/T008_Quantidade)+(T008_Valor_ICMS_Substituicao_Retencao/T008_Quantidade))/T008_Valor_Preco_Sem_Desconto_Unitario) WHERE T008_Id = '{$T008_Id}'");
                mysqli_query("CALL T008_Gravar_Totalizacao_4('{$T008_Id}')");
            }

            // O cabeçalho deve refletir o último recálculo, inclusive no preço bruto.
            $cSql = mysql_query("call T007_Gravar_Totalizacao_4('$T008_T007_Id');");
            if ($atribuicoesEspeciaisRTC) {
                $retornoTotaisRTC = $this->totalizarValoresEspeciaisNFDebitoCredito($T008_T007_Id);
                if ($retornoTotaisRTC !== true) {
                    return $retornoTotaisRTC;
                }
            }

            return true;
        }

        public function gerarCertificadoQualidade($T007_Id = 0, $numeroNotaFiscal){
            global $g;

            $dirPDF = $g['pathDados'] . 'anexosEmail/';
            //$fileName = $dirPDF .md5($T007_Id.time()).'.pdf';
            $fileName = $dirPDF .'Certificado_NF_'.$numeroNotaFiscal.'.pdf';
            $acaoId = '3e9f26159a86b0a1b80acc91544f4000';
            $link = "/sistema/personalizacao/outro/3e9f26159a86b0a1b80acc91544f4000/?ajax=true&acaoId=$T007_Id";
            $url = gGerarUrlBackend('/sistema/personalizacaoLowCode/grid_func-ajax/telaGerarPdf/',
                                    "&acaoId={$acaoId}&link=" . urlencode($link) . "&salvarNoArquivo=" . urlencode($fileName) . "&marginTop=2&marginLeft=2&marginRight=2&marginBottom=2&pdfAltura=210&pdfLargura=297"
            );

            file_get_contents($url);

            if (!file_exists($fileName)) {
                return "Erro ao gerar e salvar o PDF.";
            } else {
                //$pdfs[] = $fileName;
                return $fileName;
            }            
        }
        
        /**
         * montarEmail
         *
         * @param String $T007_Id
         * @return array
         */
        public function montarEmail($T007_Id)
        {
            global $g, $confUsuario;

            $Dir = $g['pathDados'] . 'tmp/';
            is_dir($Dir) or mkdir($Dir, 0777, true);
            $arquivoNome = "{$Dir}MailDANFE-T007-{$T007_Id}.txt";
            //@unlink($arquivoNome);
            $h = fopen($arquivoNome, 'w');
            $data="Entrou montarE-mail\n";
            $r = fwrite($h, $data);

            $data="Parametros gerarDanfe: T007_Id:{$T007_Id}\n cArquivoXML:{$cArquivoXML}\n";

            $T007_Id = mysql_real_escape_string($T007_Id);
            // T007_Id, D024_Id, D024_Nome_Empresa, D024_E_Mail, T007_Numero_Protocolo_Nfe, T007_Data_Emissao
            $sql     = "SELECT * FROM T007 LEFT JOIN D024 ON D024_Id=T007_D024_Id WHERE T007_Id='{$T007_Id}'";
            $T007    = mysqli_query($sql);
            $T007    = mysql_fetch_array($T007);
            log("Sql= ". $sql);

            $data="Select T007 " . $sql . " \n";
            $r = fwrite($h, $data);

            $array            = array();
            $array['Para']    = (!empty($T007['D024_E_Mail_Nota'])) ? $T007['D024_E_Mail_Nota'] : $T007['D024_E_Mail'];
            if($g['C031']['NFeModificarTituloEmail'] == 'S'){
                $array['Assunto'] = "Aviso de Faturamento - Nota Fiscal Nº[{$T007['T007_Numero_Nota_Fiscal']}]";    
            }else{
                $array['Assunto'] = "Nota Fiscal Nº[{$T007['T007_Numero_Nota_Fiscal']}]";
            }
            
            $array['D024_Id'] = $T007['D024_Id'];
            $array['Anexos']  = array();

            if($g['C031']['NFeEnviarEmailTransportadora'] == 'S'){
                $dadosTransportadora = mysql_query("select D022_Fax from D022 where D022_Id = '{$T007['T007_D022_Id']}'");
                if(mysql_num_rows($dadosTransportadora) > 0){
                    $varTransportadora   = mysql_fetch_array($dadosTransportadora);
                    if(!is_null($varTransportadora['D022_Email']) && !empty($varTransportadora['D022_Email'])){
                        $array['Para'] .= ", " . $varTransportadora['D022_Email'];
                    }else if(!is_null($varTransportadora['D022_Fax']) && !empty($varTransportadora['D022_Fax'])){
                        $array['Para'] .= ", " . $varTransportadora['D022_Fax'];
                    }
                }
            }

            if($g['C031']['NFeEnviarEmailVendedorInterno'] == 'S'){
                $dadosVendedorInterno = mysql_query("select C007_Email from C007 where C007_Id = '{$T007['T007_C007_Id_Vendedor_Interno']}'");
                if(mysql_num_rows($dadosVendedorInterno) > 0){
                    $varVendedorInterno   = mysql_fetch_array($dadosVendedorInterno);
                    if(!is_null($varVendedorInterno['C007_Email']) && !empty($varVendedorInterno['C007_Email'])){
                        $array['Para'] .= ", " . $varVendedorInterno['C007_Email'];
                    }
                }
            }

            if($g['C031']['NFeEnviarEmailRepresentante'] == 'S'){
                $dadosRepresentante = mysql_query("select D021_Nome_Fantasia 
                                                    from D021
                                                    left join T007 on T007_D021_Id = D021_Id
                                                    where 
                                                        T007_Id = '{$T007_Id}'");
                if(mysql_num_rows($dadosRepresentante) > 0){
                    $varRepresentante   = mysql_fetch_array($dadosRepresentante);
                    if(!is_null($varRepresentante['D021_Nome_Fantasia']) && !empty($varRepresentante['D021_Nome_Fantasia'])){
                        $array['Para'] .= ", " . $varRepresentante['D021_Nome_Fantasia'];
                    }
                }
            }

            if($g['C031']['NFeEnviarEmailPessoaProposta'] == 'S'){
                $dadosPessoaProposta  = mysql_query("select 
                                                        D024_E_Mail_Nota, 
                                                        D024_E_Mail 
                                                    from 
                                                        D024
                                                    left join T007A on T007A_D024_Id = D024_Id
                                                    where
                                                        T007A_T007_Id = '{$T007_Id}'");
                if(mysql_num_rows($dadosPessoaProposta) > 0){
                    $varPessoaProposta    = mysql_fetch_array($dadosPessoaProposta);
                    if(!is_null($varPessoaProposta['D024_E_Mail_Nota']) && !empty($varPessoaProposta['D024_E_Mail_Nota'])){
                        $array['Para'] .= ", " . $varPessoaProposta['D024_E_Mail_Nota'];
                    }else if(!is_null($varPessoaProposta['D024_E_Mail']) && !empty($varPessoaProposta['D024_E_Mail'])){
                        $array['Para'] .= ", " . $varPessoaProposta['D024_E_Mail'];
                    }
                }
            }

            if($g['C031']['anexoEmailCertificadoQualidade'] == 'S'){

                $dadosCliente = mysqli_query("select T007_Id
                                                from T007
                                           left join D024   on T007_D024_Id   = D024_Id
                                           left join D024A  on D024A_D024_Id  = D024_Id
                                           left join T008   on T008_T007_Id   = T007_Id
                                           left join D009   on T008_D009_Id   = D009_Id
                                           left join D049   on D009_D049_Id   = D049_Id
                                           left join D001   on D049_D001_Id   = D001_Id
                                           left join CQP001 on CQP001_D001_Id = D001_Id
                                               where T007_Id = '{$T007_Id}'
                                                 and D024A_Flag_Certificado_Qualidade = 'S'
                                                 and coalesce(CQP001_D001_Id, 0) > 0");

                if(mysqli_num_rows($dadosCliente) > 0){
                    $pdfCertificado = $this->gerarCertificadoQualidade($T007_Id,$T007['T007_Numero_Nota_Fiscal']);
                    if (file_exists($pdfCertificado)) {
                        $array['Anexos'][] = $pdfCertificado;
                    }
                }                
            }

            // Contatos da Empresa
            $array['cc'] = '';
            if (isset($g['C031'])) {
                $NFeEnviarEmailIncluirContatosCC = $g['C031']['NFeEnviarEmailIncluirContatosCC'];
            } else {
                $NFeEnviarEmailIncluirContatosCC = '';
            }
            if (empty($NFeEnviarEmailIncluirContatosCC) || $NFeEnviarEmailIncluirContatosCC == 'S') {
                $sql = "SELECT D013_E_Mail FROM D013 WHERE D013_D024_Id='{$T007['D024_Id']}';";
                $res = mysqli_query($sql);
                while ($row = mysql_fetch_assoc($res)) {
                    if (!empty($row['D013_E_Mail'])) {
                        $array['cc'] .= empty($array['cc']) ? $row['D013_E_Mail'] : '; ' . $row['D013_E_Mail'];
                    }
                }
            }

            $data = "Contatos  " . $NFeEnviarEmailIncluirContatosCC . " \n";
            $r = fwrite($h, $data);

            $cAno_Mes_NFe  = substr($T007['T007_Data_Emissao'], 0, 7);
            $Diretorio_NFe = $g['pathDadosAntigo'] . 'nfe';
            //-- $Diretorio_Usuario � definido no arquivo include/pasta_usuario.inc
