            $data .= "Arquivo  " . $cArquivo . " \n";
            $r = fwrite($h, $data);

            if (file_exists($cArquivo)) {
                $array['Anexos'][] = $cArquivo;
            } else {
                return 'XML da nota fiscal não encontrado';
            }

            $data .= "file_exists?  \n";
            $r = fwrite($h, $data);

            $retorno = $this->gerarDanfe($T007_Id, $cArquivo);
            $data .= $retorno . "<<<< <br />" . $cArquivo ."\n";
            $r = fwrite($h, $data);
            
            log($retorno . "<<<< <br />" . $cArquivo);
            if (file_exists($retorno)) {
                log("Anexou");
                $array['Anexos'][] = $retorno;
            } else {
                return 'Falha ao gerar DANFE';
            } 
            $data .= $retorno . "file_exists retorno  \n";
            $r = fwrite($h, $data);

            // Verifica se tem cancelamentos
            if (!empty($T007['T007_Numero_Protocolo_Cancelamento_Nfe'])) {
                $cArquivoProtocolado = "$Diretorio_NFe/xml/autorizado/ID{$T007['T007_Numero_Protocolo_Cancelamento_Nfe']}.xml";
                // modelo novo, depois das alterações do evantoni
                if (!file_exists($cArquivoProtocolado)) {
                    $zenSeqEvento        = str_pad(1, 2, "0", STR_PAD_LEFT);
                    $tpEvento            = '110111';
                    $cArquivoProtocolado = "$Diretorio_NFe/xml/cancelado/ID{$tpEvento}{$T007['T007_Chave_Acesso_Nfe']}{$zenSeqEvento}.xml";
                }
                if (file_exists($cArquivoProtocolado)) {
                    $array['Anexos'][] = $cArquivoProtocolado;
                }
            }

            $data .= "T007_Numero_Protocolo_Cancelamento_Nfe:".$T007['T007_Numero_Protocolo_Cancelamento_Nfe']."\n";
            $r = fwrite($h, $data);
            
            //Verifica se há cartas de correção para esta NFe
            $sqlCce = mysqli_query("SELECT T199_Id FROM T199 WHERE T199_T007_Id='{$T007_Id}' AND T199_Flag_Enviado='S'");
            while ($rowCce = mysql_fetch_array($sqlCce)) {
                $retornoCce        = $this->montarEmailPdfCce($rowCce['T199_Id']);
                $array['Anexos'][] = $retornoCce['Anexos'][0];
                $array['Anexos'][] = $retornoCce['Anexos'][1];
            }
            $data .= "Select Cartas de correção:SELECT T199_Id FROM T199 WHERE T199_T007_Id='{$T007_Id}' AND T199_Flag_Enviado='S'\n";
            $r = fwrite($h, $data);
            
            // Corpo
            $array['Corpo']         = $T007['D024_Nome_Empresa'] . ',';
            $Protocolo_Cancelamento = '';
            if (!empty($T007['T007_Numero_Protocolo_Cancelamento_Nfe'])) {
                $Protocolo_Cancelamento = "\n<br />Protocolo de Cancelamento: {$T007['T007_Numero_Protocolo_Cancelamento_Nfe']}";            
            }
            $data .= "Protocolo cancelamento:".$Protocolo_Cancelamento."\n";
            $r = fwrite($h, $data);
            
            if (mysql_num_rows($sqlCce) > 0) {
                $array['Corpo'] = "{$T007['D024_Nome_Empresa']},\n\n<br /><br />Segue em anexo arquivo XML, DANFE e Carta(s) de Correções referente a NF-e: $T007[T007_Numero_Nota_Fiscal]\n\n<br /><br />Empresa: $T007[T007_Empresa_Usuaria_Nome]\n<br />CNPJ: $T007[T007_Empresa_Usuaria_Cnpj]\n\n<br /><br />Chave de Acesso: $T007[T007_Chave_Acesso_Nfe]\n<br />Protocolo de Autorização: $T007[T007_Numero_Protocolo_Nfe] {$Protocolo_Cancelamento}";
            } else {
                $array['Corpo'] = "{$T007['D024_Nome_Empresa']},\n\n<br /><br />Segue em anexo arquivo XML e o DANFE referente a NF-e: $T007[T007_Numero_Nota_Fiscal]\n\n<br /><br />Empresa: $T007[T007_Empresa_Usuaria_Nome]\n<br />CNPJ: $T007[T007_Empresa_Usuaria_Cnpj]\n\n<br /><br />Chave de Acesso: $T007[T007_Chave_Acesso_Nfe]\n<br />Protocolo de Autorização: $T007[T007_Numero_Protocolo_Nfe] {$Protocolo_Cancelamento}";
            }
            //$array['Corpo'] = "Envio do XML via e-mail.<br/><br/>Debug: {$cArquivo}<br/>Debug2: " . '$cArquivo = "$Diretorio_NFe/xml/autorizado/{$cAno_Mes_NFe}/$T007[T007_Numero_Protocolo_Nfe].xml";';
            $data .= "Finalizando função montar email\n\n array de retorno:".json_encode($array)."\n";
            $r = fwrite($h, $data);
            return $array;
        }

        public function montarEmailACP($T007_Id)
        {
            global $g, $confUsuario;

            $T007_Id = mysql_real_escape_string($T007_Id);
            // T007_Id, D024_Id, D024_Nome_Empresa, D024_E_Mail, T007_Numero_Protocolo_Nfe, T007_Data_Emissao
            $sql     = "SELECT * FROM T007 LEFT JOIN D024 ON D024_Id=T007_D024_Id WHERE T007_Id='{$T007_Id}'";
            log("SQL = ".$sql);
            $T007    = mysqli_query($sql);
            $T007    = mysql_fetch_array($T007);
            $T007_Flag_Acp = $T007['T007_Flag_ACP'];

            log("T007_Id = ". $T007_Id);
            $array            = array();
            $array['Para']    = (!empty($T007['D024_E_Mail_Nota'])) ? $T007['D024_E_Mail_Nota'] : $T007['D024_E_Mail'];
            $array['Assunto'] = "ACP Nº[{$T007['T007_Numero_Nota_Fiscal']}]";
            $array['D024_Id'] = $T007['D024_Id'];
            $array['T007_Flag_ACP'] = $T007['T007_Flag_ACP'];
            $array['Anexos']  = array();
            log("Array Para: ".$array['Para']);

            // Contatos da Empresa
            $array['cc'] = '';
            if (isset($g['C031'])) {
                $NFeEnviarEmailIncluirContatosCC = $g['C031']['NFeEnviarEmailIncluirContatosCC'];
            } else {
                $NFeEnviarEmailIncluirContatosCC = '';
            }
            if (empty($NFeEnviarEmailIncluirContatosCC) || $NFeEnviarEmailIncluirContatosCC == 'S') {
                $sql = "SELECT D013_E_Mail FROM D013 WHERE D013_D024_Id='{$T007['D024_Id']}';";
                $res = mysqli_query($sql);
                while ($row = mysql_fetch_assoc($res)) {
                    if (!empty($row['D013_E_Mail'])) {
                        $array['cc'] .= empty($array['cc']) ? $row['D013_E_Mail'] : '; ' . $row['D013_E_Mail'];
                    }
                }
            }

            $retorno = $this->gerarACP($T007_Id);
            if(file_exists($retorno)) {
                $array['Anexos'][] = $retorno;
            } else {
                return 'Falha ao gerar ACP';
            }

            //Corpo do email
            $array['Corpo']       = <<<EOT
                {$T007['D024_Nome_Empresa']},\n\n<br />
                <br/>Segue em anexo arquivo pdf referente a ACP: $T007[T007_Numero_Nota_Fiscal]\n\n<br /><br />Empresa: $T007[T007_Empresa_Usuaria_Nome]\n<br />CNPJ: $T007[T007_Empresa_Usuaria_Cnpj]\n\n<br />
EOT;

            return $array;
        }
        
        /**
         * atualizarAliquotasNF
         *
         * @param String $T007_Id
         * @return String/bool
         */
        public function atualizarAliquotasNF($T007_Id, $novaNFDebitoCredito = false)
        {
            global $g;
            require_once('bibliotecas/classes/FIS003.php');
            $FIS003 = new FIS003();

            $cSql_T007 = mysql_query("SELECT * FROM T007 WHERE T007_Id='$T007_Id'");
            $mT007     = mysql_fetch_array($cSql_T007);
            $cError    = mysql_error();

            if (!empty($cError)) {
                return "Erro: {$cError}";
            }

            /*if ($mT007['T007_Flag_Impresso']=='S'){
            return "NOTA JA FOI IMPRESSA";
            }*/

            if (!empty($mT007['T007_Numero_Protocolo_Nfe'])) {
                return "Esta NF-e tem protocolo de autorização, nao pode ser alterada";
            }

            if (!empty($mT007['T007_Numero_Recibo_Nfe'])) {
                return "Esta NF-e tem recibo, nao pode ser alterada";
            }

            if (!empty($mT007['T007_Chave_Acesso_Nfe'])) {
                return "Esta NF-e tem chave de acesso, nao pode ser alterada";
            }

            $cClausula = "SELECT *
                	        FROM T007
                	        LEFT JOIN T008 ON T007_Id=T008_T007_Id
                	        LEFT JOIN D009 ON D009_Id=T008_D009_Id
                			LEFT JOIN D049 ON D049_Id=D009_D049_Id
                			LEFT JOIN D001 ON D001_Id=D049_D001_Id
                            LEFT JOIN D005 ON D005_Id=T008_D005_Id
                            LEFT JOIN D006 ON D006_Id= T008_D006_Id
                            LEFT JOIN T008A ON T008_Id=T008A_T008_Id
                            LEFT JOIN D184 ON D184_Id=T008A_D184_Id
	                        WHERE T007_Id='{$T007_Id}'";
            $cSql_T008 = mysql_query($cClausula);
            $cError    = mysql_error();
            if (!empty($cError)) {
                return "Erro: {$cError}";
            }

            while ($mT008 = mysql_fetch_array($cSql_T008)) {

                if ($mT008['T008_Flag_Calculo_Manual'] == "S") {
                    continue;
                }

                require_once("bibliotecas/classes/VEN001.php");
                $VEN001 = new VEN001();

                $Aliquotas = $VEN001->retornaAliquotas($mT008['T008_D009_Id'], false, false, $T007_Id, false, false, $mT008['T008_Id']);
                if (!is_array($Aliquotas)) {
                    return "Erro no método retorna Alíquotas. Erro: " . $Aliquotas;
                }

                if($mT008['D006_Flag_Unidade_Tributavel'] == 'N' || empty($mT008['D005_D037_Id_Tributavel'])){
                    $unidadeTributavel = $mT008['D001_D037_Id'];
                    if($mT008['T008A_D184_Id'] > 0 && $mT008['D184_D037_Id'] > 0){
                        // Se tiver unidade conversao, usa ela
                        $unidadeTributavel = $mT008['D184_D037_Id'];
                    }
                    $mT008['D005_D037_Id_Tributavel'] = $unidadeTributavel;
                }

                // Buscando o percentual de tributos (lei transparências)			
                $D149  = mysql_query("SELECT D149_Percentual_Trib_Transparencia FROM D149 WHERE D149_Id='{$Aliquotas['D149_Id']}'");
                $mD149 = mysql_fetch_array($D149);

                $D006  = mysql_query("SELECT D006_Percentual_Trib_Transparencia FROM D006 WHERE D006_Id='{$mT008['T008_D006_Id']}'");
                $mD006 = mysql_fetch_array($D006);

                if (!empty($mD149['D149_Percentual_Trib_Transparencia']) AND $mD149['D149_Percentual_Trib_Transparencia'] > 0) {
                    $T008_Percentual_Trib_Transparencia = $mD149['D149_Percentual_Trib_Transparencia'];
                } else if (!empty($mD006['D006_Percentual_Trib_Transparencia']) AND $mD006['D006_Percentual_Trib_Transparencia'] > 0) {
                    $T008_Percentual_Trib_Transparencia = $mD006['D006_Percentual_Trib_Transparencia'];
                } else {
                    $T008_Percentual_Trib_Transparencia = 0;
                }

                $demonstrativoNCM = $FIS003->demonstrativoNCM($Aliquotas['D005_Id']);
