                }
                mysql_query("call T008_Gravar_Totalizacao_4('{$mT008['T008_Id']}')");
                $cError = mysql_error();
                if (!empty($cError)) {
                    return "Erro: $cError";
                }
                
            }
            
            mysql_query("call T007_Gravar_Totalizacao_4('{$T007_Id}')");
            $cError = mysql_error();
            if (!empty($cError)) {
                return "Erro: $cError";
            }
            return true;
        }

        /**
         * Preenche somente os campos da reforma tributária da NF sem recalcular os demais impostos.
         *
         * @param int $T007_Id
         * @return bool|string
         */
        public function atualizarCamposReformaTributariaNF($T007_Id)
        {
            $cSql_T007 = mysql_query("SELECT T007_Id, T007_C004_Id
                                        FROM T007
                                       WHERE T007_Id='{$T007_Id}'");
            $mT007     = mysql_fetch_array($cSql_T007);
            $cError    = mysql_error();
            if (!empty($cError)) {
                return "Erro: {$cError}";
            }

            if (empty($mT007['T007_Id'])) {
                return "NF não encontrada para atualizar os campos da reforma tributária.";
            }

            $C004 = mysql_query("SELECT C004_Flag_Tipo_Preenchimento_Reforma_Tributaria
                                   FROM C004
                                  WHERE C004_Id = '{$mT007['T007_C004_Id']}'");
            $mC004 = mysql_fetch_array($C004);
            $cError = mysql_error();
            if (!empty($cError)) {
                return "Erro: {$cError}";
            }

            if ($mC004['C004_Flag_Tipo_Preenchimento_Reforma_Tributaria'] != '1') {
                return true;
            }

            require_once('bibliotecas/classes/ReformaTributaria.php');
            $reformaTributaria = new ReformaTributaria();

            $cSql_T008 = mysql_query("SELECT T008_Id, T008_D005_Id, T008_D006_Id
                                        FROM T008
                                       WHERE T008_T007_Id='{$T007_Id}'");
            $cError = mysql_error();
            if (!empty($cError)) {
                return "Erro: {$cError}";
            }

            while ($mT008 = mysql_fetch_array($cSql_T008)) {
                $D006 = mysql_query("SELECT D006_Situacao_Tributaria_CBS_IBS,
                                            D006_Classificacao_Tributaria_CBS_IBS,
                                            D006_Situacao_Tributaria_CBS_IBS_Regular,
                                            D006_Classificacao_Tributaria_CBS_IBS_Regular
                                       FROM D006
                                      WHERE D006_Id = '{$mT008['T008_D006_Id']}'");
                $mD006 = mysql_fetch_array($D006);
                $cError = mysql_error();
                if (!empty($cError)) {
                    return "Erro: {$cError}";
                }

                $D005 = mysql_query("SELECT D005_Situacao_Tributaria_CBS_IBS,
                                            D005_Classificacao_Tributaria_CBS_IBS,
                                            D005_Situacao_Tributaria_CBS_IBS_Regular,
                                            D005_Classificacao_Tributaria_CBS_IBS_Regular
                                       FROM D005
                                      WHERE D005_Id = '{$mT008['T008_D005_Id']}'");
                $mD005 = mysql_fetch_array($D005);
                $cError = mysql_error();
                if (!empty($cError)) {
                    return "Erro: {$cError}";
                }

                $situacaoCBSIBS = '';
                $classificacaoCBSIBS = '';
                $situacaoCBSIBSRegular = '';
                $classificacaoCBSIBSRegular = '';

                if (!empty($mD006['D006_Situacao_Tributaria_CBS_IBS']) && !empty($mD006['D006_Classificacao_Tributaria_CBS_IBS'])) {
                    $situacaoCBSIBS = $mD006['D006_Situacao_Tributaria_CBS_IBS'];
                    $classificacaoCBSIBS = $mD006['D006_Classificacao_Tributaria_CBS_IBS'];
                    $situacaoCBSIBSRegular = $mD006['D006_Situacao_Tributaria_CBS_IBS_Regular'];
                    $classificacaoCBSIBSRegular = $mD006['D006_Classificacao_Tributaria_CBS_IBS_Regular'];
                } else {
                    $situacaoCBSIBS = $mD005['D005_Situacao_Tributaria_CBS_IBS'];
                    $classificacaoCBSIBS = $mD005['D005_Classificacao_Tributaria_CBS_IBS'];
                    $situacaoCBSIBSRegular = $mD005['D005_Situacao_Tributaria_CBS_IBS_Regular'];
                    $classificacaoCBSIBSRegular = $mD005['D005_Classificacao_Tributaria_CBS_IBS_Regular'];
                }

                $aliquotasReformaTributaria = $reformaTributaria->getAliquotas($classificacaoCBSIBS ?? "");
                $aliquotasReformaTributariaRegular = $reformaTributaria->getAliquotas($classificacaoCBSIBSRegular ?? "");

                $Aliquotas = array(
                    'Situacao_Tributaria_CBS_IBS' => $situacaoCBSIBS,
                    'Classificacao_Tributaria_CBS_IBS' => $classificacaoCBSIBS,
                    'Aliquota_CBS' => $aliquotasReformaTributaria['aliquotaCbs'] ?? 0,
                    'Aliquota_IBS_UF' => $aliquotasReformaTributaria['aliquotaIbsUf'] ?? 0,
                    'Aliquota_IBS_Municipal' => $aliquotasReformaTributaria['aliquotaIbsMunicipal'] ?? 0,
                    'Percentual_Reducao_CBS' => $aliquotasReformaTributaria['percentualReducaoCbs'] ?? 0,
                    'Percentual_Reducao_IBS_UF' => $aliquotasReformaTributaria['percentualReducaoIbsUf'] ?? 0,
                    'Percentual_Reducao_IBS_Municipal' => $aliquotasReformaTributaria['percentualReducaoIbsMunicipal'] ?? 0,
                    'Percentual_Diferimento_CBS' => $aliquotasReformaTributaria['percentualDiferimentoCbs'] ?? 0,
                    'Percentual_Diferimento_IBS_UF' => $aliquotasReformaTributaria['percentualDiferimentoIbsUf'] ?? 0,
                    'Percentual_Diferimento_IBS_Municipal' => $aliquotasReformaTributaria['percentualDiferimentoIbsMunicipal'] ?? 0,
                    'Situacao_Tributaria_CBS_IBS_Regular' => $situacaoCBSIBSRegular,
                    'Classificacao_Tributaria_CBS_IBS_Regular' => $classificacaoCBSIBSRegular,
                    'Aliquota_CBS_Regular' => $aliquotasReformaTributariaRegular['aliquotaCbs'] ?? 0,
                    'Aliquota_IBS_UF_Regular' => $aliquotasReformaTributariaRegular['aliquotaIbsUf'] ?? 0,
                    'Aliquota_IBS_Municipal_Regular' => $aliquotasReformaTributariaRegular['aliquotaIbsMunicipal'] ?? 0,
                    'Percentual_Reducao_CBS_Regular' => $aliquotasReformaTributariaRegular['percentualReducaoCbs'] ?? 0,
                    'Percentual_Reducao_IBS_UF_Regular' => $aliquotasReformaTributariaRegular['percentualReducaoIbsUf'] ?? 0,
                    'Percentual_Reducao_IBS_Municipal_Regular' => $aliquotasReformaTributariaRegular['percentualReducaoIbsMunicipal'] ?? 0,
                );

                $T008A = mysql_query("SELECT T008A_Id
                                        FROM T008A
                                       WHERE T008A_T008_Id = '{$mT008['T008_Id']}'");
                $mT008A = mysql_fetch_array($T008A);
                $cError = mysql_error();
                if (!empty($cError)) {
                    return "Erro: {$cError}";
                }

                if (!empty($mT008A['T008A_Id'])) {
                    $cClausula = "UPDATE T008A SET
                                        T008A_Situacao_Tributaria_CBS_IBS              = '{$Aliquotas['Situacao_Tributaria_CBS_IBS']}',
                                        T008A_Classificacao_Tributaria_CBS_IBS         = '{$Aliquotas['Classificacao_Tributaria_CBS_IBS']}',
                                        T008A_Aliquota_CBS                             = '{$Aliquotas['Aliquota_CBS']}',
                                        T008A_Aliquota_IBS_UF                          = '{$Aliquotas['Aliquota_IBS_UF']}',
                                        T008A_Aliquota_IBS_Municipal                   = '{$Aliquotas['Aliquota_IBS_Municipal']}',
                                        T008A_Percentual_Reducao_CBS                   = '{$Aliquotas['Percentual_Reducao_CBS']}',
                                        T008A_Percentual_Reducao_IBS_UF                = '{$Aliquotas['Percentual_Reducao_IBS_UF']}',
                                        T008A_Percentual_Reducao_IBS_Municipal         = '{$Aliquotas['Percentual_Reducao_IBS_Municipal']}',
                                        T008A_Percentual_Diferimento_CBS               = '{$Aliquotas['Percentual_Diferimento_CBS']}',
                                        T008A_Percentual_Diferimento_IBS_UF            = '{$Aliquotas['Percentual_Diferimento_IBS_UF']}',
                                        T008A_Percentual_Diferimento_IBS_Municipal     = '{$Aliquotas['Percentual_Diferimento_IBS_Municipal']}',
                                        T008A_Situacao_Tributaria_CBS_IBS_Regular      = '{$Aliquotas['Situacao_Tributaria_CBS_IBS_Regular']}',
                                        T008A_Classificacao_Tributaria_CBS_IBS_Regular = '{$Aliquotas['Classificacao_Tributaria_CBS_IBS_Regular']}',
                                        T008A_Aliquota_CBS_Regular                     = '{$Aliquotas['Aliquota_CBS_Regular']}',
                                        T008A_Aliquota_IBS_UF_Regular                  = '{$Aliquotas['Aliquota_IBS_UF_Regular']}',
                                        T008A_Aliquota_IBS_Municipal_Regular           = '{$Aliquotas['Aliquota_IBS_Municipal_Regular']}',
                                        T008A_Percentual_Reducao_CBS_Regular           = '{$Aliquotas['Percentual_Reducao_CBS_Regular']}',
                                        T008A_Percentual_Reducao_IBS_UF_Regular        = '{$Aliquotas['Percentual_Reducao_IBS_UF_Regular']}',
                                        T008A_Percentual_Reducao_IBS_Municipal_Regular = '{$Aliquotas['Percentual_Reducao_IBS_Municipal_Regular']}'
                                  WHERE T008A_Id = '{$mT008A['T008A_Id']}'";
                } else {
                    $cClausula = "INSERT INTO T008A (
                                        T008A_T008_Id,
                                        T008A_Situacao_Tributaria_CBS_IBS,
                                        T008A_Classificacao_Tributaria_CBS_IBS,
                                        T008A_Aliquota_CBS,
                                        T008A_Aliquota_IBS_UF,
                                        T008A_Aliquota_IBS_Municipal,
                                        T008A_Percentual_Reducao_CBS,
                                        T008A_Percentual_Reducao_IBS_UF,
                                        T008A_Percentual_Reducao_IBS_Municipal,
                                        T008A_Percentual_Diferimento_CBS,
                                        T008A_Percentual_Diferimento_IBS_UF,
                                        T008A_Percentual_Diferimento_IBS_Municipal,
                                        T008A_Situacao_Tributaria_CBS_IBS_Regular,
                                        T008A_Classificacao_Tributaria_CBS_IBS_Regular,
                                        T008A_Aliquota_CBS_Regular,
                                        T008A_Aliquota_IBS_UF_Regular,
                                        T008A_Aliquota_IBS_Municipal_Regular,
                                        T008A_Percentual_Reducao_CBS_Regular,
                                        T008A_Percentual_Reducao_IBS_UF_Regular,
                                        T008A_Percentual_Reducao_IBS_Municipal_Regular
                                  ) VALUES (
                                        '{$mT008['T008_Id']}',
                                        '{$Aliquotas['Situacao_Tributaria_CBS_IBS']}',
                                        '{$Aliquotas['Classificacao_Tributaria_CBS_IBS']}',
                                        '{$Aliquotas['Aliquota_CBS']}',
                                        '{$Aliquotas['Aliquota_IBS_UF']}',
                                        '{$Aliquotas['Aliquota_IBS_Municipal']}',
                                        '{$Aliquotas['Percentual_Reducao_CBS']}',
                                        '{$Aliquotas['Percentual_Reducao_IBS_UF']}',
                                        '{$Aliquotas['Percentual_Reducao_IBS_Municipal']}',
                                        '{$Aliquotas['Percentual_Diferimento_CBS']}',
                                        '{$Aliquotas['Percentual_Diferimento_IBS_UF']}',
                                        '{$Aliquotas['Percentual_Diferimento_IBS_Municipal']}',
                                        '{$Aliquotas['Situacao_Tributaria_CBS_IBS_Regular']}',
                                        '{$Aliquotas['Classificacao_Tributaria_CBS_IBS_Regular']}',
                                        '{$Aliquotas['Aliquota_CBS_Regular']}',
                                        '{$Aliquotas['Aliquota_IBS_UF_Regular']}',
                                        '{$Aliquotas['Aliquota_IBS_Municipal_Regular']}',
                                        '{$Aliquotas['Percentual_Reducao_CBS_Regular']}',
                                        '{$Aliquotas['Percentual_Reducao_IBS_UF_Regular']}',
                                        '{$Aliquotas['Percentual_Reducao_IBS_Municipal_Regular']}'
                                  )";
                }

                mysql_query($cClausula);
                $cError = mysql_error();
                if (!empty($cError)) {
                    return "Erro: {$cError}";
                }

                mysql_query("call T008_Gravar_Totalizacao_4('{$mT008['T008_Id']}')");
                $cError = mysql_error();
                if (!empty($cError)) {
                    return "Erro: {$cError}";
                }
            }

            mysql_query("call T007_Gravar_Totalizacao_4('{$T007_Id}')");
            $cError = mysql_error();
