            return true;
        }

        
        /**
         * VEN003montarPdfGridNotasFiscais
         *
         * @param String $sqlT007
         * @param String $sqlTotalizadores
         * @return array
         */
        public function VEN003montarPdfGridNotasFiscais($sqlT007, $sqlTotalizadores)
        {
            global $g, $confUsuario;
            
            $resultT007 = mysql_query($sqlT007);
            
            $resTotalizadores                       = mysql_query($sqlTotalizadores);
            $rowTotalizadores                       = mysql_fetch_array($resTotalizadores);
            $rowTotalizadores['valorTotalGeral']    = gCorrigeNumero($rowTotalizadores['valorTotalGeral']);
            $rowTotalizadores['valorTotalProdutos'] = gCorrigeNumero($rowTotalizadores['valorTotalProdutos']);
            
            $sqlC004    = "SELECT C004_Nome_Empresa FROM C004 WHERE C004_Id='{$g['empresaAtual']}'";
            $resultC004 = mysql_query($sqlC004);
            $C004       = mysql_fetch_array($resultC004);
            
            $sqlC007    = "SELECT * FROM C007 WHERE C007_Id='{$g['usuarioAtual']}'";
            $resultC007 = mysql_query($sqlC007);
            $C007       = mysql_fetch_array($resultC007);
            
            //$layout = $g['conf']->ini('layoutOrcamentoEmailPdf');
            
            // Array de retorno para criação do e-mail
            $array            = array();
            $array['Para']    = "";
            $array['Assunto'] = "Clientes";
            
            /**
             * PDF
             */
            require_once('bibliotecas/tcpdf/config/lang/eng.php');
            require_once('bibliotecas/tcpdf/tcpdf.php');
            
            // create new PDF document
            $pdf = new \TCPDF(PDF_PAGE_ORIENTATION, PDF_UNIT, PDF_PAGE_FORMAT, true, 'UTF-8', false);
            // SET document information
            $pdf->SetCreator(PDF_CREATOR);
            $pdf->SetAuthor('Hardness Sistemas');
            // remove default header/footer
            $pdf->setPrintHeader(false);
            //$pdf->setPrintFooter(true);
            $pdf->SetMargins(8, 8, 8, 8);
            // SET font
            $pdf->SetFont('helvetica', '', 7);
            //SET auto page breaks
            $pdf->SetAutoPageBreak(TRUE, PDF_MARGIN_BOTTOM);
            //SET image scale factor
            $pdf->setImageScale(PDF_IMAGE_SCALE_RATIO);
            // Orientação da página
            $pdf->setPageOrientation('P');
            // add a page
            $pdf->AddPage();
            
            $html = '';
            /**
             * PDF - STYLE
             */
            $html .= <<<EOT
				<style>
					.header .text {
						font-size: 25px;
					}
					.header .text2 {
						font-size: 35px;
						font-weight: bold;
					}
					.titulo {
						background-color: #E1ECF1;
					}
					.titulo_superior {
						font-size: 30px;
					}
					.itens td {
						border: 1px solid black;
					}
					.textIncluso {
						font-size: 18px;
						color: red;
						background-color: #E1ECF1;
					}
					
				</style>
EOT;
            
            /**
             * PDF - HEADER
             */
            if (!empty($g['c004']['C004_Logo_Marca'])) {
                $pathinfo      = pathinfo($g['c004']['C004_Logo_Marca']);
                $caminhoImagem = "{$confUsuario['urlRaiz']}{$g['pathWeb']}{$g['pathDados']}imagens/logo/{$g['empresaAtual']}.{$pathinfo['extension']}";
                $caminhoImagem = "<img src=\"{$caminhoImagem}\">";
            } else {
                $caminhoImagem = "";
            }
            
            $html .= <<<EOT
		<table style='height:10px;border:1px solid black;'>
			<tr>
				<td align="left">{$g['c004']['C004_Nome_Empresa']}</td>
				<td align="right" style="font-size: 230%;"><b>Notas Fiscais</b></td>
			</tr>
		</table>
		<div style="height:20px; width:100%;"></div>
		<table style='border:1px solid black;'>
			<tr class="itens">
				<td align="center">
					Notas Emitidas<br/>
					{$rowTotalizadores['qtdeNotas']}
				</td>
				<td align="center">
					Valor Produtos<br/>
					 R$ {$rowTotalizadores['valorTotalProdutos']}
				</td>
				<td align="center">
					Valor Total<br/>
					R$ {$rowTotalizadores['valorTotalGeral']}
				</td>
			</tr>
		</table>
EOT;
            
            /**
             * PDF - TABELA NOTAS FISCAIS
             */
            
            if ($C007['C007_Flag_Vendedor'] == 'D' OR $C007['C007_Flag_Vendedor'] == 'S') {
                // GRID: Diretor
                
                $html .= <<<EOT
			<div style="height:20px; width:100%;"></div>
					<table class="itens" cellspacing="0" cellpadding="2">
						<tr class="titulo">
							<td style="width: 7%"; align="center";>CFOP</td>
    						<td style="width: 7%"; align="center";>Data</td>
    						<td style="width: 8%"; align=center>Nº</td>
    						<td style="width: 5%"; align="center">Cód</td>
    						<td style="width: 32%"; align="left">Cliente</td>
    						<td style="width: 12%;"; align="right">Produtos R$ </td>
    						<td style="width: 9%"; align="right">Valor R$ </td>
    						<td style="width: 20%"; align="center">Vendedor</td>
    					</tr>
    				</table>
EOT;
            } else {
                $html .= <<<EOT
			<div style="height:20px; width:100%;"></div>
					<table class="itens" cellspacing="0" cellpadding="2">
						<tr class="titulo">
							<td style="width: 7%"; align="center">CFOP</td>
    						<td style="width: 7%"; align="center">Data</td>
    						<td style="width: 8%"; align=center>Nº</td>
    						<td style="width: 8%"; align="center">Cód</td>
    						<td style="width: 40%"; align="left">Cliente</td>
    						<td style="width: 12%"; align="right">Produtos R$ </td>
    						<td style="width: 18%"; align="right">Valor R$ </td>
    					</tr>
    				</table>
EOT;
            }
            
            $html .= <<<EOT
		<table class="itens" cellspacing="0" cellpadding="2">
EOT;
            while ($rowT007 = mysql_fetch_array($resultT007)) {
                $rowT007['T007_Valor_Total_Produtos'] = gCorrigeNumero($rowT007['T007_Valor_Total_Produtos']);
                $rowT007['T007_Valor_Total']          = gCorrigeNumero($rowT007['T007_Valor_Total']);
                $rowT007['T007_Data_Emissao']         = gCorrigeData($rowT007['T007_Data_Emissao']);
                $rowT007['D024_Nome_Empresa']         = substr($rowT007['D024_Nome_Empresa'], 0, 27);
                $nomeCliente                          = $rowT007['D024_Nome_Empresa'];
                if ($C007['C007_Flag_Vendedor'] == 'D' OR $C007['C007_Flag_Vendedor'] == 'S') {
                    // GRID: Diretor
                    $html .= <<<EOT
			
				<tr>
					<td style="width: 7%"; align="center">{$rowT007['D006_Codigo_CFOP']}</td>
    				<td style="width: 7%"; align="center">{$rowT007['T007_Data_Emissao']}</td>
    				<td style="width: 8%"; align="center">{$rowT007['T007_Numero_Nota_Fiscal']}</td>
    				<td style="width: 5%"; align="center">{$rowT007['D024_Id']}</td>
    				<td style="width: 32%"; align="left">{$nomeCliente}</td>
    				<td style="width: 12%"; align="right">{$rowT007['T007_Valor_Total_Produtos']}</td>
    				<td style="width: 9%"; align="right">{$rowT007['T007_Valor_Total']}</td>
    				<td style="width: 20%"; align="center">{$rowT007['C007_Primeiro_Nome']}</td>
				</tr>
				
EOT;
                } else {
                    $html .= <<<EOT
			
				<tr>
					<td style="width: 7%"; align="center">{$rowT007['D006_Codigo_CFOP']}</td>
    				<td style="width: 7%"; align="center">{$rowT007['T007_Data_Emissao']}</td>
    				<td style="width: 8%"; align="center">{$rowT007['T007_Numero_Nota_Fiscal']}</td>
    				<td style="width: 8%"; align="center">{$rowT007['D024_Id']}</td>
    				<td style="width: 40%"; align="left">{$nomeCliente}</td>
    				<td style="width: 12%"; align="right">{$rowT007['T007_Valor_Total_Produtos']}</td>
    				<td style="width: 10%"; align="right">{$rowT007['T007_Valor_Total_Servicos']}</td>
    				<td style="width: 10%"; align="right">{$rowT007['T007_Valor_Troca']}</td>
    				<td style="width: 18%"; align="right">{$rowT007['T007_Valor_Total']}</td>
				</tr>
				
EOT;
                    
                }
                
            }
            $html .= '</table>';
            
            /**
             * PDF - GERA!
             */
            $pdf->writeHTML($html, true, false, true, false, 'C');
            // reset pointer to the last page
            $pdf->lastPage();
            // get data
            $data = $pdf->getPDFData();
            
            // Gravar arquivo no disco
            $anexoDir = $g['pathDados'] . 'tmp/';
            is_dir($anexoDir) OR mkdir($anexoDir, 0777, true);
            $anexoNome = "{$anexoDir}clientesLista.pdf";
            @unlink($anexoNome);
            $h = fopen($anexoNome, 'w');
            fwrite($h, $data);
            fclose($h);
            // Adiciona como anexo
            $array['Anexos']    = array(
                $anexoNome
            );
            $array['AnexosWeb'] = array(
                '/hardness3/' . $anexoNome
            );
            // Logo 		
            if (!empty($g['c004']['C004_Logo_Marca'])) {
                $pathinfo      = pathinfo($g['c004']['C004_Logo_Marca']);
                $caminhoImagem = "{$confUsuario['urlRaiz']}{$g['pathWeb']}{$g['pathDados']}imagens/logo/{$g['empresaAtual']}.{$pathinfo['extension']}";
            } else {
                $caminhoImagem = "";
            }
            // (TODO) passar para o arq. conf
            $caminhoImagem  = str_replace('201.22.57.137:8282', 'eurosul', $caminhoImagem);
            $caminhoImagem  = str_replace('201.22.57.137:8181', 'sigma', $caminhoImagem);
            // Variaveis enviadas para o modulo de e-mails (que serão gravadas na tabela T139)
            $array['Corpo'] = "<img src='{$caminhoImagem}' style='margin-left:10px'><br /><br /><br /><br /><font style='font-size:16px'>Lista de Clientes em anexo.</font><br /><br /><br />";
            
            return $array;
        }
        
        /**
         * incluirNotaReferenciada
         *
         * @param Form $form
         * @return String/bool
         */        
        public function incluirNotaReferenciada($form)
        {
            $T007_Id                 = $form->campoValorEnviado('T132_T007_Id');
