            }

            // Variaveis enviadas para o modulo de e-mails (que serão gravadas na tabela T139)
            $array['Corpo']                 = "<img src='{$caminhoImagem}' style='margin-left:10px'><br /><br /><br /><br /><font style='font-size:16px'>{$T199['D024_Nome_Empresa']}, <br /><br />Segue em anexo a Carta de Correção Eletrônica referente a NFe número <b>{$T199['T007_Numero_Nota_Fiscal']}</b>.</font><br /><br /><br />";
            $array['D024_Id']               = $T199['T199_D024_Id'];
            $array['T139_Valor_Total']      = $T199['T007_Valor_Total'];
            $sql                            = "SELECT COUNT(*) FROM T008 WHERE T008_T007_Id='{$T199['T007_Id']}'";
            $registros                      = mysql_query($sql);
            $registros                      = mysql_fetch_array($registros);
            $array['T139_Numero_Registros'] = $registros[0];
            
            return $array;
        }

        /**
         * ven003AplicarPercentualDesconto
         *
         * @param String $T008_Id
         * @param String $campoEditado
         * @param String $valorAntigo
         * @param String $novoValor
         * @return String/bool
         */    
        public function ven003AplicarPercentualDesconto($T008_Id, $campoEditado, $valorAntigo, $novoValor)
        {
            global $g;
            if ($T008_Id <= 0) {
                return "T008_Id nao existe!";
            }
            $Campo_Editado          = $campoEditado;
            $Conteudo_Campo_Editado = $novoValor;
            
            $T007    = mysql_query("SELECT T008_T007_Id, T007_Casas_Decimais_Preco FROM T008 LEFT JOIN T007 ON T007_Id=T008_T007_Id WHERE T008_Id='{$T008_Id}'");
            $mT007   = mysql_fetch_array($T007);
            $T007_Id = $mT007['T008_T007_Id'];
            
            if (empty($Campo_Editado)) {
                return "Campo_Editado nao existe!";
            }
            
            if ($T008_Id <= 0) {
                return "T008_Id nao existe!";
            }
            $C007  = mysql_query("SELECT * FROM C007 WHERE C007_Id='{$g['usuarioAtual']}'");
            $mC007 = mysql_fetch_array($C007);
            
            $cC004 = mysql_query("SELECT * FROM C004 WHERE C004_Id='{$g['empresaAtual']}'");
            $mC004 = mysql_fetch_array($cC004);
            
            $cClausula = " SELECT ";
            $cClausula .= " *  ";
            $cClausula .= " FROM T008 ";
            $cClausula .= " LEFT JOIN D009 ON D009_Id=T008_D009_Id ";
            $cClausula .= " LEFT JOIN D049 ON D049_Id=D009_D049_Id ";
            $cClausula .= " LEFT JOIN D001 ON D001_Id=D049_D001_Id ";
            $cClausula .= " LEFT JOIN D037 ON D037_Id=T008_D037_Id ";
            $cClausula .= " WHERE T008_Id='$T008_Id' ";
            $T008  = mysql_query("$cClausula");
            $mT008 = mysql_fetch_array($T008);
            
            if ($Campo_Editado == 'T008_Valor_Preco_Sem_Desconto_Unitario') {
                $Conteudo_Campo_Editado = gCorrigeNumeroInverte($Conteudo_Campo_Editado, $mC004['C004_Casas_Decimais_Preco'] + 1);
                
                if ($Conteudo_Campo_Editado < $mT008['T008_Valor_Custo_Unitario']) {
                    //return 'Preço inválido';
                }
                $sql = "UPDATE T008 SET T008_Valor_Preco_Sem_Desconto_Unitario=round('$Conteudo_Campo_Editado', {$mT007['T007_Casas_Decimais_Preco']}),
                                        T008_Valor_Preco_Unitario=T008_Valor_Preco_Sem_Desconto_Unitario,
                                        T008_Percentual_Desconto=if(T008_Valor_Preco_Original>0,(1-(T008_Valor_Preco_Sem_Desconto_Unitario/T008_Valor_Preco_Original))*100,0),
                                        T008_Valor_Desconto_Unitario=if(T008_Valor_Preco_Original>0,(T008_Valor_Preco_Original*($Conteudo_Campo_Editado/100)),0)
                                  WHERE T008_Id='$T008_Id'";
                mysql_query($sql);
                if (mysql_error()) {
                    $erro = mysql_error();
                    return "1 .Erro: " . $erro . ' - ' . str_replace("\n", ' ', $sql);
                }
                
            } elseif ($Campo_Editado == 'T008_Percentual_Desconto') {
                if (!empty($Conteudo_Campo_Editado)) {
                    $Conteudo_Campo_Editado = gCorrigeNumeroInverte($Conteudo_Campo_Editado, 5);
                } else {
                    $Conteudo_Campo_Editado = 0;
                }
                //return "1: ".number_format($Conteudo_Campo_Editado,2)."<br />2: ".number_format($mT008['T008_Percentual_Desconto'],2);
                if (($mT008['T008_Valor_Preco_Original'] - ($mT008['T008_Valor_Preco_Original'] * ($Conteudo_Campo_Editado / 100))) < $mT008['T008_Valor_Custo_Unitario']) {
                    // return "Desconto inválido";
                }
                
                $sql = "UPDATE T008 SET T008_Percentual_Desconto='$Conteudo_Campo_Editado',
                                            T008_Valor_Preco_Sem_Desconto_Unitario=round(T008_Valor_Preco_Original-(T008_Valor_Preco_Original*($Conteudo_Campo_Editado/100)), {$mT007['T007_Casas_Decimais_Preco']}),
                                            T008_Valor_Preco_Unitario=T008_Valor_Preco_Sem_Desconto_Unitario,
                                            T008_Valor_Desconto_Unitario=(T008_Valor_Preco_Original*($Conteudo_Campo_Editado/100))
                                      WHERE T008_Id='$T008_Id'";
                mysql_query($sql);
                if (mysql_error()) {
                    $erro = mysql_error();
                    return "2 .Erro: " . $erro;
                }

                if($g['C031']['utilizaUnidadeConversaoVenda'] == 'S'){
                    $T007A = mysql_query("SELECT T007A_Id
                                            FROM T007A
                                           WHERE T007A_T007_Id = '{$mT008['T008_T007_Id']}'
                                             AND T007A_Flag_Conversao_Unidade = 'S'");
    
                    if(mysql_num_rows($T007A) > 0 ){
                        // Se utiliza unidade conversão precisa atualizar os dados da tabela estendida
                        require_once('bibliotecas/classes/CAD002.php');
                        $CAD002 = new CAD002();
                        $CAD002->conversaoUnidadeProduto(false, false, $T008_Id, true);
                    }          
                }
            } else {
                $Conteudo_Campo_Editado = strtoupper($Conteudo_Campo_Editado);
                $Conteudo_Campo_Editado = addslashes($Conteudo_Campo_Editado);
                
                mysql_query("UPDATE T008 SET $Campo_Editado='$Conteudo_Campo_Editado' WHERE T008_Id='$T008_Id'");
            }
            
            $cSql = mysql_query("call T008_Gravar_Totalizacao_4('$T008_Id');");
            return true;
        }
        
