        /**
         * Registra o envio dos boletos vinculados a uma nota fiscal.
         *
         * @param int $T007_Id
         * @return bool|string
         */
        public function atualizaDataEnvioBoleto($T007_Id) {
            $T007_Id = (int) $T007_Id;
            if ($T007_Id <= 0) {
                return "T007_Id menor ou igual a zero: {$T007_Id}";
            }

            $sql = <<<SQL
                SELECT DISTINCT T002_T117_Id FROM T002 WHERE T002_T007_Id = '{$T007_Id}' AND IFNULL(T002_T117_Id, 0) > 0;
            SQL;

            $boletos = mysql_query($sql);
            if ($boletos === false) {
                $erro = mysql_error();
                return "Não foi possível localizar os boletos da NF T007_Id - {$T007_Id}: \nSelect: {$sql}\n\n{$erro}\n\n";
            }

            while ($boleto = mysql_fetch_assoc($boletos)) {
                $T117_Id = (int) $boleto['T002_T117_Id'];
                $updt = <<<SQL
                    UPDATE T117 SET T117_Data_Envio_Email = NOW() WHERE T117_Id = '{$T117_Id}';
                SQL;

                if (mysql_query($updt) === false) {
                    $erro = mysql_error();
                    return "Não foi possível atualizar 'T117_Data_Envio_Email' do boleto T117_Id - {$T117_Id}: \nUpdate: {$updt}\n\n{$erro}\n\n";
                }
            }

            return true;
        }
        
        /**
         * VEN003calcularParcelaCombo
         *
         * @param String $parcela
         * @param String $valorTotal
         * @param String $tipoJuros
         * @param String $taxaJuros
         * @param String $parcelasIsentas
         * @return String/bool
         */        
        public function VEN003calcularParcelaCombo($parcela, $valorTotal, $tipoJuros, $taxaJuros, $parcelasIsentas)
        {
            global $g;
            if ($parcela <= $parcelasIsentas) {
                return gCorrigeNumero($valorTotal / $parcela);
            } else {
                if ($tipoJuros == 'S') {
                    return gJurosSimples($valorTotal, $taxaJuros, $parcela);
                } else if ($tipoJuros == 'C') {
                    return gJurosCompostos($valorTotal, $taxaJuros, $parcela);
                }
            }
            
        }
        
