        /**
         * inserirParcela
         *
         * @param Form $form
         * @return String/bool
         */        
        public function inserirParcela($form)
        {
            
            $T007_Id        = $form['T007_Id'];
            $intervaloDias  = $form['IntervalorDias'];
            $portador       = $form['D027_Id'];
            $Total_Parcelas = $form['Total_Parcelas'];
            
            $diaFixo                = $form['diaFixo'];
            $primeiroVencimentoNum  = $form['primeiroVencimentoNum'];
            $primeiroVencimentoData = $form['primeiroVencimentoData'];
            
            // se foi definido um intervalo de dias
            if ($intervaloDias > 0) {
                $valorNovo  = 0;
                $query      = "SELECT * FROM T007 WHERE T007_Id='{$T007_Id}'";
                $retorno    = mysql_query($query);
                $linha      = mysql_fetch_assoc($retorno);
                $valorTotal = $linha['T007_Valor_Total'];
                
                $query            = "SELECT * FROM T118 WHERE T118_T007_Id='{$T007_Id}' ORDER BY T118_Id DESC";
                $retorno          = mysql_query($query);
                $linha            = mysql_fetch_assoc($retorno);
                $prazoUltima      = $linha['T118_Prazos_Dias'];
                $numeroUltima     = $linha['T118_Numero_Parcela'];
                $numeroNova       = $numeroUltima + 1;
                $vencimentoUltima = $linha['T118_Data_Vencimento'];
                // se a parcela a ser inserida é a primeira, pega a data informada no campo "Primeiro Vencimento"
                // se não, a data é a ultima + intervalo de dias informado.
                if (mysql_num_rows($retorno) == 0) {
                    if (trim($primeiroVencimentoNum) != "") {
                        $prazoNovo = $primeiroVencimentoNum;
                    } else if (trim($primeiroVencimentoData) != "") {
                        $date1     = new \DateTime(date("Y-m-d"));
                        $date2     = new \DateTime(gCorrigeDataInverte($primeiroVencimentoData));
                        $interval  = $date1->diff($date2);
                        $prazoNovo = $interval->days;
                    }
                    $valorNovo = $valorTotal;
                } else {
                    $prazoNovo = $prazoUltima + $intervaloDias;
                    $valorNovo = 0;
                }
                
                $cClausula = "INSERT INTO T118 (";
                $cClausula .= "T118_T007_Id,";
                $cClausula .= "T118_D027_Id,";
                $cClausula .= "T118_Numero_Parcela,";
                $cClausula .= "T118_Prazos_Dias,";
                $cClausula .= "T118_Data_Vencimento,";
                $cClausula .= "T118_Valor_Parcela";
                $cClausula .= ") VALUES (";
                $cClausula .= "'$T007_Id',";
                $cClausula .= "'$portador',";
                $cClausula .= "'$numeroNova',";
                $cClausula .= "'$prazoNovo',";
                $cClausula .= "DATE_ADD(current_date(),INTERVAL $prazoNovo DAY),";
                $cClausula .= "'$valorNovo'";
                $cClausula .= ")";
                mysql_query($cClausula);
                $erro = mysql_error();
                // ou se foi colocado um dia fixo	
            } else if ($diaFixo > 0) {
                
                if ($diaFixo > 31)
                    return "Por favor, insira um dia válido";
                
                $valorNovo  = 0;
                $query      = "SELECT * FROM T007 WHERE T007_Id='{$T007_Id}'";
                $retorno    = mysql_query($query);
                $linha      = mysql_fetch_assoc($retorno);
                $valorTotal = $linha['T007_Valor_Total'];
                
                $query            = "SELECT * FROM T118 WHERE T118_T007_Id='{$T007_Id}' ORDER BY T118_Id DESC";
                $retorno          = mysql_query($query);
                $linha            = mysql_fetch_assoc($retorno);
                $prazoUltima      = $linha['T118_Prazos_Dias'];
                $numeroUltima     = $linha['T118_Numero_Parcela'];
                $numeroNova       = $numeroUltima + 1;
                $vencimentoUltima = $linha['T118_Data_Vencimento'];
                if (mysql_num_rows($retorno) == 0) {
                    if (trim($primeiroVencimentoNum) != "") {
                        $date     = strtotime("+$primeiroVencimentoNum day", strtotime(date("Y-m-d")));
                        $dataNova = date("Y-m-d", $date);
                    } else if (trim($primeiroVencimentoData) != "") {
                        $dataNova = gCorrigeDataInverte($primeiroVencimentoData);
                    }
                    $valorNovo = $valorTotal;
                } else {
                    $ano = date("Y", strtotime($vencimentoUltima));
                    $mes = date("m", strtotime($vencimentoUltima));
                    $mes++;
                    if ($mes == 13) {
                        $mes = 1;
                        $ano++;
                    }
                    $dataSomar = "$ano-$mes-$diaFixo";
                    $validou   = checkdate($mes, $diaFixo, $ano);
                    while (!$validou) {
                        $diaFixo--;
                        $validou = checkdate($mes, $diaFixo, $ano);
                    }
                    $dataNova = "$ano-$mes-$diaFixo";
                    
                    $valorNovo = 0;
                }
                
                $cClausula = "INSERT INTO T118 (";
                $cClausula .= "T118_T007_Id,";
                $cClausula .= "T118_D027_Id,";
                $cClausula .= "T118_Numero_Parcela,";
                $cClausula .= "T118_Data_Vencimento,";
                $cClausula .= "T118_Prazos_Dias,";
                $cClausula .= "T118_Valor_Parcela";
                $cClausula .= ") VALUES (";
                $cClausula .= "'$T007_Id',";
                $cClausula .= "'$portador',";
                $cClausula .= "'$numeroNova',";
                $cClausula .= "'$dataNova',";
                $cClausula .= "DATEDIFF('$dataNova',current_date()),";
                $cClausula .= "'$valorNovo'";
                $cClausula .= ")";
                mysql_query($cClausula);
                $erro = mysql_error();
            }
            
            if (empty($erro)) {
                return true;
            } else {
                return false;
            }
        }
        
        /**
         * calcularParcelaSimulacao
         *
         * @param Form $form
         * @return String
         */        
        public function calcularParcelaSimulacao($form)
        {
            global $g;
            $T007_Id     = $form['T007_Id'];
            $numParcelas = $form['Total_Parcelas'];
            
            if ($numParcelas == "0") {
                return '';
            }
            
            $query      = "SELECT * FROM T007 WHERE T007_Id='{$T007_Id}'";
            $retorno    = mysql_query($query);
            $linha      = mysql_fetch_assoc($retorno);
            $valorTotal = $linha['T007_Valor_Total'];
            
            return gCorrigeNumero($valorTotal / $numParcelas);
        }
        
        /**
         * atualizarParcelas
         *
         * @param Form $form
         * @return String
         */        
        public function atualizarParcelas($form)
        {
            global $g;
            
            $T007_Id                = $form->campoValorEnviado('T007_Id');
            $Total_Parcelas         = $form->campoValorEnviado('Total_Parcelas');
            $IntervalorDias         = $form->campoValorEnviado('IntervalorDias');
            $diaFixo                = $form->campoValorEnviado('diaFixo');
            $primeiroVencimentoNum  = $form->campoValorEnviado('primeiroVencimentoNum');
            $primeiroVencimentoData = $form->campoValorEnviado('primeiroVencimentoData');
            $numeroParcelas         = $form->campoValorEnviado('Total_Parcelas');
            $D027_Id                = $form->campoValorEnviado('Portador_D027_Id');
            $primeiroVencimentoTipo = $form->campoValorEnviado('selecionaPrimeiroVencimento');
            $diasVctoTipo           = $form->campoValorEnviado('selecionaDias');
            
            $campoUsarFreteParcela = strtoupper($form->campoValorEnviado('usarFreteParcela'));
            $campoUsarSTParcela    = strtoupper($form->campoValorEnviado('usarSTParcela'));
            $campoUsarIPIParcela   = strtoupper($form->campoValorEnviado('usarIPIParcela'));
            
            if (($primeiroVencimentoData != "") || (!empty($primeiroVencimentoData))) {
                $primeiroVencmentoValor = $primeiroVencimentoData;
            } else if (($primeiroVencimentoNum != "") || (!empty($primeiroVencimentoNum))) {
                $primeiroVencmentoValor = $primeiroVencimentoNum;
            }else{
                return "Preencha o campo 1º Vencimento.";
            }
            
            if (($IntervalorDias != "") || (!empty($IntervalorDias))) {
                $diasVctoValor = $IntervalorDias;
            } else if (($diaFixo != "") || (!empty($diaFixo))) {
                $diasVctoValor = $diaFixo;
            }
            if ($diasVctoTipo == "I") {
                $diasVctoTipo = "Intervalo";
            } else if ($diasVctoTipo == "F") {
                $diasVctoTipo = "Dia Fixo";
            }
            
            
            $cSql_T007 = mysql_query("SELECT * FROM T007 WHERE T007_Id='{$T007_Id}'");
            $mT007     = mysql_fetch_array($cSql_T007);
            
            // se for "a combinar" remove as parcelas que ja existem
            if ($numeroParcelas == '0') {
                mysql_query("delete T118 FROM T118 WHERE T118_T007_Id='{$T007_Id}'");
                if (mysql_error())
                    return mysql_error();
                else
                    return true;
            }
                        
            $cSql_T118 = mysql_query("SELECT * FROM T118 LEFT JOIN D027 ON D027_Id=T118_D027_Id WHERE T118_T007_Id='{$T007_Id}'");
            while ($mT118 = mysql_fetch_array($cSql_T118)) {
                $mPrazoAntigo[$mT118['T118_Numero_Parcela']]    = $mT118['T118_Prazos_Dias'];
                $mPortadorAntigo[$mT118['T118_Numero_Parcela']] = $mT118['T118_D027_Id'];
            }
            
            mysql_query("delete T118 FROM T118 WHERE T118_T007_Id='{$T007_Id}'");
            
            
            $Valor_Total_IPI       = $mT007['T007_Valor_Total_IPI'];
            $Valor_Total_Orcamento = $mT007['T007_Valor_Total'];
            
            //Global descontinuada 06/01/2015
            //$usarFretePrimeiraParcela = $g['C031']['usarFretePrimeiraParcela'];
            if ($campoUsarFreteParcela == "ON") {
                $Valor_Total_Orcamento = ($Valor_Total_Orcamento - $mT007['T007_Valor_Frete']);
            }            
            if ($campoUsarSTParcela == "ON") {
                $Valor_Total_Orcamento = ($Valor_Total_Orcamento - $mT007['T007_Valor_ICMS_Substituicao_Retencao']);
            }
            if ($campoUsarIPIParcela == "ON") {
                $Valor_Total_Orcamento = ($Valor_Total_Orcamento - $mT007['T007_Valor_Total_IPI']);
            }
            
            if ($Total_Parcelas > 0) {
                //$Valor_Titulo_Parcela = ( $Valor_Total_Orcamento - $Valor_Total_IPI ) / $Total_Parcelas;		
                //$Valor_Total_Titulo = ( ( round($Valor_Titulo_Parcela,2) * $Total_Parcelas ) + $Valor_Total_IPI );
                
                // verificar se deve adicionar juro na parcela 
                $C004              = mysql_query("SELECT * FROM C004 WHERE C004_Id='{$g['empresaAtual']}'");
                $mC004             = mysql_fetch_array($C004);
                $tipoJuros         = $mC004['C004_Tipo_Juros'];
                $taxaJuros         = $mC004['C004_Taxa_Juros'];
                $taxaJurosParcela  = 0.00;
                $valorJurosParcela = 0.00;
                $parcelasIsentas   = $mC004['C004_Parcelas_Isentas_Juros'];
                if ($Total_Parcelas > $parcelasIsentas) {
                    $taxaJurosParcela = $taxaJuros;
                    if ($taxaJuros > 0.00) {
                        if ($tipoJuros == 'S')
                            $Valor_Titulo_Parcela = gCorrigeNumeroInverte(gJurosSimples($Valor_Total_Orcamento, $taxaJuros, $Total_Parcelas));
                        else if ($tipoJuros == 'C')
                            $Valor_Titulo_Parcela = gCorrigeNumeroInverte(gJurosCompostos($Valor_Total_Orcamento, $taxaJuros, $Total_Parcelas));
                        $valorJurosParcela = $Valor_Titulo_Parcela - ($Valor_Total_Orcamento / $Total_Parcelas);
                    } else {
                        $Valor_Titulo_Parcela = ($Valor_Total_Orcamento) / $Total_Parcelas;
                    }
                } else {
                    $Valor_Titulo_Parcela = ($Valor_Total_Orcamento) / $Total_Parcelas;
                }
                
                $Valor_Total_Titulo         = ((round($Valor_Titulo_Parcela, 2) * $Total_Parcelas));
                $Valor_Total_Titulo         = round($Valor_Total_Titulo, 2);
                $Diferenca_Primeira_Parcela = 0; // criado pra evitar erro de undefined no for
                if (($Valor_Total_Titulo != $Valor_Total_Orcamento) && ($Total_Parcelas <= $parcelasIsentas)) {
                    $Diferenca_Primeira_Parcela = $Valor_Total_Orcamento - $Valor_Total_Titulo;
                }
            }
            // se foi definido um intervalo de dias
            if ($IntervalorDias > 0) {
                // variavel para guardar a diferença de dias entre o intervalo de dias e o dia da primeira parcela	
                $acrescimo = 0;
                for ($x = 1; $x <= $Total_Parcelas; $x++) {
                    if ($x == 1) {
                        //$Valor_Titulo = ($Valor_Titulo_Parcela + $Valor_Total_IPI) + $Diferenca_Primeira_Parcela;
                        $Valor_Titulo = $Valor_Titulo_Parcela + $Diferenca_Primeira_Parcela;
                    } else {
                        $Valor_Titulo = $Valor_Titulo_Parcela;
                    }
                    if ($D027_Id > 0) {
                        $mPortadorAntigo[$x] = $D027_Id;
                    }
                    
                    // se for a primeira parcela
                    if ($x == 1) {
                        // se o primeiro vencimento foi preenchido em dias, atribui ele
                        if (trim($primeiroVencimentoNum) != "") {
                            $mPrazoAntigo[$x] = $primeiroVencimentoNum;
                            $acrescimo        = $primeiroVencimentoNum;
                            // se o primeiro vencimento foi preenchido com uma data, transforma em intervalo e atribui
                        } else if (trim($primeiroVencimentoData) != "") {
                            $date1            = new \DateTime(date("Y-m-d"));
                            $date2            = new \DateTime(gCorrigeDataInverte($primeiroVencimentoData));
                            $interval         = $date1->diff($date2);
                            $mPrazoAntigo[$x] = $interval->days;
                            $acrescimo        = $interval->days;
                        }
                    } else {
                        $mPrazoAntigo[$x] = (($IntervalorDias * ($x - 1)) + $acrescimo);
                    }
                    
                    if ($x == 1 && $campoUsarFreteParcela == "ON") {
                        $Valor_Titulo += $mT007['T007_Valor_Frete'];
                    }
                    if ($x == 1 && $campoUsarSTParcela == "ON") {
                        $Valor_Titulo += $mT007['T007_Valor_ICMS_Substituicao_Retencao'];
                    }
                    if ($x == 1 && $campoUsarIPIParcela == "ON") {
                        $Valor_Titulo += $mT007['T007_Valor_Total_IPI'];
                    }
                    
                    $cClausula = "INSERT INTO T118 (";
                    $cClausula .= "T118_T007_Id,";
                    $cClausula .= "T118_D027_Id,";
                    $cClausula .= "T118_Numero_Parcela,";
                    $cClausula .= "T118_Prazos_Dias,";
                    $cClausula .= "T118_Data_Vencimento,";
                    $cClausula .= "T118_Taxa_Juros,";
                    $cClausula .= "T118_Valor_Juros,";
                    $cClausula .= "T118_Valor_Parcela";
                    $cClausula .= ") VALUES (";
                    $cClausula .= "'$T007_Id',";
                    $cClausula .= "'$mPortadorAntigo[$x]',";
                    $cClausula .= "'$x',";
                    $cClausula .= "'$mPrazoAntigo[$x]',";
                    $cClausula .= "DATE_ADD(current_date(),INTERVAL $mPrazoAntigo[$x] DAY),";
                    $cClausula .= "'$taxaJurosParcela',";
                    $cClausula .= "'$valorJurosParcela',";
                    $cClausula .= "'$Valor_Titulo'";
                    $cClausula .= ")";
                    
                    mysql_query($cClausula);
                    
                    if (mysql_error()) {
                        return mysql_error();
                    }
                }
                // ou se foi colocado um dia fixo	
            } else if ($diaFixo > 0) {
                if ($diaFixo > 31)
                    return "Por favor, insira um dia válido";
                $mes = date("m");
                $ano = date("Y");
                
                $validou = checkdate($mes, $diaFixo, $ano);
                while (!$validou) {
                    $diaFixo--;
                    $validou = checkdate($mes, $diaFixo, $ano);
                }
                $primeiraData = "$ano-$mes-$diaFixo";
                
                for ($x = 1; $x <= $Total_Parcelas; $x++) {
                    if ($x == 1) {
                        //$Valor_Titulo = ($Valor_Titulo_Parcela + $Valor_Total_IPI) + $Diferenca_Primeira_Parcela;
                        $Valor_Titulo = $Valor_Titulo_Parcela + $Diferenca_Primeira_Parcela;
                    } else {
                        $Valor_Titulo = $Valor_Titulo_Parcela;
                    }
                    if ($D027_Id > 0) {
                        $mPortadorAntigo[$x] = $D027_Id;
                    }
                    
                    $dataVencimento = "0";
                    $dataPrazoDias  = date("Y-m-d");
                    $numMeses       = $x;
                    // se for a primeira parcela
                    if ($x == 1) {
                        // se o primeiro vencimento foi preenchido em dias, soma esses dias a data atual
                        if (trim($primeiroVencimentoNum) != "") {
                            $date           = strtotime("+$primeiroVencimentoNum day", strtotime(date("Y-m-d")));
                            $dataVencimento = date("Y-m-d", $date);
                            // se o primeiro vencimento foi preenchido com uma data, atribui
                        } else if (trim($primeiroVencimentoData) != "") {
                            $dataVencimento = gCorrigeDataInverte($primeiroVencimentoData);
                        }
                        $dataPrazoDias = $dataVencimento;
                        // looping feito para quando o dia fixo é menor do que o intervalo dias da primeira parcela e fica no mesmo mes
                        $dataAux       = date("Y-m-d", strtotime("+1 month", strtotime($primeiraData)));
                        $mes1          = date("m", strtotime($dataAux));
                        $mes2          = date("m", strtotime($dataPrazoDias));
                        while ((strtotime($dataPrazoDias) > strtotime($dataAux)) || ($mes1 == $mes2)) {
                            $dataAux      = date("Y-m-d", strtotime("+1 month", strtotime($dataAux)));
                            $mes1         = date("m", strtotime($dataAux));
                            $primeiraData = date("Y-m-d", strtotime("+1 month", strtotime($primeiraData)));
                        }
                        $numMeses = "0";
                    } else {
                        $dataVencimento = $primeiraData;
                        $numMeses       = $x - 1;
                        // calcula a data de vencimento para depois
                        // poder calcular os dias até o vencimento da parcela (T118_Prazos_Dias)			    		
                        $date           = strtotime("+$numMeses month", strtotime($dataVencimento));
                        $dataPrazoDias  = date("Y-m-d", $date);
                        $numMeses       = $x - 1;
                    }
                    
                    if ($x == 1 && $campoUsarFreteParcela == "ON") {
                        $Valor_Titulo += $mT007['T007_Valor_Frete'];
                    }
                    if ($x == 1 && $campoUsarSTParcela == "ON") {
                        $Valor_Titulo += $mT007['T007_Valor_ICMS_Substituicao_Retencao'];
                    }
                    if ($x == 1 && $campoUsarIPIParcela == "ON") {
                        $Valor_Titulo += $mT007['T007_Valor_Total_IPI'];
                    }
                    
                    $cClausula = "INSERT INTO T118 (";
                    $cClausula .= "T118_T007_Id,";
                    $cClausula .= "T118_D027_Id,";
                    $cClausula .= "T118_Numero_Parcela,";
                    $cClausula .= "T118_Data_Vencimento,";
                    $cClausula .= "T118_Prazos_Dias,";
                    $cClausula .= "T118_Taxa_Juros,";
                    $cClausula .= "T118_Valor_Juros,";
                    $cClausula .= "T118_Valor_Parcela";
                    $cClausula .= ") VALUES (";
                    $cClausula .= "'$T007_Id',";
                    $cClausula .= "'$mPortadorAntigo[$x]',";
                    $cClausula .= "'$x',";
                    $cClausula .= "DATE_ADD('$dataVencimento',INTERVAL $numMeses MONTH),";
                    $cClausula .= "DATEDIFF('$dataPrazoDias',current_date()),";
                    $cClausula .= "'$taxaJurosParcela',";
                    $cClausula .= "'$valorJurosParcela',";
                    $cClausula .= "'$Valor_Titulo'";
                    $cClausula .= ")";
                    mysql_query($cClausula);
                    
                    if (mysql_error()) {
                        return mysql_error();
                    }
                }
            }
            
            $sqlT007    = <<<EOT
 			UPDATE T007 SET
 			T007_Pgto_Parcelas='{$Total_Parcelas}',
 			T007_Pgto_Primeiro_Vcto_Tipo='{$primeiroVencimentoTipo}',
 			T007_Pgto_Primeiro_Vcto_Valor='{$primeiroVencmentoValor}',
 			T007_Pgto_Dias_Vcto_Tipo='{$diasVctoTipo}',
 			T007_Pgto_Dias_Vcto_Valor='{$diasVctoValor}',
 			T007_Pgto_Portador='{$D027_Id}',
 			T007_Pgto_Data=CURRENT_TIMESTAMP(),
 			T007_Pgto_C007_Id='{$g['usuarioAtual']}'
 			WHERE T007_Id='{$T007_Id}'
EOT;
            $resultT007 = mysql_query($sqlT007);
            if (mysql_error()) {
                return mysql_error();
            }
            return true;
        }
        
        /**
         * importarCCe
         *
         * @param File $cConteudo_XML
         * @param File $cArquivo
         * @param String $TipoZip
         * @return String/bool
         */
        public function importarCCe($cConteudo_XML, $cArquivo, $TipoZip)
        {
            global $g;
            //-- INSTANCIA A CLASSE "DOM" DO PHP PARA LER OS "N�S" DO XML
            $xmlInteiro = addslashes($cConteudo_XML);
            $dom        = new \DomDocument("1.0", "UTF-8");
            @$dom->loadXML($cConteudo_XML);
            
            $chNFe = $dom->getElementsByTagName("chNFe")->item(0)->nodeValue;
            
            $T007  = mysql_query("SELECT * FROM T007 WHERE T007_Chave_Acesso_Nfe='{$chNFe}'");
            $mT007 = mysql_fetch_array($T007);
            if (mysql_num_rows($T007) <= 0) {
                return "Não foi encontrada nenhuma NFe para a chave de acesso: " . $chNFe;
            }
            
            $xCorrecao   = $dom->getElementsByTagName("xCorrecao")->item(0)->nodeValue;
            $dhEvento    = $dom->getElementsByTagName("dhEvento")->item(0)->nodeValue;
            $nSeqEvento  = $dom->getElementsByTagName("nSeqEvento")->item(0)->nodeValue;
            $xMotivo     = addslashes($dom->getElementsByTagName("xMotivo")->item(0)->nodeValue);
            $cStat       = $dom->getElementsByTagName("cStat")->item(0)->nodeValue;
            $nProt       = $dom->getElementsByTagName("nProt")->item(0)->nodeValue;
            $infEvento   = $dom->getElementsByTagName("infEvento")->item(0);
            $infEventoId = $infEvento->getAttribute('Id');
            
            if (empty($nProt)) {
                return "Esta carta de correção não possui número de protocolo de autorização";
            }
            
            $T199 = mysql_query("SELECT * FROM T199 WHERE T199_Correcao='{$xCorrecao}' AND T199_T007_Id='{$mT007['T007_Id']}'");
            if (mysql_num_rows($T199) > 0) {
                return "Esta Carta de correção já existe";
            }
            
            $insT199 = <<<EOT
			INSERT INTO T199 (
				T199_T007_Id,
				T199_C007_Id,
				T199_Data_Hora_Inclusao,
				T199_Sequencial_Evento,
				T199_Correcao,
				T199_Flag_Enviado,
				T199_Data_Envio_Email_Cce
			) VALUES (
				'{$mT007['T007_Id']}',
				'{$g['usuarioAtual']}',
				'{$dhEvento}',
				'{$nSeqEvento}',
				'{$xCorrecao}',
				'S',
				'{$xmlInteiro}'
			);
EOT;
            $resT199 = mysql_query($insT199);
            $erro    = mysql_error();
            if ($erro) {
                mysql_query("ROLLBACK");
                return "Erro Insert CCe: " . $erro;
            }
            $T199_Id = $g['mysqlLastId'];
            
            $T200    = <<<EOT
			INSERT INTO T200 (
				T200_T199_Id,
				T200_C007_Id,
				T200_Data_Hora_Inclusao,
				T200_Status,
				T200_Motivo,
				T200_Retorno_XML
			) VALUES (
				'{$T199_Id}',
				'{$g['usuarioAtual']}',
				CURRENT_TIMESTAMP(),
				'{$cStat}',
				'{$xMotivo}',
				'$cConteudo_XML'
			);
EOT;
            $resT200 = mysql_query($T200);
            $erro    = mysql_error();
            if ($erro) {
                mysql_query("ROLLBACK");
                return "Erro Insert Histórico CCe: " . $erro;
            }
            
            $cAno_Mes_NFe = substr($dEmi, 0, 7);
            if (!is_dir("{$g['pathDadosAntigo']}/nfe/xml/cce/autorizado/")) {
                mkdir("{$g['pathDadosAntigo']}/nfe/xml/cce/autorizado/", 0777, true);
            }
            
            $cArquivoSalvar = "{$g['pathDadosAntigo']}/nfe/xml/cce/autorizado/{$infEventoId}_{$nSeqEvento}.xml";
            
            $fp = fopen($cArquivoSalvar, "a");
            if (!@fwrite($fp, "$cConteudo_XML")) {
                mysql_query("ROLLBACK");
                return "Não foi possível continuar, o arquivo:" . $cArquivoSalvar . "Não pode ser salvo. Verique as permissões na pasta do arquivo";
            } else {
                return true;
            }
        }
        
        /**
         * gerarNotaTransporte
         *
         * @param String $T007_Id
         * @param String $Trans_D024_Id
         * @param String $D006_Id
         * @param String $Trans_Observacao
         * @param String $listaT007s
         * @return String/bool
         */
        public function gerarNotaTransporte($T007_Id, $Trans_D024_Id, $D006_Id, $Trans_Observacao, $T007_Flag_Indicador_Presenca, $listaT007s = false, $C004_Id = false, $T007_Flag_ACP = false, $notaDevolucao = false, $T007_Flag_Finalidade_NFe = false, $T007_Flag_Destino_Produto = false, $aplicarRegraCFOP = false, $utilizarValoresDespesas = false, $atualizarAliquotasReformaTributaria = false, $retornarId = false){
            global $g;
            require_once("bibliotecas/classes/VEN001.php");
            $VEN001 = new VEN001();

            require_once("bibliotecas/classes/VEN012.php");
            $VEN012 = new VEN012();

            if ($T007_Id <= 0) {
                return gGeraAlertMsg("Atenção", "Selecione uma nota!");
            }
            
            if ($Trans_D024_Id <= 0) {
                return gGeraAlertMsg("Atenção", "Selecione um Cliente");
            }
        
            if ($D006_Id <= 0) {
                $D006 = mysql_query("SELECT D006_D006_Id 
                                       FROM T008
                                  LEFT JOIN D006 ON D006_Id = T008_D006_Id
                                      WHERE T008_T007_Id = {$T007_Id}
                                        AND D006_D006_Id > 0");
                $mD006   = mysql_fetch_assoc($D006);
                $D006_Id = $mD006['D006_D006_Id'];
                $recebeuD006_Id = false;
            } else {
                $recebeuD006_Id = true;;
            }
            
            if (empty($Trans_Observacao)) {
                //return gGeraAlertMsg("Atenção", "Informe a observação que será impressa na Nota Fiscal");
            }
            $cClausula = " SELECT * FROM T007 WHERE T007_Id='$T007_Id'";
            $cSql_T007 = mysql_query($cClausula);
            $cErro     = mysql_error();
            if (!empty($cErro)) {
                return gGeraAlertMsg("Atenção", "Erro: " . str_replace(array(
                    "'",
                    '"'
                ), "", $cErro) . "\n" . str_replace(array(
                    "'",
                    '"'
                ), "", $cClausula));
            }
            $mT007 = mysql_fetch_array($cSql_T007);

            //Se a nota for emitida por outra empresa, atualizar o C004 com a empresa selecionada
            if($C004_Id){
                $mT007['T007_C004_Id'] = $C004_Id;
            }
            
            $cClausula = "SELECT * FROM C004 LEFT JOIN D020 ON D020_Id=C004_D020_Id LEFT JOIN D018 ON D018_Id=D020_D018_Id WHERE C004_Id = '{$mT007['T007_C004_Id']}'";
            $cSql_C004 = mysql_query($cClausula);
            $cErro     = mysql_error();
            if (!empty($cErro)) {
                return gGeraAlertMsg("Atenção", "Erro: " . str_replace(array(
                    "'",
                    '"'
                ), "", $cErro) . "\n" . str_replace(array(
                    "'",
                    '"'
                ), "", $cClausula));
            }
            $mC004 = mysql_fetch_array($cSql_C004);
            
            $cClausula = "SELECT * FROM D024 LEFT JOIN D020 ON D020_Id=D024_D020_Id LEFT JOIN D018 ON D018_Id=D020_D018_Id LEFT JOIN D030 ON D030_Id=D024_D030_Id WHERE D024_Id='$Trans_D024_Id'";
            $cSql_D024 = mysql_query($cClausula);
            $cErro     = mysql_error();
            if (!empty($cErro)) {
                return gGeraAlertMsg("Atenção", "Erro: " . str_replace(array(
                    "'",
                    '"'
                ), "", $cErro) . "\n" . str_replace(array(
                    "'",
                    '"'
                ), "", $cClausula));
            }
            $mD024 = mysql_fetch_array($cSql_D024);
            
            $cClausula = "SELECT * FROM D006 LEFT JOIN D059 ON D059_Id=D006_D059_Id WHERE D006_Id='$D006_Id'";
            $cSql_D006 = mysql_query($cClausula);
            $cErro     = mysql_error();
            if (!empty($cErro)) {
                return gGeraAlertMsg("Atenção", "Erro: " . str_replace(array(
                    "'",
                    '"'
                ), "", $cErro) . "\n" . str_replace(array(
                    "'",
                    '"'
                ), "", $cClausula));
            }
            $mD006 = mysql_fetch_array($cSql_D006);
            
            $mT008['D006_D059_Id']                      = $mD006['D006_D059_Id'];
            $mT008['D006_Modalidade_ICMS_Substituicao'] = $mD006['D006_Modalidade_ICMS_Substituicao'];
            
            if ($mT007['T007_Flag_ACP'] == '1' AND $mConfig['C020_NFe_Habilitada'] == 'S') {
                $mT007['T007_Flag_ACP'] = '6';
            }

            //Seta a flag destino operação
            if($mC004['D018_Id'] == $mD024['D018_Id']){
                $T007_Flag_Destino_Operacao = '1';
            } else if($mC004['D018_Id'] != $mD024['D018_Id'] && $mD024['D018_UF'] != 'EX') {
                $T007_Flag_Destino_Operacao = '2';
            } else {
                $T007_Flag_Destino_Operacao = '3';
            }

            // Vai verificar se na UF da empresa (C004) possui % FCP, caso não 
            // precisa zerar no item se não da erro ao enviar para o Sefaz
            $D053 = mysql_query("SELECT D053_Percentual_FCP
                                   FROM D053
                                  WHERE D053_C004_Id = '{$mC004['C004_Id']}'
                                    AND D053_D018_Id = '{$mC004['C004_D018_Id']}'");

            $mD053 = mysql_fetch_array($D053);

            $UFPossuiFCP = true;
            if($mD053['D053_Percentual_FCP'] <= 0){
                $UFPossuiFCP = false;
            }

            //////////////////////////////////////////////////////////////////////////////////////////////////////
            //-- VALIDACOES
            //////////////////////////////////////////////////////////////////////////////////////////////////////
            
            if (mysql_num_rows($cSql_T007) == 0) {
                return gGeraAlertMsg("Atenção", "NF de origem não encontrada $T007_Id");
            }
            
            if (mysql_num_rows($cSql_D024) == 0) {
