            $mT007['T007_Numero_Nota_Devolvida']              = addslashes($mT007['T007_Numero_Nota_Devolvida']);
            $mT007['T007_Descricao_CFOP']                     = addslashes($mT007['T007_Descricao_CFOP']);
            $mT007['T007_Nome_Transportadora']                = addslashes($mT007['T007_Nome_Transportadora']);
            $mT007['T007_Tipo_Transporte']                    = addslashes($mT007['T007_Tipo_Transporte']);
            $mT007['T007_Observacao_1']                       = addslashes($mT007['T007_Observacao_1']);
            $mT007['T007_Observacao_2']                       = addslashes($mT007['T007_Observacao_2']);
            $mT007['T007_Observacao_3']                       = addslashes($mT007['T007_Observacao_3']);
            $mD006['D006_Observacao']                         = addslashes($mD006['D006_Observacao']);
            $mT007['T007_Transportadora_CNPJ']                = addslashes($mT007['T007_Transportadora_CNPJ']);
            $mT007['T007_Transportadora_Inscricao_Estadual']  = addslashes($mT007['T007_Transportadora_Inscricao_Estadual']);
            $mT007['T007_Transportadora_Endereco']            = addslashes($mT007['T007_Transportadora_Endereco']);
            $mT007['T007_Transportadora_Cidade']              = addslashes($mT007['T007_Transportadora_Cidade']);
            $mT007['T007_Transportadora_Estado']              = addslashes($mT007['T007_Transportadora_Estado']);
            $mT007['T007_Transportadora_Placa_Veiculo']       = addslashes($mT007['T007_Transportadora_Placa_Veiculo']);
            $mT007['T007_Estado_Veiculo']                     = addslashes($mT007['T007_Estado_Veiculo']);
            $mT007['T007_Especie']                            = addslashes($mT007['T007_Especie']);
            $mT007['T007_Marca']                              = addslashes($mT007['T007_Marca']);
            $mT007['T007_Numero_Caixas']                      = addslashes($mT007['T007_Numero_Caixas']);
            $mT007['T007_Mao_Obra_1']                         = addslashes($mT007['T007_Mao_Obra_1']);
            $mT007['T007_Mao_Obra_2']                         = addslashes($mT007['T007_Mao_Obra_2']);
            $mT007['T007_Mao_Obra_3']                         = addslashes($mT007['T007_Mao_Obra_3']);
            $mT007['T007_Mao_Obra_4']                         = addslashes($mT007['T007_Mao_Obra_4']);
            $mT007['T007_Valor_Mao_Obra']                     = addslashes($mT007['T007_Valor_Mao_Obra']);
            $mT007['T007_Inscricao_Municipal']                = addslashes($mT007['T007_Inscricao_Municipal']);
            $mT007['T007_Empresa_Usuaria_Nome']               = addslashes($mT007['T007_Empresa_Usuaria_Nome']);
