                                                 T118_Numero_Parcela,
                                                 T118_Prazos_Dias,
                                                 T118_Data_Vencimento,
                                                 T118_Valor_Parcela,
                                                 T118_Taxa_Juros,
                                                 T118_Valor_Juros,
                                                 T118_D027_Id,
                                                 T118_T007_Id
                                         )VALUES(
                                                 '{$mT118['T118_Numero_Parcela']}',
                                                 '{$mT118['T118_Prazos_Dias']}',
                                                 '{$mT118['T118_Data_Vencimento']}',
                                                 '{$mT118['T118_Valor_Parcela']}',
                                                 '{$mT118['T118_Taxa_Juros']}',
                                                 '{$mT118['T118_Valor_Juros']}', 
                                                 '{$mT118['T118_D027_Id']}',
                                                 '$nT007_Id'
                                   )");
                            $cErro=mysql_error();
                            if(!empty($cErro)){
                                mysql_query("ROLLBACK");
                                return "Erro ao inserir o pagamento na Nota Fiscal.";
                            }
                        }
                    }
                    $cClausula  = "INSERT INTO T132 ( ";
                    $cClausula .= " T132_Cupom_Numero_COO, ";
                    $cClausula .= " T132_Cupom_Modelo, ";
                    $cClausula .= " T132_T007_Id ";                                           
                    $cClausula .= " ) VALUES ( ";
                    $cClausula .= " '{$mT007['T007_Numero_Nota_Fiscal']}', ";
                    $cClausula .= " '2D', ";
                    $cClausula .= " '$nT007_Id' ";
                    $cClausula .= " );";
                    
                    log($cClausula);
                    mysql_query($cClausula);
                    $cErro=mysql_error($cClausula);
                    if(!empty($cErro)){
                        mysql_query("ROLLBACK");
                        return "Erro ao inserir documento referenciado na Nota Fiscal.";
                    }
                    mysql_query("UPDATE T007 
                                    SET T007_Numero_Cupom_Fiscal='{$mT007['T007_Numero_Nota_Fiscal']}' 
                                  WHERE T007_Id='$nT007_Id'
                                ");
                    $cErro=mysql_error();
                    if(!empty($cErro)){
                        mysql_query("ROLLBACK");
                        return "Erro ao inserir dados do cupom na Nota Fiscal.";
                    }
                }
            }

            // Na devolução de NF-e, a NT 2025.002 exige a referência em cada item.
            // As referências de outros documentos, como cupom fiscal, permanecem no cabeçalho.
            $Observacao_Fiscal = "";
            if($g['C031']['exibirObservacaoVendedornaNF']=='S'){
                $Observacao_Fiscal .= 'VENDEDOR: ' . substr($mT007['C007_Primeiro_Nome'], 0, 12);
            }
            if (!empty($mC004['C004_Observacao_Fiscal'])) {
                $Observacao_Fiscal .= $mC004['C004_Observacao_Fiscal'];
            }
            $sqlT007 = mysql_query("SELECT D006_Observacao FROM T007 LEFT JOIN D006 ON D006_Id = T007_D006_Id WHERE T007_Id = '{$nT007_Id}' AND D006_Observacao != ''");
            $sqlT008 = mysql_query("SELECT DISTINCT T008_D006_Id, D006_Observacao FROM T005 LEFT JOIN T008 ON T008_T005_Id = T005_Id LEFT JOIN D006 ON T008_D006_Id = D006_Id WHERE T007_Id = '{$nT007_Id}' AND T008_D006_Id != T007_D006_Id AND D006_Observacao != ''");

            $observacao = '';
            log("$$$Aqui");
            if (mysql_num_rows($sqlT007) > 0) {
                $T007_Observacao = mysql_fetch_array($sqlT007);
                $observacao .= $T007_Observacao['D006_Observacao'];
            }
            
            if (mysql_num_rows($sqlT008) > 0) {
                while ($T008_Observacao = mysql_fetch_array($sqlT008)) {
                    $observacao .= $T008_Observacao['D006_Observacao'];
                }
            }
            
            if ($observacao != '') {
                $Observacao_Fiscal .= $observacao;
            }

            $cClausula = " SELECT * FROM T007 WHERE T007_Id='$nT007_Id'";
            $cSql_T007 = mysql_query($cClausula);
            $cErro     = mysql_error();
            if (!empty($cErro)) {
                return gGeraAlertMsg("Atenção", "Erro: " . str_replace(array(
                    "'",
                    '"'
                ), "", $cErro) . "\n" . str_replace(array(
                    "'",
                    '"'
                ), "", $cClausula));
            }
            $mT007 = mysql_fetch_array($cSql_T007);
            // Váriaveis dentro da Observação Fiscal
            foreach ($mT007 as $key => $value) {
                $key = preg_replace('#^[^_]+_#', '', $key);
                $key = strtoupper($key);
                if (preg_match('#^([0-9])+\.([0-9])+$#', $value)) {
                    $value = gCorrigeNumero($value);
                }
                $Observacao_Fiscal = str_replace('[' . strtoupper($key) . ']', $value, $Observacao_Fiscal);
                log("$$$O que acontece".$Observacao_Fiscal);
            }
            mysql_query("UPDATE T007 
                            SET T007_Observacao_Nota_Fiscal_1='$Observacao_Fiscal' 
                          WHERE T007_Id='$nT007_Id'
                        ");
            $cErro=mysql_error();
            if(!empty($cErro)){
                mysql_query("ROLLBACK");
                return "Erro ao inserir dados do cupom na Nota Fiscal.";
            }

            
            //grava na C004 o ultimo numero da nota fiscal
            if ($mT007['T007_Flag_ACP'] == 1) {
                
                $cClausula = " UPDATE C004 SET ";
                $cClausula .= " C004_Ultimo_Numero_Nota_Fiscal='{$proximoNumero}' ";
                $cClausula .= " WHERE C004_Id='{$mT007['T007_C004_Id']}' ";
                mysql_query($cClausula);
                $cErro = mysql_error();
                if (!empty($cErro)) {
                    $retorno = "Clausula: " . $cClausula;
                    $retorno .= "ERRO: " . $cErro;
                    mysql_query("ROLLBACK");
                    return $retorno;
                }
            } elseif ($mT007['T007_Flag_ACP'] == 6) {
                
                $cClausula = " UPDATE C004 SET ";
                $cClausula .= " C004_Ultimo_Numero_Nota_Fiscal_Eletronica='{$proximoNumero}' ";
                $cClausula .= " WHERE C004_Id='{$mT007['T007_C004_Id']}' ";
                mysql_query($cClausula);
                $cErro = mysql_error();
                if (!empty($cErro)) {
                    $retorno = "Clausula: " . $cClausula;
                    $retorno .= "ERRO: " . $cErro;
                    mysql_query("ROLLBACK");
                    return $retorno;
                }

            } elseif ($mT007['T007_Flag_ACP'] == 8) {
                
                $cClausula = " UPDATE C004 SET ";
                $cClausula .= " C004_Ultimo_Numero_NFCe ='{$proximoNumero}' ";
                $cClausula .= " WHERE C004_Id='{$mT007['T007_C004_Id']}' ";
                mysql_query($cClausula);
                $cErro = mysql_error();
                if (!empty($cErro)) {
                    $retorno = "Clausula: " . $cClausula;
                    $retorno .= "ERRO: " . $cErro;
                    mysql_query("ROLLBACK");
                    return $retorno;
                }

            } else if ($mT007['T007_Flag_ACP'] == 4) {
                
                $cClausula = " UPDATE C004 SET ";
                $cClausula .= " C004_Ultimo_Numero_Cupom_Fiscal='{$proximoNumero}' ";
                $cClausula .= " WHERE C004_Id='{$mT007['T007_C004_Id']}' ";
                mysql_query($cClausula);
                $cErro = mysql_error();
                if (!empty($cErro)) {
                    $retorno = "Clausula: " . $cClausula;
                    $retorno .= "ERRO: " . $cErro;
                    mysql_query("ROLLBACK");
                    return $retorno;
                }
            } else if ($mT007['T007_Flag_ACP'] == 3) {
                
                $cClausula = " UPDATE C004 SET ";
                $cClausula .= " C004_Ultimo_Numero_ACP='{$proximoNumero}' ";
                $cClausula .= " WHERE C004_Id='{$mT007['T007_C004_Id']}' ";
                mysql_query($cClausula);
                $cErro = mysql_error();
                if (!empty($cErro)) {
                    $retorno = "Clausula: " . $cClausula;
                    $retorno .= "ERRO: " . $cErro;
                    mysql_query("ROLLBACK");
                    return $retorno;
                }
            } 
                       
            if ($listaT007s) {
                $ids = implode(',', $listaT007s);
                mysql_query("UPDATE T008 SET T008_Quantidade_Devolucao = 0 WHERE T008_T007_Id IN ($ids)");
            }
            
            // Criada configuração global para retirada personalização GP
            if($g['C031']['totalizarPesoNFeDevolucao'] == 'S'){

                $T008_Peso=mysql_query("SELECT SUM(T008_Peso_Unitario), SUM(T008_Peso_Total) as Peso_Total FROM T008 WHERE T008_T007_Id='{$nT007_Id}'");
                $mT008_Total_Peso = mysql_fetch_array($T008_Peso);
                
                $upT007_Peso = mysql_query("UPDATE T007 set T007_Peso_Bruto='{$mT008_Total_Peso['Peso_Total']}', T007_Peso_Liquido='{$mT008_Total_Peso['Peso_Total']}', T007_Total_Peso='{$mT008_Total_Peso['Peso_Total']}}' WHERE T007_Id='{$nT007_Id}'");
            }
            

            //Aplicar Regra de CFOP
            if($aplicarRegraCFOP) {
                
                // Altera para calcular alíquotas
                mysql_query("UPDATE T008 SET T008_Flag_Calculo_Manual = 'N' WHERE T008_T007_Id = '{$nT007_Id}'");
                $cErro = mysql_error();
                if (!empty($cErro)) {
                    $retorno = "Clausula: " . $cClausula;
                    $retorno .= "ERRO: " . $cErro;
                    mysql_query("ROLLBACK");
                    return $retorno;
                }
                //Aplica regra de CFOP e atualiza alíquotas
                $retorno = $this->ven003atualizarCFOP($nT007_Id);
                
                if ($retorno !== true) {
                    mysql_query("ROLLBACK");
                    return $retorno;
                }

                $cClausula = "call T007_Gravar_Totalizacao_4('$nT007_Id') ";
                mysql_query($cClausula);
                $cErro = mysql_error();
                
                if (!empty($cErro)) {                    
                    return gGeraAlertMsg("Atenção", "Erro ao atualizar CFOP: " . str_replace(array(
                        "'",
                        '"'
                    ), "", $cErro) . "\n" . str_replace(array(
                        "'",
                        '"'
                    ), "", $cClausula));
                }
            }

            mysql_query("COMMIT");

			// Rotinas fiscais especializadas podem reutilizar a cópia segura da
			// nota sem produzir scripts/alertas na resposta HTTP.
			if ($retornarId) {
				return array(
					'T007_Id' => (int) $nT007_Id,
					'numero' => $proximoNumero,
					'serie' => $numeroSerie
				);
			}

            $tipo = array(1 => 'NF', 3 => 'ACP', 4 => 'CP', 6 => 'NFe', 8 => 'NFCe');
            if($C004_Id != $g['empresaAtual']) {
                echo gGeraAlertMsg("Nota Fiscal gerada com sucesso", "Gerada {$tipo[$mT007['T007_Flag_ACP']]} N° <b>". $proximoNumero ." </b> na empresa {$mC004['C004_Nome_Empresa']}.");
            } else { 
                echo gGeraAlertMsg("Atenção", "Nota Fiscal <b>". $proximoNumero ." </b> gerada com sucesso!");
                echo <<<EOT
        			<div class="divHidden"><script type="text/javascript"> if (typeof jQuery != 'undefined') {
        				setTimeout(function() {
        					abrirJanela(false, '{$g['divIdRoot']}', '{$g['divId']}', unique(), '', 'Nota Fiscal', '/ven/ven003/content/ven003contentIncluirNotaFiscal/', '&acaoId=' + encodeURIComponent("{$nT007_Id}") + '&tabela=T007', [900,550]);
        				}, 500);
        			} </script></div>
EOT;
            }

            $this->triggerAposInserirNotaDevolucaoOrigemEmitida($nT007_Id);

            //Atualiza notificações relacionadas ao T007
            //require_once('bibliotecas/classes/NOTIFICACOES.php');
            //$NOTIFICACOES = new NOTIFICACOES();
            //$NOTIFICACOES->atualizarNotificacoesT007();
            return true;
        }

		/**
		 * Gera NF-e de débito/crédito a partir de uma NF-e modelo 55 autorizada.
		 *
		 * A origem fiscal fica registrada internamente pela nota espelho. As
		 * referências enviadas no XML são incluídas somente nos tipos exigidos
		 * pela NT 2025.002: NFref no cabeçalho ou DFeReferenciado no item.
		 *
		 * @param array $dados
		 * @return array|string
		 */
		public function gerarNFDebitoCreditoNotaAutorizada(array $dados)
		{
			global $g;

			$T007_IdOrigem = isset($dados['T007_Id']) ? (int) $dados['T007_Id'] : 0;
			$D006_Id = isset($dados['D006_Id']) ? (int) $dados['D006_Id'] : 0;
			$destino = 0;
			$tipoOperacao = isset($dados['tipoOperacao']) ? strtolower(trim($dados['tipoOperacao'])) : '';
			$tipoFiscal = isset($dados['tipoFiscal']) ? trim($dados['tipoFiscal']) : '';
			$observacao = '';
			$quantidadesInformadas = isset($dados['quantidades']) && is_array($dados['quantidades']) ? $dados['quantidades'] : array();
			$precosInformados = array_key_exists('precos', $dados) ? $dados['precos'] : array();
			if (!is_array($precosInformados)) {
				return 'Os preços unitários informados são inválidos.';
			}
			$reformaInformada = isset($dados['reforma']) && is_array($dados['reforma']) ? $dados['reforma'] : array();
			$finalidade = $tipoOperacao === 'credito' ? '5' : ($tipoOperacao === 'debito' ? '6' : '');
			if ($tipoOperacao === 'debito' && $tipoFiscal === '06') {
				return 'NF de débito tipo 06 - Pagamento antecipado deve ser gerada pelo pedido.';
			}
			$tiposValidos = $tipoOperacao === 'credito'
				? array('01', '02', '03', '04', '05', '06')
				: array('01', '02', '03', '04', '05', '07', '08');

			if ($T007_IdOrigem <= 0 || $D006_Id <= 0 || empty($finalidade) || !in_array($tipoFiscal, $tiposValidos, true)) {
				return 'Os dados informados para gerar a NF de débito/crédito são inválidos.';
			}
			if ($tipoOperacao === 'credito' && $tipoFiscal === '02' && (int) date('Y') < 2029) {
				return 'NF de crédito tipo 02 somente pode ser emitida a partir de janeiro de 2029.';
			}
			require_once('bibliotecas/classes/ReformaTributaria.php');
			$reformaTributaria = new ReformaTributaria();
			$regraFiscal = $reformaTributaria->getRegrasNFDebitoCredito()[$finalidade . ':' . $tipoFiscal];
			if ((string) ($g['C004']['C004_Flag_Tipo_Preenchimento_Reforma_Tributaria'] ?? '') !== '1') {
				return 'Ative o preenchimento da Reforma Tributária pela regra fiscal da empresa antes de usar este gerador. A nova NF não deve herdar a classificação da origem sem recalcular.';
			}
			$campoVinculoSql = mysql_query("SHOW COLUMNS FROM T007A LIKE 'T007A_T007_Id_Origem_NF_Debito_Credito'");
			if (!$campoVinculoSql || mysql_num_rows($campoVinculoSql) === 0) {
				return 'A atualização da base está pendente. Execute a Atualização Base para criar o vínculo da NF de débito/crédito na tabela estendida T007A.';
			}

			$origemSql = mysql_query("SELECT T007_Id,
										 T007_D024_Id,
										 T007_C004_Id,
										 T007_D006_Id,
										 T007_Flag_Destino_Produto,
										 T007_Flag_ACP,
										 T007_Flag_Cancelada,
										 T007_Flag_Inutilizado,
										 T007_Flag_Denegado,
										 T007_Numero_Nota_Fiscal,
										 T007_Serie,
										 T007_Data_Emissao,
										 T007_Chave_Acesso_Nfe,
										 T007_Numero_Protocolo_Nfe
								   FROM T007
								  WHERE T007_Id = '{$T007_IdOrigem}'
									AND T007_C004_Id = '{$g['empresaAtual']}'
								  LIMIT 1");
			$origem = $origemSql ? mysql_fetch_assoc($origemSql) : false;
			if (!$origem || (int) $origem['T007_Flag_ACP'] !== 6 || empty($origem['T007_Numero_Protocolo_Nfe']) || strlen($origem['T007_Chave_Acesso_Nfe']) !== 44
				|| substr($origem['T007_Chave_Acesso_Nfe'], 20, 2) !== '55'
				|| $origem['T007_Flag_Cancelada'] === 'S' || $origem['T007_Flag_Inutilizado'] === 'S' || $origem['T007_Flag_Denegado'] === 'S') {
				return 'A origem deve ser uma NF-e modelo 55 autorizada, ativa e pertencente à empresa atual.';
			}
			$destino = (int) $origem['T007_Flag_Destino_Produto'];
			if ($destino < 1 || $destino > 20) {
				return 'A NF-e de origem não possui um destino de produto válido.';
			}

			$cfopSql = mysql_query("SELECT D006_Id, REPLACE(D006_Codigo_CFOP,'.','') AS Codigo_CFOP
								 FROM D006
								WHERE D006_Id = '{$D006_Id}'
								  AND IFNULL(D006_Flag_Inativo,'N') != 'S'");
			$cfop = $cfopSql ? mysql_fetch_assoc($cfopSql) : false;
			if (!$cfop) {
				return 'Selecione uma CFOP ativa.';
			}
			$primeiroDigitoCFOP = substr((string) $cfop['Codigo_CFOP'], 0, 1);
			if ($finalidade === '5' && !in_array($primeiroDigitoCFOP, array('1', '2', '3'), true)) {
				return 'NF de crédito é uma operação de entrada. Selecione uma CFOP iniciada por 1, 2 ou 3.';
			}
			if ($finalidade === '6' && !in_array($primeiroDigitoCFOP, array('5', '6', '7'), true)) {
				return 'NF de débito é uma operação de saída. Selecione uma CFOP iniciada por 5, 6 ou 7.';
			}
			$erroCFOP = $reformaTributaria->validarCFOPNFDebitoCredito($finalidade, $tipoFiscal, $cfop['Codigo_CFOP']);
			if ($erroCFOP !== null) {
				return $erroCFOP;
			}

			$itensOrigem = array();
			$itensPorNumero = array();
			$itensSql = mysql_query("SELECT T008_Id, T008_Codigo_Produto,
										 T008_Descricao_Produto, T008_Quantidade
								   FROM T008
								  WHERE T008_T007_Id = '{$T007_IdOrigem}'
								  ORDER BY T008_Id");
			if (!$itensSql) {
				return 'Não foi possível consultar os produtos da NF-e autorizada: ' . mysql_error();
			}
			$numeroItemNFe = 0;
			while ($item = mysql_fetch_assoc($itensSql)) {
				$numeroItemNFe++;
				$item['Numero_Item_NFe'] = $numeroItemNFe;
				$itensOrigem[(int) $item['T008_Id']] = $item;
				$itensPorNumero[$numeroItemNFe] = (int) $item['T008_Id'];
			}
			if (empty($itensOrigem)) {
				return 'A NF-e de origem não possui produtos.';
			}

			$quantidades = array();
			foreach ($quantidadesInformadas as $T008_IdOrigem => $quantidadeInformada) {
				$T008_IdOrigem = (int) $T008_IdOrigem;
				if (!isset($itensOrigem[$T008_IdOrigem])) {
					return "O item {$T008_IdOrigem} não pertence à NF-e de origem.";
				}
				$quantidadeTexto = trim((string) $quantidadeInformada);
				if (strpos($quantidadeTexto, ',') !== false) {
					$quantidadeTexto = str_replace('.', '', $quantidadeTexto);
					$quantidadeTexto = str_replace(',', '.', $quantidadeTexto);
				}
				$quantidade = is_numeric($quantidadeTexto) ? (float) $quantidadeTexto : -1;
				if ($quantidade < 0 || $quantidade > ((float) $itensOrigem[$T008_IdOrigem]['T008_Quantidade'] + 0.000001)) {
					return "A quantidade informada para o item {$itensOrigem[$T008_IdOrigem]['Numero_Item_NFe']} é inválida ou supera a NF-e de origem.";
				}
				if ($quantidade > 0) {
					$quantidades[$T008_IdOrigem] = $quantidade;
				}
			}
			if (empty($quantidades)) {
				return 'Informe uma quantidade maior que zero em pelo menos um produto.';
			}
			if ($tipoOperacao === 'debito' && $tipoFiscal === '03' && count($quantidades) > 1) {
				return 'Débito tipo 03 não informa nItem e não permite repetir a mesma chave. Gere um item por NF de débito ao partir de uma única NF-e autorizada.';
			}

			// Preço opcional, validado antes de copiar a nota. Trabalhar como texto
			// decimal preserva a precisão de DECIMAL(20,10), inclusive no limite.
			$precos = array();
			foreach ($precosInformados as $T008_IdOrigem => $precoInformado) {
				if (!ctype_digit((string) $T008_IdOrigem) || !isset($itensOrigem[(int) $T008_IdOrigem])) {
					return 'Um dos preços informados não corresponde a um item da NF-e de origem.';
				}
				$T008_IdOrigem = (int) $T008_IdOrigem;
				if (!isset($quantidades[$T008_IdOrigem])) { continue; }
				$erroPreco = "Preço unitário inválido no item {$itensOrigem[$T008_IdOrigem]['Numero_Item_NFe']}. Informe um valor não negativo, com até 10 dígitos inteiros e 10 casas decimais.";
				if (!is_string($precoInformado) && !is_int($precoInformado) && !is_float($precoInformado)) {
					return $erroPreco;
				}
				$precoTexto = trim((string) $precoInformado);
				if ($precoTexto === '') { continue; }
				if (strpos($precoTexto, ',') !== false) {
					if (!preg_match('/^(?:[0-9]+|[0-9]{1,3}(?:\.[0-9]{3})+),[0-9]{1,10}$/D', $precoTexto)) {
						return $erroPreco;
					}
					$precoTexto = str_replace(',', '.', str_replace('.', '', $precoTexto));
				}
				if (!preg_match('/^[0-9]+(?:\.[0-9]{1,10})?$/D', $precoTexto)) {
					return $erroPreco;
				}
				$partesPreco = explode('.', $precoTexto, 2);
				$inteiroPreco = ltrim($partesPreco[0], '0');
				if (strlen($inteiroPreco) > 10) { return $erroPreco; }
				$precos[$T008_IdOrigem] = ($inteiroPreco === '' ? '0' : $inteiroPreco)
					. '.' . str_pad($partesPreco[1] ?? '', 10, '0');
			}

			// Os valores normais de CBS/IBS são apenas consultivos na tela e serão
			// recalculados na nova NF. Somente os grupos especiais previstos para o
			// tipo podem ser informados manualmente; a lista fechada também impede
			// que o JSON recebido altere outros campos de T008A.
			$grupoEspecial = $regraFiscal['grupo'];
			$camposReformaPermitidos = $reformaTributaria->getCamposEspeciaisNFDebitoCredito($grupoEspecial);
			if ($regraFiscal['classe'] === null) {
				// Tipos sem classe fixa também podem exigir estorno pela cClassTrib.
				// Preservar o valor informado mesmo antes de o fiscal ajustar a classe.
				$camposReformaPermitidos = array_merge($camposReformaPermitidos,
					$reformaTributaria->getCamposEspeciaisNFDebitoCredito('estorno'));
			}
			$reforma = array();
			foreach ($quantidades as $T008_IdOrigem => $quantidade) {
				$valoresItem = isset($reformaInformada[$T008_IdOrigem]) && is_array($reformaInformada[$T008_IdOrigem]) ? $reformaInformada[$T008_IdOrigem] : array();
				$reforma[$T008_IdOrigem] = array();
				foreach ($camposReformaPermitidos as $campo) {
					$valorRecebido = isset($valoresItem[$campo]) ? trim((string) $valoresItem[$campo]) : '';
					if ($campo === 'T008A_Competencia_Ajuste') {
						if ($valorRecebido !== '' && !preg_match('/^(0[1-9]|1[0-2])\/\d{4}$/', $valorRecebido)) {
							return "Informe a competência do item {$itensOrigem[$T008_IdOrigem]['Numero_Item_NFe']} no formato MM/AAAA.";
						}
						$reforma[$T008_IdOrigem][$campo] = $valorRecebido;
						continue;
					}
					if (strpos($valorRecebido, ',') !== false) {
						$valorRecebido = str_replace('.', '', $valorRecebido);
						$valorRecebido = str_replace(',', '.', $valorRecebido);
					}
					$valor = $valorRecebido === '' ? 0 : (is_numeric($valorRecebido) ? (float) $valorRecebido : -1);
					if (!is_finite($valor) || $valor < 0) {
						return "Há um valor de IBS/CBS inválido no item {$itensOrigem[$T008_IdOrigem]['Numero_Item_NFe']}.";
					}
					// Os grupos especiais são 13v2 no XML. Persistir em centavos
					// evita totalizar frações que não serão transmitidas por item.
					$reforma[$T008_IdOrigem][$campo] = round($valor, 2);
				}
				if ($grupoEspecial === 'ajuste' && empty($reforma[$T008_IdOrigem]['T008A_Competencia_Ajuste'])) {
					return "Informe a competência do ajuste no item {$itensOrigem[$T008_IdOrigem]['Numero_Item_NFe']}.";
				}
				if ($grupoEspecial === 'transferencia'
					&& empty($reforma[$T008_IdOrigem]['T008A_Valor_IBS_Transferido'])
					&& empty($reforma[$T008_IdOrigem]['T008A_Valor_CBS_Transferido'])) {
					return "Informe um valor de IBS ou CBS a transferir no item {$itensOrigem[$T008_IdOrigem]['Numero_Item_NFe']}.";
				}
				if ($grupoEspecial === 'ajuste'
					&& empty($reforma[$T008_IdOrigem]['T008A_Valor_IBS_Ajuste_Competencia'])
					&& empty($reforma[$T008_IdOrigem]['T008A_Valor_CBS_Ajuste_Competencia'])) {
					return "Informe um valor de IBS ou CBS para o ajuste do item {$itensOrigem[$T008_IdOrigem]['Numero_Item_NFe']}.";
				}
			}

			$lockNome = mysql_real_escape_string("ven003-nfdc-origem-{$g['empresaAtual']}-{$T007_IdOrigem}");
			$lockSql = mysql_query("SELECT GET_LOCK('{$lockNome}',10) AS Bloqueado");
			$lock = $lockSql ? mysql_fetch_assoc($lockSql) : false;
			if (empty($lock['Bloqueado'])) {
				return 'Esta NF-e está sendo utilizada por outro usuário. Aguarde e tente novamente.';
			}

			$copia = $this->gerarNotaTransporte(
				$T007_IdOrigem,
				(int) $origem['T007_D024_Id'],
				$D006_Id,
				$observacao,
				'0',
				false,
				false,
				'6',
				false,
				$finalidade,
				$destino,
				false,
				false,
				true,
				true
			);
			if (!is_array($copia) || empty($copia['T007_Id'])) {
				mysql_query("SELECT RELEASE_LOCK('{$lockNome}')");
				return is_string($copia) ? $copia : 'Não foi possível copiar a NF-e autorizada.';
			}
			$T007_Id = (int) $copia['T007_Id'];

			$cancelar = function ($mensagem) use ($T007_Id, $lockNome) {
				mysql_query('ROLLBACK');
				mysql_query('SET AUTOCOMMIT=1');
				mysql_query("DELETE FROM T132 WHERE T132_T007_Id = '{$T007_Id}'");
				$retornoExclusao = $this->ven003excluirNota($T007_Id);
				mysql_query('SET AUTOCOMMIT=1');
				mysql_query("SELECT RELEASE_LOCK('{$lockNome}')");
				if ($retornoExclusao !== true) {
					$mensagem .= ' Não foi possível remover automaticamente a cópia em elaboração (T007_Id '
						. $T007_Id . '). Não transmita essa nota; solicite revisão ao suporte. ' . (string) $retornoExclusao;
				}
				return $mensagem;
			};

			mysql_query('SET AUTOCOMMIT=0');
			mysql_query('START TRANSACTION');
			mysql_query("UPDATE T007
							SET T007_Flag_Finalidade_NFe = '{$finalidade}',
								T007_Flag_Entrada_Saida = '" . ($finalidade === '5' ? 'E' : 'S') . "',
								T007_D006_Id = '{$D006_Id}',
								T007_Flag_Destino_Produto = '{$destino}',
								T007_Flag_Calcular = 'S',
								T007_T005_Id = NULL
						  WHERE T007_Id = '{$T007_Id}'");
			if (mysql_error()) {
				return $cancelar('Não foi possível ajustar o cabeçalho da NF especial: ' . mysql_error());
			}
			mysql_query("UPDATE T007A
							SET T007A_Tipo_NF_Debito = '" . ($finalidade === '6' ? mysql_real_escape_string($tipoFiscal) : '') . "',
								T007A_Tipo_NF_Credito = '" . ($finalidade === '5' ? mysql_real_escape_string($tipoFiscal) : '') . "',
								T007A_T007_Id_Origem_NF_Debito_Credito = '{$T007_IdOrigem}'
						  WHERE T007A_T007_Id = '{$T007_Id}'");
			if (mysql_error()) {
				return $cancelar('Não foi possível gravar o tipo fiscal da NF especial: ' . mysql_error());
			}
			$tipoGravadoSql = mysql_query("SELECT T007A_T007_Id
										FROM T007A
									   WHERE T007A_T007_Id = '{$T007_Id}'
									 AND T007A_Tipo_NF_Debito = '" . ($finalidade === '6' ? mysql_real_escape_string($tipoFiscal) : '') . "'
									 AND T007A_Tipo_NF_Credito = '" . ($finalidade === '5' ? mysql_real_escape_string($tipoFiscal) : '') . "'
									 AND T007A_T007_Id_Origem_NF_Debito_Credito = '{$T007_IdOrigem}'
								   LIMIT 1");
			if (!$tipoGravadoSql || mysql_num_rows($tipoGravadoSql) !== 1) {
				return $cancelar('Não foi possível confirmar o tipo fiscal da NF especial.');
			}

			// A nota espelho não pode herdar referências, valores calculados nem
			// grupos especiais da origem. A matriz abaixo inclui somente os dados
			// próprios do tipo selecionado; os valores normais serão recalculados.
			mysql_query("DELETE FROM T132 WHERE T132_T007_Id = '{$T007_Id}'");
			// Limpar também os impostos anteriores à reforma. Nenhum valor
			// calculado da origem pode servir de entrada para a nova operação.
			$limpezaImpostos = array();
			foreach (array('Base_IPI', 'IPI', 'IPI_Devolucao', 'Base_ICMS', 'ICMS',
				'Base_ICMS_Sem_Reducao', 'Base_ICMS_Impresso', 'Base_ICMS_Diferido', 'ICMS_Diferido',
				'Base_ICMS_Desonerado', 'ICMS_Desonerado', 'Base_ICMS_Oculto', 'ICMS_Oculto', 'ICMS_Credito',
				'Base_ICMS_Substituicao', 'ICMS_Substituicao', 'ICMS_Substituicao_Retencao',
				'Base_ICMS_Substituicao_Retido', 'ICMS_Substituicao_Retido', 'ICMS_Substituto',
				'Base_Partilha_ICMS', 'Partilha_ICMS_Destino', 'Partilha_ICMS_Origem',
				'Base_FCP', 'FCP', 'Base_FCP_ST', 'FCP_ST', 'Base_FCP_Ret', 'FCP_Retido',
				'Base_FCP_Dest', 'FCP_Partilha', 'Base_PIS', 'PIS', 'Base_COFINS', 'COFINS',
				'Base_IRPJ', 'IRPJ', 'Base_CSLL', 'CSLL',
				'Base_Imposto_Importacao_Unitario', 'Imposto_Importacao_Unitario',
				'Total_Base_Imposto_Importacao', 'Total_Imposto_Importacao', 'Total_IOF',
				'Trib_Transparencia', 'Trib_Federal', 'Trib_Estadual', 'Trib_Municipal') as $imposto) {
				$limpezaImpostos[] = 'I.T008_Valor_' . $imposto . '=0';
			}
			$limpezaImpostosSql = implode(',', $limpezaImpostos);
			mysql_query("UPDATE T008A A
						 INNER JOIN T008 I ON I.T008_Id=A.T008A_T008_Id
							SET {$limpezaImpostosSql},
								A.T008A_Valor_Base_PIS_Retido=0,
								A.T008A_Valor_PIS_Retido=0,
								A.T008A_Valor_Base_COFINS_Retido=0,
								A.T008A_Valor_COFINS_Retido=0,
								A.T008A_Valor_Beneficio_Credito_Presumido=0,
								A.T008A_Chave_Acesso_DFe_Referenciado='',
								A.T008A_Item_DFe_Referenciado=0,
								A.T008A_Valor_Base_CBS_IBS=0,
								A.T008A_Valor_CBS=0,
								A.T008A_Valor_IBS=0,
								A.T008A_Valor_IBS_UF=0,
								A.T008A_Valor_IBS_Municipal=0,
								A.T008A_Valor_Diferimento_CBS=0,
								A.T008A_Valor_Diferimento_IBS_UF=0,
								A.T008A_Valor_Diferimento_IBS_Municipal=0,
								A.T008A_Valor_CBS_Regular=0,
								A.T008A_Valor_IBS_UF_Regular=0,
								A.T008A_Valor_IBS_Municipal_Regular=0,
								A.T008A_Valor_Total_Reforma=0,
								A.T008A_Valor_IBS_Transferido=0,
								A.T008A_Valor_CBS_Transferido=0,
								A.T008A_Competencia_Ajuste='',
								A.T008A_Valor_IBS_Ajuste_Competencia=0,
								A.T008A_Valor_CBS_Ajuste_Competencia=0,
								A.T008A_Valor_IBS_Estornado=0,
								A.T008A_Valor_CBS_Estornado=0
						  WHERE I.T008_T007_Id='{$T007_Id}'");
			if (mysql_error()) {
				return $cancelar('Não foi possível limpar os valores fiscais herdados da NF-e de origem: ' . mysql_error());
			}

			$referenciaCabecalho = $tipoOperacao === 'credito' && in_array($tipoFiscal, array('01', '03', '04'), true);
			$referenciaItem = ($tipoOperacao === 'debito' && in_array($tipoFiscal, array('03', '04'), true))
				|| ($tipoOperacao === 'credito' && $tipoFiscal === '06');
			$referenciaNumeroItem = ($tipoOperacao === 'debito' && $tipoFiscal === '04')
				|| ($tipoOperacao === 'credito' && $tipoFiscal === '06');

			$novosItensSql = mysql_query("SELECT T008_Id
										  FROM T008
										 WHERE T008_T007_Id = '{$T007_Id}'
									  ORDER BY T008_Id");
			if (!$novosItensSql) {
				return $cancelar('Não foi possível consultar os itens copiados da NF especial: ' . mysql_error());
			}
			$numeroItem = 0;
			$mapaItensNovos = array();
			while ($novoItem = mysql_fetch_assoc($novosItensSql)) {
				$numeroItem++;
				$novoT008_Id = (int) $novoItem['T008_Id'];
				$origemItemId = isset($itensPorNumero[$numeroItem]) ? $itensPorNumero[$numeroItem] : 0;
				if (!$origemItemId || !isset($quantidades[$origemItemId])) {
					mysql_query("DELETE FROM T001 WHERE T001_T008_Id = '{$novoT008_Id}'");
					if (mysql_error()) {
						return $cancelar('Não foi possível remover o histórico do item não selecionado da NF especial: ' . mysql_error());
					}
					mysql_query("DELETE FROM T008A WHERE T008A_T008_Id = '{$novoT008_Id}'");
					if (mysql_error()) {
						return $cancelar('Não foi possível remover os dados complementares do item não selecionado da NF especial: ' . mysql_error());
					}
					mysql_query("DELETE FROM T008 WHERE T008_Id = '{$novoT008_Id}' AND T008_T007_Id = '{$T007_Id}'");
					if (mysql_error()) {
						return $cancelar('Não foi possível remover os itens não selecionados da NF especial: ' . mysql_error());
					}
					continue;
				}

				$quantidade = mysql_real_escape_string(number_format((float) $quantidades[$origemItemId], 6, '.', ''));
				$mapaItensNovos[$origemItemId] = $novoT008_Id;
				$precoItemSql = '';
				$precoComercialSql = '';
				if (isset($precos[$origemItemId])) {
					$precoNovo = mysql_real_escape_string($precos[$origemItemId]);
					// O totalizador usa T008; o preço comercial também deve ficar
					// persistido em T008A, como solicitado. Não altera a nota de origem.
					$precoItemSql = "T008_Valor_Preco_Sem_Desconto_Unitario='{$precoNovo}',";
					$precoComercialSql = "T008A_Preco_Unitario_Comercial='{$precoNovo}',";
				}
				$ajustouItem = mysql_query("UPDATE T008
								SET T008_Quantidade='{$quantidade}',
									{$precoItemSql}
									T008_T006_Id=NULL,
									T008_D006_Id='{$D006_Id}',
									T008_Flag_Destino_Produto='{$destino}',
									T008_Flag_Calculo_Manual='N'
							  WHERE T008_Id='{$novoT008_Id}'
								AND T008_T007_Id='{$T007_Id}'");
				if (!$ajustouItem || mysql_error()) {
					return $cancelar('Não foi possível ajustar quantidade/preço do item da NF especial: ' . mysql_error());
				}
				$ajustouItemComercial = mysql_query("UPDATE T008A
								SET T008A_Quantidade_Comercial='{$quantidade}',
									{$precoComercialSql}
									T008A_Chave_Acesso_DFe_Referenciado='" . ($referenciaItem ? mysql_real_escape_string($origem['T007_Chave_Acesso_Nfe']) : '') . "',
									T008A_Item_DFe_Referenciado='" . ($referenciaNumeroItem ? $numeroItem : 0) . "'
							  WHERE T008A_T008_Id='{$novoT008_Id}'");
				if (!$ajustouItemComercial || mysql_error()) {
					return $cancelar('Não foi possível ajustar os itens da NF especial: ' . mysql_error());
				}
			}

			if ($referenciaCabecalho) {
				$chave = mysql_real_escape_string($origem['T007_Chave_Acesso_Nfe']);
				$numero = mysql_real_escape_string($origem['T007_Numero_Nota_Fiscal']);
				$serie = mysql_real_escape_string($origem['T007_Serie']);
				$anoMes = mysql_real_escape_string(substr(str_replace('-', '', $origem['T007_Data_Emissao']), 2, 4));
				$cnpj = mysql_real_escape_string(substr($origem['T007_Chave_Acesso_Nfe'], 6, 14));
				mysql_query("INSERT INTO T132 (T132_T007_Id,T132_Tipo,T132_Chave_Acesso,T132_Numero_Nota_Fiscal,T132_Modelo,T132_Serie,T132_Ano_Mes,T132_Cnpj)
							 VALUES ('{$T007_Id}','NFe','{$chave}','{$numero}','55','{$serie}','{$anoMes}','{$cnpj}')");
				if (mysql_error()) {
					return $cancelar('Não foi possível gravar a NF-e referenciada no cabeçalho: ' . mysql_error());
				}
			}

			$retornoAliquotas = $this->atualizarAliquotasNF($T007_Id, true);
			if ($retornoAliquotas !== true) {
				return $cancelar('Não foi possível atualizar os tributos da NF especial: ' . $retornoAliquotas);
			}

			// Conferir dados operacionais sem impor CST/cClassTrib ao fiscal.
			// O enquadramento escolhido não impede criar a nota em elaboração.
			$fiscalSql = mysql_query("SELECT I.T008_Id, D.D006_Codigo_CFOP AS T008_Codigo_CFOP, A.*,
										N.T007_Data_Emissao, N.T007_Empresa_Usuaria_CRT
								 FROM T008 I
								 JOIN T007 N ON N.T007_Id=I.T008_T007_Id
								 LEFT JOIN D006 D ON D.D006_Id=I.T008_D006_Id
								 LEFT JOIN T008A A ON A.T008A_T008_Id=I.T008_Id
								 WHERE I.T008_T007_Id='{$T007_Id}'");
			if (!$fiscalSql || mysql_num_rows($fiscalSql) !== count($mapaItensNovos)) {
				return $cancelar('Não foi possível confirmar a configuração fiscal de todos os itens da nova NF.');
			}
			$origensPorItemNovo = array_flip($mapaItensNovos);
			while ($fiscalItem = mysql_fetch_assoc($fiscalSql)) {
				$origemItemId = $origensPorItemNovo[(int) $fiscalItem['T008_Id']] ?? 0;
				if (!$origemItemId) {
					return $cancelar('O item calculado não corresponde aos itens selecionados na origem.');
				}
				$erroFiscal = $reformaTributaria->validarItemNFDebitoCredito($finalidade, $tipoFiscal,
					array_merge($fiscalItem, $reforma[$origemItemId]), (string) $fiscalItem['T007_Data_Emissao'],
					(string) $fiscalItem['T007_Empresa_Usuaria_CRT'], false);
				if ($erroFiscal !== null) {
					return $cancelar('Item ' . $itensOrigem[$origemItemId]['Numero_Item_NFe'] . ' da origem: ' . $erroFiscal);
				}
			}

			// A CFOP define CST/cClassTrib e recalcula os valores normais. Depois
			// são aplicados exclusivamente os grupos especiais informados na grade.
			foreach ($mapaItensNovos as $origemItemId => $novoT008_Id) {
				$atribuicoes = array();
				foreach ($reforma[$origemItemId] as $campo => $valor) {
					if ($campo === 'T008A_Competencia_Ajuste') {
						$atribuicoes[] = $campo . "='" . mysql_real_escape_string($valor) . "'";
					} else {
						$atribuicoes[] = $campo . "='" . mysql_real_escape_string(number_format((float) $valor, 4, '.', '')) . "'";
					}
				}
				if (!empty($atribuicoes)) {
					mysql_query("UPDATE T008A SET " . implode(',', $atribuicoes) . " WHERE T008A_T008_Id='{$novoT008_Id}'");
					if (mysql_error()) {
						return $cancelar('Não foi possível gravar os valores de IBS/CBS do item: ' . mysql_error());
					}
				}
			}
			mysql_query("CALL T007_Gravar_Totalizacao_4('{$T007_Id}')");
			if (mysql_error()) {
				return $cancelar('Não foi possível totalizar os valores de IBS/CBS da NF especial: ' . mysql_error());
			}
			$retornoTotaisRTC = $this->totalizarValoresEspeciaisNFDebitoCredito($T007_Id);
			if ($retornoTotaisRTC !== true) {
				return $cancelar($retornoTotaisRTC);
			}
			mysql_query('COMMIT');
			$erroCommit = mysql_error();
			mysql_query('SET AUTOCOMMIT=1');
			if (!empty($erroCommit)) {
				return $cancelar('Não foi possível confirmar a geração da NF especial: ' . $erroCommit);
			}
			mysql_query("SELECT RELEASE_LOCK('{$lockNome}')");

			return array(
				'T007_Id' => $T007_Id,
				'numero' => $copia['numero'],
				'serie' => $copia['serie'],
				'operacao' => $tipoOperacao,
				'tipoFiscal' => $tipoFiscal,
				'itens' => count($quantidades),
				'referencia' => $referenciaCabecalho ? 'cabecalho' : ($referenciaItem ? 'item' : 'nenhuma')
			);
		}
        
        /** Sincroniza controles internos com os itens efetivamente gravados.
         * Não depende da versão/personalização da rotina geral de totalização,
         * nem da classificação ou do cálculo automático dos tributos comuns.
         * Não altera notas autorizadas/inativas nem cria grupos no XML.
         */
        public function totalizarValoresEspeciaisNFDebitoCredito($T007_Id)
        {
            global $g;
            $T007_Id = (int) $T007_Id;
            $empresaId = (int) ($g['empresaAtual'] ?? 0);
            if ($T007_Id <= 0 || $empresaId <= 0) {
                return 'Não foi possível identificar a nota/empresa para totalizar os valores especiais.';
            }
            $sql = "UPDATE T007A CAB
                    INNER JOIN T007 NF ON NF.T007_Id = CAB.T007A_T007_Id
                    CROSS JOIN (
                        SELECT IFNULL(SUM(ITEM.T008A_Valor_IBS_Transferido), 0) AS IBS_Transferido,
                               IFNULL(SUM(ITEM.T008A_Valor_CBS_Transferido), 0) AS CBS_Transferido,
                               IFNULL(SUM(ITEM.T008A_Valor_IBS_Ajuste_Competencia), 0) AS IBS_Ajuste,
                               IFNULL(SUM(ITEM.T008A_Valor_CBS_Ajuste_Competencia), 0) AS CBS_Ajuste,
                               IFNULL(SUM(ITEM.T008A_Valor_IBS_Estornado), 0) AS IBS_Estornado,
                               IFNULL(SUM(ITEM.T008A_Valor_CBS_Estornado), 0) AS CBS_Estornado
                          FROM T008 PROD
                          LEFT JOIN T008A ITEM ON ITEM.T008A_T008_Id = PROD.T008_Id
                         WHERE PROD.T008_T007_Id = '{$T007_Id}'
                    ) TOTAIS
                    SET CAB.T007A_Valor_Total_IBS_Transferido = TOTAIS.IBS_Transferido,
                        CAB.T007A_Valor_Total_CBS_Transferido = TOTAIS.CBS_Transferido,
                        CAB.T007A_Valor_Total_IBS_Ajuste_Competencia = TOTAIS.IBS_Ajuste,
                        CAB.T007A_Valor_Total_CBS_Ajuste_Competencia = TOTAIS.CBS_Ajuste,
                        CAB.T007A_Valor_Total_IBS_Estornado = TOTAIS.IBS_Estornado,
                        CAB.T007A_Valor_Total_CBS_Estornado = TOTAIS.CBS_Estornado
                    WHERE NF.T007_Id = '{$T007_Id}'
                      AND NF.T007_C004_Id = '{$empresaId}'
                      AND NF.T007_Flag_Finalidade_NFe IN ('5', '6')
                      AND IFNULL(NF.T007_Numero_Protocolo_Nfe, '') = ''
                      AND IFNULL(NF.T007_Flag_Cancelada, 'N') != 'S'
                      AND IFNULL(NF.T007_Flag_Inutilizado, 'N') != 'S'
                      AND IFNULL(NF.T007_Flag_Denegado, 'N') != 'S'";
            if (!mysql_query($sql)) {
                return 'Não foi possível gravar os totais especiais de IBS/CBS no cabeçalho: ' . mysql_error();
            }
            return true;
        }

        /**
         * imprimirNFeMarcada
         *
         * @return true
         */        
        public function imprimirNFeMarcada($extra = false, $sql = false)
        {
            global $g;
            if ($sql == false) {
                $sql = "SELECT T007_Id,T007_Numero_Protocolo_Nfe,T007_Data_Emissao, if(T007_Flag_ACP!='3',LPAD(T007_Numero_Nota_Fiscal,7,'0'),T007_Numero_Nota_Fiscal) as NFe FROM T007 " . $extra;
            } 
            $sql = mysql_query($sql);

            while ($res = mysql_fetch_array($sql)) {
                if (!empty($res['T007_Numero_Protocolo_Nfe'])) {
                    $AnoMesNFe  = substr($res['T007_Data_Emissao'], 0, 7);
                    $arquivoXML = $g['pathDadosAntigo'] . 'nfe/xml/autorizado/' . $AnoMesNFe . '/' . $res['T007_Numero_Protocolo_Nfe'] . '.xml';
                    if (!file_exists($arquivoXML)) {
                        $arquivoXML = $g['pathDadosAntigo'] . 'nfe/xml/autorizado/' . $res['T007_Numero_Protocolo_Nfe'] . '.xml';
                    }
                    $this->gerarDanfe($res['T007_Id'], $arquivoXML, false);
                }
            }
            return true;
        }

        /**
         * gerarDANFENotasFilaEnvio
         *
         * @return true
         */        
        public function gerarDANFENotasFilaEnvio()
        {
            global $g;
            $sql = mysql_query("SELECT * FROM T007 WHERE T007_Flag_Enviar = 'S' AND T007_C004_Id = '{$g['empresaAtual']}' AND T007_TX_Flag_Finalizada = 2");
            while ($res = mysql_fetch_array($sql)) {
                if (!empty($res['T007_Numero_Protocolo_Nfe'])) {
                    $arquivoDANFE = '../hardness/'.$g['pathDados'].'nfe/danfe/danfe_'.$res['T007_Numero_Protocolo_Nfe'].'.pdf';
                    if(file_exists($arquivoDANFE)){ continue; }
                    $AnoMesNFe  = substr($res['T007_Data_Emissao'], 0, 7);
                    $arquivoXML = $g['pathDadosAntigo'] . 'nfe/xml/autorizado/' . $AnoMesNFe . '/' . $res['T007_Numero_Protocolo_Nfe'] . '.xml';
                    if (!file_exists($arquivoXML))
                    {
                        $arquivoXML = $g['pathDadosAntigo'] . 'nfe/xml/autorizado/' . $res['T007_Numero_Protocolo_Nfe'] . '.xml';
                    }
                    $this->gerarDanfe($res['T007_Id'], $arquivoXML, false);
                }
            }
            return true;
        }
        
        /**
         * ven003atualizarCFOP
         *
         * @param String $T007_Id
         * @return String
         */        
        public function ven003atualizarCFOP($T007_Id)
        {
            require_once("bibliotecas/classes/VEN001.php");
            $VEN001 = new VEN001();
            global $g;
            
            $sqlT007 = mysql_query("SELECT * 
                                      FROM T007 
                                 LEFT JOIN T008 ON T007_Id = T008_T007_Id 
                                 LEFT JOIN D148 on D148_Id=T007_D148_Id_Entrega
                                     WHERE T007_Id = '{$T007_Id}'");

            while ($T007 = mysql_fetch_array($sqlT007)) {

                $contextoCFOP = [
                    'ufEnderecoEntrega' => $T007['D148_D018_Id']
                ];
                //$D006_Id = $VEN001->retornaCFOP($T007['T007_D024_Id'], $T007['T008_D009_Id'], $T007['T007_C004_Id'], $T007['T008_Flag_Destino_Produto'], false, false, false, $T007['T007_C004_Id_Estoque'], $T007['T008_Id']);
                //$demonstrativoCFOP = $VEN001->retornaCFOP($T007['T007_D024_Id'], $T007['T008_D009_Id'], $T007['T007_C004_Id'], $T007['T008_Flag_Destino_Produto'], false, true, false, $T007['T007_C004_Id_Estoque'], $T007['T008_Id']);
                $D006_Id = $VEN001->retornaCFOPContexto($T007['T007_D024_Id'], $T007['T008_D009_Id'], $T007['T007_C004_Id'], $T007['T008_Flag_Destino_Produto'], false, false, false, $T007['T007_C004_Id_Estoque'], $T007['T008_Id'], $contextoCFOP);
                $demonstrativoCFOP = $VEN001->retornaCFOPContexto($T007['T007_D024_Id'], $T007['T008_D009_Id'], $T007['T007_C004_Id'], $T007['T008_Flag_Destino_Produto'], false, true, false, $T007['T007_C004_Id_Estoque'], $T007['T008_Id'], $contextoCFOP);
                $demonstrativoCFOP = mysql_real_escape_string($demonstrativoCFOP);
                mysql_query("UPDATE T008 SET T008_D006_Id = '{$D006_Id}', T008_D006_Id_Info = '{$demonstrativoCFOP}' WHERE T008_Id = '{$T007['T008_Id']}'");
                // Grava demonstartivo na estendida também, clientes que estavam com muitas regras não mostrava completo, campo na estentida aceita mais caracteres
                mysqli_query("UPDATE T008A SET T008A_D006_Id_Info = '{$demonstrativoCFOP}' WHERE T008A_T008_Id = '{$T007['T008_Id']}'");
            }

            if ($D006_Id > 0) {
                mysql_query("UPDATE T007 SET T007_D006_Id='{$D006_Id}' WHERE T007_Id='{$T007_Id}'");
            }

            $retorno = $this->atualizarAliquotasNF($T007_Id);
            return $retorno;
        }
        
        /**
         * ven003atualizarCFOPManual
         *
         * @param String $T007_Id
         * @param String $D006_Id
         * @return String
         */        
        public function ven003atualizarCFOPManual($T007_Id, $D006_Id)
        {
            mysql_query("UPDATE T007 SET T007_D006_Id = '{$D006_Id}' WHERE T007_Id = '{$T007_Id}'");
            mysql_query("UPDATE T008 SET T008_D006_Id = '{$D006_Id}' WHERE T008_T007_Id = '{$T007_Id}'");
            $retorno = $this->atualizarAliquotasNF($T007_Id);
            return $retorno;
        }

        /**
         * verificaCancelarNF
         *
         * @param String $T007_Id
         * @return String/bool
         */
        public function verificaCancelarNF($T007_Id)
        {
            global $g;
            
            $sqlT007 = mysql_query("SELECT * FROM T007 WHERE T007_Id = '{$T007_Id}'");
            $mT007   = mysql_fetch_array($sqlT007);
            
            $cSql_T007 = mysql_query("SELECT T007_Id FROM T007 WHERE T007_Id='{$T007_Id}' AND T007_Flag_Cancelada='S'");
            if (mysql_num_rows($cSql_T007) > 0) {
                return "Essa nota fiscal já foi cancelada";
            }
            
            $cSql_T007 = mysql_query("SELECT T007_Id FROM T007 WHERE T007_Id='{$T007_Id}' AND T007_Flag_Impresso!='S'");
            if (mysql_num_rows($cSql_T007) > 0) {
                //return "Essa nota fiscal nao foi impressa ainda";
            }
            
            $cSql_T002 = mysql_query("SELECT T002_Id FROM T002 WHERE T002_T007_Id='{$T007_Id}' AND T002_Data_Recebimento!='0000-00-00' AND (T002_Valor_Duplicata>0 || T002_Valor_Total>0)");
            if (mysql_num_rows($cSql_T002) > 0) {
                return "Existem títulos a receber baixados!";
            }
            
            $cSql_T002 = mysql_query("SELECT T002_Id FROM T002 WHERE T002_T007_Id='{$T007_Id}' AND T002_T035_Id>0");
            if (mysql_num_rows($cSql_T002) > 0) {
                return "Existem títulos que já foram enviados para o banco!";
            }

            // Validação comentada em 21/11/2019 devido ao erro apresentado na empresa fane, eles haviam reparcelado os titulos e depois excluido eles e não estavam conseguindo cancelar a nota fiscal
            /*$cSql_T002 = mysql_query("SELECT T002_Id FROM T002 WHERE T002_T007_Id='{$T007_Id}' AND T002_Flag_Cancelada = 'S'");
            if (mysql_num_rows($cSql_T002) > 0) {
                return "Existem títulos a receber cancelados! Verifique se foram agrupados!";
            }*/
            
            $cSql_T015 = mysql_query("SELECT T015_Id FROM T015 WHERE T015_T007_Id='{$T007_Id}' AND T015_Data_Pagamento!='0000-00-00'");
            if (mysql_num_rows($cSql_T015) > 0) {
                return "Existem títulos a pagar baixados!";
            }
            
            $cSql_T008 = mysql_query("SELECT T008_Id FROM T008 LEFT JOIN T007 ON T007_Id=T008_T007_Id WHERE T008_T007_Id='{$T007_Id}'");
            while ($mT008 = mysql_fetch_array($cSql_T008)) {
                $cSql = mysql_query("SELECT T008_Id,T007_Numero_Nota_Fiscal FROM T008 LEFT JOIN T007 ON T007_Id=T008_T007_Id WHERE T008_T008_Id='{$mT008['T008_Id']}' AND T007_Flag_Cancelada!='S' AND T007_Flag_Finalidade_NFe != '1'");
                if (mysql_num_rows($cSql) > 0) {
                    $notas = array();
                    while($mNotas = mysql_fetch_array($cSql)){
                        $notas[] = $mNotas['T007_Numero_Nota_Fiscal'];
                    }
                    $numeroNotas = implode($notas,", ");
                    return "Existem notas emitidas relacionadas a esta nota:<br><br>{$numeroNotas}";
                }
            }
            
            $cSql_T008 = mysql_query("SELECT T008_Id FROM T008 LEFT JOIN T007 ON T007_Id=T008_T007_Id WHERE T008_T007_Id='{$T007_Id}'");
            while ($mT008 = mysql_fetch_array($cSql_T008)) {
                $cSql = mysql_query("SELECT T006_Id FROM T006 LEFT JOIN T005 ON T005_Id=T006_T005_Id WHERE T006_T008_Id='{$mT008['T008_Id']}' AND T005_Flag_Status!='8' AND T005_Flag_Status!='5' AND T005_Flag_Status!='4'");
                if (mysql_num_rows($cSql) > 0) {
                    return "Existem pedidos relacionados a esta nota!";
                }
            }
            
            $cSql_T008 = mysql_query("SELECT T008_Id FROM T008 LEFT JOIN T007 ON T007_Id=T008_T007_Id WHERE T008_T007_Id='{$T007_Id}'");
            while ($mT008 = mysql_fetch_array($cSql_T008)) {
                $cSql = mysql_query("SELECT T014_Id, T013_Numero_Nota_Fiscal FROM T014 LEFT JOIN T013 ON T013_Id=T014_T013_Id WHERE T014_T008_Id='{$mT008['T008_Id']}' AND T013_Flag_Cancelada!='S'");
                if (mysql_num_rows($cSql) > 0) {
                    $notas = array();
                    while($mNotas = mysql_fetch_array($cSql)){
                        $notas[] = $mNotas['T013_Numero_Nota_Fiscal'];
                    }
                    $numeroNotas = implode(", ", array_unique($notas));
                    return "Não é possível cancelar esta NF, pois já existe NF recebida vinculada a esta devolução que não está cancelada. Verifique se a NF recebida deve ser cancelada antes de prosseguir.<br><br>Notas recebidas: {$numeroNotas}";
                }
            }
            
            //-- VERIFICA SE O USUARIO TEM ACESSO A OPCAO DE CANCELAR PEDIDO PENDENTE
            $sqlC030 = mysql_query("SELECT * FROM C030 WHERE C030_C021_Id = '{$g['c021']['C021_Id']}' AND c030_C029_Id = 169 AND C030_Acesso_Liberado = 'S'");
            if (mysql_num_rows($sqlC030) == 0) {
                return "Acesso não disponível para o perfil {$g['c021']['C021_Nome_Perfil']}!";
            }
            
            //Regra comentada, o prazo varia de UF para UF
            //if ($mT007['T007_Flag_ACP'] == 6) {
            //    $cSql_T007_EXP = mysql_query("SELECT timediff(now(),T007_Data_Hora_Protocolo_Nfe) FROM T007 WHERE T007_Id='$T007_Id'");
            //    $mT007_EXP     = mysql_fetch_array($cSql_T007_EXP);
            //    $Horas_Emissao = str_replace(":", "", $mT007_EXP[0]);
            //    if ($Horas_Emissao >= 1680000) {
            //        return "Nota foi emitida a mais de 168 horas. A Sefaz não aceita cancelamentos após esse prazo";
            //    }
            //}
            return true;
        }

