        /**
         * cancelarNotaFiscal
         *
         * @param Form $form
         * @param String $T007_Id
         * @return String/bool
         */        
        public function cancelarNotaFiscal($form, $T007_Id)
        {
            global $g;

            //-- VERIFICA SE O USUARIO TEM ACESSO A OPCAO DE CANCELAR PEDIDO PENDENTE
            $sqlC030 = mysql_query("SELECT * FROM C030 WHERE C030_C021_Id = '{$g['c021']['C021_Id']}' AND c030_C029_Id = 169 AND C030_Acesso_Liberado = 'S'");
            $erro = mysql_error();
            if (!empty($erro)){
                return "Erro: " . $erro;
            }

            if (mysql_num_rows($sqlC030) == 0) {
                return "Acesso não disponível para o perfil {$g['c021']['C021_Nome_Perfil']}!";
            }
            //-- ELIMINA O ENTER
            $AmbienteCancelamento         = $form->campoValorEnviado('AmbienteCancelamento');
            $T007_Observacao_Cancelamento = $form->campoValorEnviado('T007_Observacao_Cancelamento');
            $T007_Observacao_Cancelamento = str_replace("\r", "", $T007_Observacao_Cancelamento);
            $T007_Observacao_Cancelamento = str_replace("\n", " ", $T007_Observacao_Cancelamento);
            $T007_Observacao_Cancelamento = trim($T007_Observacao_Cancelamento);
            
            $T007_Observacao_Cancelamento = gLimpaAcentos($T007_Observacao_Cancelamento);
            if (empty($T007_Observacao_Cancelamento)) {
                return "Preencha o motivo do cancelamento!";
            }

            $cSql_T007 = mysql_query("SELECT * FROM T007 LEFT JOIN C004 ON C004_Id=T007_C004_Id LEFT JOIN D018 ON D018_Id = C004_D018_Id WHERE T007_Id='{$T007_Id}'");
            $erro = mysql_error();
            if (!empty($erro)){
                return "Erro: " . $erro;
            }
            $mT007     = mysql_fetch_array($cSql_T007);
            
            if ($mT007['T007_Versao_NFe'] == '1.10') {
                //--  Class para gerar o arquivo da NFe VERSAO 1.10
                include $g['pathRaiz'] . "hardness/class/nfe.class.php";
            } elseif ($mT007['T007_Versao_NFe'] == '2.00') {
                //--  Class para gerar o arquivo da NFe VERSAO 2.00
                include $g['pathRaiz'] . "hardness/class/nfe.class.php";
            } elseif ($mT007['T007_Versao_NFe'] == '3.10') {
                //--  Class para gerar o arquivo da NFe VERSAO 2.00
                include $g['pathRaiz'] . "hardness/class/nfe4.class.php";
            
            } else if ($mT007['T007_Versao_NFe'] == '4.00') {
                include $g['pathRaiz'] . "hardness/class/nfe4.class.php";

            } else {
                $cClausula = " UPDATE T007 SET ";
                $cClausula .= " T007_Versao_NFe = '1.10' ";
                $cClausula .= " WHERE T007_Id='{$T007_Id}' ";
                mysql_query($cClausula);
                
                $cSql_T007 = mysql_query("SELECT * FROM T007 LEFT JOIN C004 ON C004_Id=T007_C004_Id WHERE T007_Id='{$T007_Id}'");
                $erro = mysql_error();
                if (!empty($erro)){
                    return "Erro: " . $erro;
                }
                
                $mT007     = mysql_fetch_array($cSql_T007);
                
                if ($mT007['T007_Versao_NFe'] != '1.10' AND $mT007['T007_Versao_NFe'] != '2.00') {
                    return "Versão não foi definida na nota fiscal (T007_Versao_NFe), verifique!";
                }
                
                //--  Class para gerar o arquivo da NFe VERSAO 1.10
                include $g['pathDadosAntigo'] . "/../../class/nfe.class.php";
            }

            mysql_query("SET AUTOCOMMIT=0");
            mysql_query("START TRANSACTION");
            
            if ($mT007['T007_Flag_ACP'] != 6 && $mT007['T007_Flag_ACP'] != 8) {
                //-- CANCELAMENTO DA NOTA FISCAL NORMAL
                return $this->gravarCancelamento($T007_Id, $T007_Observacao_Cancelamento);
            } else {

                $T002=mysql_query("SELECT T002_Numero_Duplicata,T002_T035_Id FROM T002 WHERE T002_T007_Id=T007_Id WHERE T007_Id='{$T007_Id}'");
                while($mT002 = mysql_fetch_array($T002)){
                    if(!empty($mT002['T002_T035_Id'])){
                        return "Existe títulos que já foram enviados ao banco. Por favor, consulte o financeiro.";
                    }
                }
                //-- CANCELAMENTO DA NOTA FISCAL ELETRONICA
                if (strlen($T007_Observacao_Cancelamento) < 15) {
                    mysql_query("ROLLBACK");
                    return "Justificativa de cancelamento deve ter mais de 15 caracteres";
                } elseif (strlen($T007_Observacao_Cancelamento) > 255) {
                    mysql_query("ROLLBACK");
                    return "Caracteres excedidos para justificativa de cancelamento. Ultrapassou 255 caracteres";
                }
                
                if (empty($mT007['T007_Numero_Protocolo_Nfe'])) {
                    mysql_query("ROLLBACK");
                    return "Esta NF-e ainda não tem protocolo de autorização, nao pode ser cancelada";
                }
                
                if (empty($mT007['T007_Chave_Acesso_Nfe'])) {
                    mysql_query("ROLLBACK");
                    return "Esta NF-e não possui chave de acesso, nao pode ser cancelada";
                }
                
                if ($g['C020']['C020_NFe_Treinamento'] == 'S' AND $mT007['T007_Ambiente_NFe'] != '2') {
                    return "NFe esta definida como treinamento e o ambiente não é homologacao, verifique!";
                }
                
                if ($g['C020']['C020_NFe_Treinamento'] == 'S') {
                    $cClausula = " UPDATE T007 SET ";
                    $cClausula .= " T007_Numero_Protocolo_Cancelamento_Nfe = T007_Chave_Acesso_Nfe, ";
                    $cClausula .= " T007_Data_Hora_Cancelamento_Nfe = now() ";
                    $cClausula .= " WHERE T007_Id='{$T007_Id}' ";
                    mysql_query($cClausula);
                    $cErro = mysql_error();
                    if (!empty($cErro)) {
                        mysql_query("ROLLBACK");
                        return "Ocorreu um erro ao gravar o retorno do Sefaz na nota fiscal\nPor favor entre em contato com o suporte \nErro:$cErro\nClausula:$cClausula";
                    }
                    return $this->gravarCancelamento($T007_Id, $T007_Observacao_Cancelamento);
                } else {

                    //-- $Diretorio_NFe é definido no arquivo include/pasta_usuario.inc
                    $oNFE = new classeNFe($mT007['T007_Flag_ACP']);
                    $oNFE->setPastaArquivoXML($g['pathDadosAntigo'] . "nfe/xml");
                    
                    $oNFE->setUFEmitente($mT007['T007_Empresa_Usuaria_Uf']);
                    $oNFE->setCodigoUFEmitente($mT007['T007_Empresa_Usuaria_Codigo_Estado_IBGE']);
                    $oNFE->setSenhaCertificado($mT007['C004_Senha_Certificados']);
                    $oNFE->setCertificadoPEM($mT007['C004_Localizacao_Certificados'] . $mT007['T007_C004_Id'] . ".pem");
                    
                    $oNFE->setIdentAmbiente($mT007['T007_Ambiente_NFe']); //--  1-Produção / 2-Homologação
                    /*
                    if ($mT007['T007_Flag_Contingencia'] == 'S') {
                        $oNFE->setTipoDocAuxiliar('2');
                    } elseif ($mT007['T007_Flag_SCAN'] == 'S') {
                        //$oNFE->setTipoDocAuxiliar('3');

                        if ($mT007['D018_UF'] == 'AC' || $mT007['D018_UF'] == 'AL' || $mT007['D018_UF'] == 'AP' || $mT007['D018_UF'] == 'MG' || $mT007['D018_UF'] == 'PB' || $mT007['D018_UF'] == 'RJ' || $mT007['D018_UF'] == 'RS' || $mT007['D018_UF'] == 'RO' || $mT007['D018_UF'] == 'RR' || $mT007['D018_UF'] == 'SC' || $mT007['D018_UF'] == 'SE' || $mT007['D018_UF'] == 'SP' || $mT007['D018_UF'] == 'TO' || $mT007['D018_UF'] == 'DF') {
                            $oNFE->setTipoDocAuxiliar(6);   // SVC-AN
                        } else {
                            $oNFE->setTipoDocAuxiliar(7);   // SVC-RS
                        }

                        //SE FOR  NFC-E
                        if($mT007['T007_Flag_ACP']=='8'){
                            $oNFE->setTipoDocAuxiliar(9);   // SCAN
                        }
                    } else {
                        $oNFE->setTipoDocAuxiliar('2');
                    }*/
                    if($AmbienteCancelamento=='contingencia'){
                        if ($mT007['D018_UF'] == 'AC' || $mT007['D018_UF'] == 'AL' || $mT007['D018_UF'] == 'AP' || $mT007['D018_UF'] == 'MG' || $mT007['D018_UF'] == 'PB' || $mT007['D018_UF'] == 'RJ' || $mT007['D018_UF'] == 'RS' || $mT007['D018_UF'] == 'RO' || $mT007['D018_UF'] == 'RR' || $mT007['D018_UF'] == 'SC' || $mT007['D018_UF'] == 'SE' || $mT007['D018_UF'] == 'SP' || $mT007['D018_UF'] == 'TO' || $mT007['D018_UF'] == 'DF'  || $mT007['D018_UF'] == 'ES') {
                            $oNFE->setTipoDocAuxiliar(6);   // SVC-AN
                        } else {
                            $oNFE->setTipoDocAuxiliar(7);   // SVC-RS
                        }

                        //SE FOR  NFC-E
                        if($mT007['T007_Flag_ACP']=='8'){
                            $oNFE->setTipoDocAuxiliar(9);   // SCAN
                        }
                    } else {
                        $oNFE->setTipoDocAuxiliar('2');
                    }
                    $oNFE->setT007Id($T007_Id);
                    $oNFE->setModeloCertificado($g['C020']['C020_NFe_Tipo_Certificado']);
                    
                    if ($mT007['T007_Versao_NFe'] == '1.10')
                        $oNFE->setWebService();
                    
                    $oNFE->setCertificadoHardness($g['pathDadosAntigo'] . "/../../principal/hardness.pem");
                    
