                        $cNumero_Protocolo = $oNFE->nProt;
                        $Data_Recebimento  = $oNFE->dhRecbto;
                        $Data_Recebimento  = str_replace("T", " ", $Data_Recebimento);
                        $Data_Recebimento  = substr($Data_Recebimento, 0, 19);
                        
                        if(empty($cNumero_Protocolo)){
                            if (!empty($mT007['T007_Numero_Protocolo_Cancelamento_Nfe'])){
                                $cNumero_Protocolo = $mT007['T007_Numero_Protocolo_Cancelamento_Nfe'];
                            } else {
                                $logErro = $oNFE->mErrorMsg;
                                $logErro = $logErro[0];
                                mysql_query("ROLLBACK");
                                return "Erro ao cancelar a nota fiscal, não retornou PROTOCOLO DE CANCELAMENTO, favor verificar. ($logErro)";
                            }
                        }
                        $cClausula = " UPDATE T007 SET ";
                        $cClausula .= " T007_Numero_Protocolo_Cancelamento_Nfe = '$cNumero_Protocolo', ";
                        $cClausula .= " T007_Data_Hora_Cancelamento_Nfe = '$Data_Recebimento' ";
                        $cClausula .= " WHERE T007_Id='{$T007_Id}' ";
                        mysql_query($cClausula);
                        $cErro = mysql_error();
                        if (!empty($cErro)) {
                            mysql_query("ROLLBACK");
                            return "Ocorreu um erro ao gravar o retorno do Sefaz na nota fiscal\nPor favor entre em contato com o suporte \nErro:$cErro\nClausula:$cClausula";
                        }
                        $this->gravarCancelamento($T007_Id, $T007_Observacao_Cancelamento);
                    } else {
                        mysql_query("ROLLBACK");
                        return "Problemas com os servidores do Sefaz: " . $oNFE->getMotivo();
                    }
                }
            }
            mysql_query("COMMIT");

            $this->emailCancelamentoNF($T007_Id);

            return true;
        }
        
        /**
         * pagamento
         *
         * @param String $T007_Id
         * @param String $T007_Observacao_Cancelamento
         * @return true
         */        
        public function gravarCancelamento($T007_Id, $T007_Observacao_Cancelamento)
        {
            mysql_query("SET AUTOCOMMIT=1");
            $T007_Observacao_Cancelamento = mysql_real_escape_string($T007_Observacao_Cancelamento);
            $sqlT007                      = mysql_query("SELECT * FROM T007 WHERE T007_Id = '{$T007_Id}'");
