						T007_Valor_Total_PIS=0,
						T007_Valor_Total_COFINS=0
					WHERE T007_Id='{$T007_Id}'");
            
            //-- Limpa o Flag de classificacao do item
            $sql = mysql_query("UPDATE T008 SET T008_Flag_Classificacao=0 WHERE T008_T007_Id='{$T007_Id}'");
            
            //-- Cancelando Contas a Receber
            mysql_query("UPDATE T002 
						SET T002_Flag_Cancelada='S',
							T002_Data_Recebimento=current_date(),
							T002_Observacao_2='*** NF CANCELADA ***',
							T002_Valor_Duplicata=0,
							T002_Valor_Total=0,
							T002_Valor_Comissao=0,
                            T002_Percentual_Comissao=0,
                            T002_Valor_Comissao_Representante=0,
                            T002_Percentual_Comissao_Representante=0,
                            T002_Valor_Total_Comissao_Externo=0,
                            T002_Percentual_Comissao_Externo=0,
                            T002_Valor_Total_Comissao_Usuario=0,
                            T002_Percentual_Comissao_Usuario=0
						WHERE T002_T007_Id='{$T007_Id}'");

            //-- Cancelando boleto se existir
            $T002 = mysql_query("SELECT T002_T117_Id
                                   FROM T002
                                  WHERE T002_T007_Id='{$T007_Id}'
                                    AND IFNULL(T002_T117_Id,0) > 0");

            while($mT002 = mysql_fetch_assoc($T002)){                
                mysql_query("UPDATE T117
                                SET T117_Flag_Cancelado = 'S'
                              WHERE T117_Id = '{$mT002['T002_T117_Id']}'");
            }
            
            //-- Cancelando Contas a Pagar
            mysql_query("UPDATE T015 
						SET T015_Flag_Cancelada='S',
							T015_Data_Pagamento=current_date(),
							T015_Observacao_2='*** NF CANCELADA ***',
							T015_Valor_Duplicata=0,
							T015_Valor_Total=0
						WHERE T015_T007_Id='{$T007_Id}'");
            
            $cSql = mysql_query("UPDATE T001 SET T001_Flag_Operacao='C' WHERE T001_T007_Id='{$T007_Id}'");
            
            $cSql_T008 = mysql_query("SELECT D006_Flag_Estoque,
										     T008_D009_Id,
                                             T008_Quantidade,
                                             T007_D024_Id,
                                             T008_Id,
                                             T007_Id,
                                             T008_C004_Id,
                                             T007_D006_Id,
                                             T008_Codigo_Produto,
                                             T007_Numero_Nota_Fiscal,
