						           LEFT JOIN T007 ON T008_T007_Id=T007_Id
						           LEFT JOIN D006 ON T007_D006_Id=D006_Id
						           LEFT JOIN D009 ON D009_Id=T008_D009_Id
						           LEFT JOIN D049 ON D049_Id=D009_D049_Id
								       WHERE T008_T007_Id='{$T007_Id}'");
            
            while ($mT008 = mysql_fetch_array($cSql_T008)) {
                ///////////////////////////////////////////////////////////////////////////////////////////////////
                //-- INVERSAO DOS FLAG POR SER UM CANCELAMENTO
                ///////////////////////////////////////////////////////////////////////////////////////////////////
                if ($mT008['D006_Flag_Estoque'] == 'D') {
                    $Flag_Operacao_Historico = "E";
                } elseif ($mT008['D006_Flag_Estoque'] == 'C') {
                    $Flag_Operacao_Historico = "S";
                } elseif ($mT008['D006_Flag_Estoque'] == 'N') {
                    $Flag_Operacao_Historico = "N";
                }
                ///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
                // ENCONTRA O ID DO T066
                ///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
                $cSql_T066 = mysql_query("SELECT T066_Id FROM T066 WHERE T066_D048_Id='$D048_Id' AND T066_D009_Id='$mT008[T008_D009_Id]'");
                $mT066     = mysql_fetch_array($cSql_T066);
                
                require_once('bibliotecas/classes/CAD002.php');
                $CAD002 = new CAD002();
                $CAD002->D001_reprocessa_historico(0, $mT008['T008_D009_Id'], 20);
            }
            
            $sqlUpdD024 = " UPDATE D024 SET";
            $sqlUpdD024 .= " D024_Data_Primeira_Compra = T007_Primeira_Ultima_Compra(1,D024_Id),";
            $sqlUpdD024 .= " D024_Data_Ultima_Compra = T007_Primeira_Ultima_Compra(2,D024_Id),";
            //Function parametro = 3 retorna a empresa da ultima compra
            $sqlUpdD024 .= " D024_C004_Id_Ultima_Compra = T007_Primeira_Ultima_Compra(3,D024_Id)";
            $sqlUpdD024 .= " WHERE D024_Id=$mT007[T007_D024_Id]";
            $cmD204 = mysql_query($sqlUpdD024);
            
            // Se existir mais de uma nota relacionada ao mesmo pedido o pedido se mantém coletado
            $T005=mysql_query("SELECT * FROM T007 WHERE T007_T005_Id='{$mT007['T007_T005_Id']}'");
            if(mysql_num_rows($T005) < 2){
                $cSql = mysql_query("UPDATE T005 
    								SET T005_Flag_Status='3',
                                        T005_Nome_Status = T005_Status_Pedido (T005_Flag_Status, 1),
    									T005_Flag_Situacao='1',
    									T005_Flag_Almoxarifado='S'
    								WHERE T005_Id='{$mT007['T007_T005_Id']}'");
            }
            /*	
            $cSql=mysql_query("UPDATE T005 
            SET T005_Flag_Status='3', T005_Nome_Status = T005_Status_Pedido (T005_Flag_Status, 1),
            T005_Flag_Situacao='1'
            WHERE T005_Id='$mT007[T007_T005_Id]'
            AND T005_Flag_Almoxarifado='S'");
            
            $cSql=mysql_query("UPDATE T005 
            SET T005_Flag_Status='25', T005_Nome_Status = T005_Status_Pedido (T005_Flag_Status, 1),
            T005_Flag_Situacao='1'
            WHERE T005_Id='$mT007[T007_T005_Id]'
            AND T005_Flag_Almoxarifado!='S'");
            
            */
            $this->gravarCancelamentoAdicionais($T007_Id);
        
            mysql_query("UPDATE T072
					LEFT JOIN T007 ON T007_Id=T072_T007_Id
					SET T072_Flag_Atualizado='S'
					WHERE T007_Flag_Cancelada='S'");
            return true;
        }
        
        /**
         * estornarCancelamento
         *
         * @param String $T007_Id
         * @param String $T007_Observacao_Cancelamento
         * @return true
         */        
        public function estornarCancelamento($T007_Id)
        {
            require_once('bibliotecas/classes/CAD002.php');
            $CAD002 = new CAD002();

            mysql_query("SET AUTOCOMMIT=1");

            $T007_Observacao_Cancelamento = mysql_real_escape_string($T007_Observacao_Cancelamento);
            $sqlT007                      = mysql_query("SELECT T007_Numero_Protocolo_Nfe,
                                                                T007_D024_Id,
                                                                T007_T005_Id,
                                                                T007_Numero_Protocolo_Cancelamento_Nfe
                                                           FROM T007 WHERE T007_Id = '{$T007_Id}'");
            $mT007                        = mysql_fetch_array($sqlT007);

            if (!empty($mT007['T007_Numero_Protocolo_Cancelamento_Nfe'])){
               return "A nota fiscal possui protocolo de cancelamento, não pode ser recuperada.";
            }

            //-- Recuperando T007
            mysql_query("UPDATE T007
					SET T007_Flag_Cancelada='N',
						T007_Observacao_Cancelamento='{$T007_Observacao_Cancelamento}',
                        T007_Numero_Protocolo_Nfe='',
                        T007_Flag_Denegado=''	
                  WHERE T007_Id='{$T007_Id}'");
                  
            mysql_query("call T007_Gravar_Totalizacao_4('{$T007_Id}')");

            mysql_query("UPDATE T007
					SET T007_Numero_Protocolo_Nfe='{$mT007['T007_Numero_Protocolo_Nfe']}'
                  WHERE T007_Id='{$T007_Id}'");
            
            $cSql = mysql_query("UPDATE T001 SET T001_Flag_Operacao='S' WHERE T001_T007_Id='{$T007_Id}'");
            
            $cSql_T008 = mysql_query("SELECT T008_D009_Id
								 FROM T008
								WHERE T008_T007_Id='{$T007_Id}'");
            
            while ($mT008 = mysql_fetch_array($cSql_T008)) {
                $CAD002->D001_reprocessa_historico(0,$mT008['T008_D009_Id'],500);
            }

            return true;
        }


        /**
         * ven003excluirNota
         *
         * @param String $T007_Id
         * @return String/bool
         */        
        public function ven003excluirNota($T007_Id, $PDV = false)
        {
            global $g;
            require_once('bibliotecas/classes/CAD002.php');
            $CAD002 = new CAD002();

            $cClausula = " SELECT ";
            $cClausula .= " * ";
            $cClausula .= " FROM T007 ";
            $cClausula .= " WHERE T007_Id='{$T007_Id}' ";
            $cSql_T007 = mysql_query($cClausula);
            $mT007     = mysql_fetch_array($cSql_T007);
            $T005_Id = $mT007['T007_T005_Id'];
            
            //Verifica se a nota fiscal possui protocolo
            $sqlT007 = mysql_query("SELECT T007_Id FROM T007 WHERE T007_Id = '{$T007_Id}' AND (ifnull(T007_Numero_Protocolo_Nfe,'') != '' or ifnull(T007_Numero_Protocolo_Cancelamento_Nfe,'') != '' or ifnull(T007_Protocolo_Inutilizacao,'') != '')");
            if (mysql_num_rows($sqlT007) > 0) {
                mysql_query("update C007 set C007_T007_Id_PDV = '0' where C007_Id = '{$g['usuarioAtual']}' AND C007_T007_Id_PDV = '{$T007_Id}'");
                return "Esta nota possui protocolo de transmissão, cancelamento ou inutilização. Não pode ser excluida.";
            }

            //Verifica se a nota fiscal possuí uma remessa bancária
            $sqlT007 = mysql_query("SELECT * FROM T007 LEFT JOIN T002 ON T002_T007_Id = T007_Id WHERE T007_Id = '{$T007_Id}' AND T002_T035_Id > 0");
            if (mysql_num_rows($sqlT007) > 0) {
                return (mysql_num_rows($sqlT007) > 1) ? "Existem títulos a receber que estão em remessa bancária, por favor verifique." : "Existe título a receber que está em remessa bancária, por favor verifique.";
            }
            
            $sqlT002 = mysql_query("SELECT * FROM T002 WHERE T002_T007_Id != '{$T007_Id}' AND T002_T117_Id IN (SELECT DISTINCT T002_T117_Id FROM T002 WHERE T002_T007_Id = '{$T007_Id}' AND IFNULL(T002_T117_Id,0)>0)");
            if (mysql_num_rows($sqlT002) > 0) {
                return (mysql_num_rows($sqlT002) > 1) ? "Existem boletos que estão relacionados a outras notas fiscais, por favor verifique." : "Existe boleto relacionado a outra nota fiscal, por favor verifique.";
            }

            if($mT007['T007_Flag_ACP'] == 6 || $mT007['T007_Flag_ACP'] == 8){
                $T127 = mysql_query("SELECT T127_Retorno_Sefaz 
                                       FROM T127 
                                      WHERE T127_Numero_Nota_Fiscal='{$mT007['T007_Numero_Nota_Fiscal']}' 
                                        AND T127_C004_Id='{$g['empresaAtual']}' 
                                        AND T127_Modelo=IF('{$mT007['T007_Flag_ACP']}' = '6', '55', '65') 
                                        AND (T127_Codigo_Retorno = '539' OR T127_Codigo_Retorno = '204' OR T127_Codigo_Retorno = '635')
                                      LIMIT 1");

                if(mysql_num_rows($T127) > 0){
                    $mT127 = mysql_fetch_array($T127);
                    return "Nota fiscal já está autorizada no portal, não pode mais ser excluída, tente transmitir novamente.<br>Retorno Sefaz: {$mT127['T127_Retorno_Sefaz']}";
                }
            }
            
            mysql_query("SET AUTOCOMMIT=0");
            mysql_query("START TRANSACTION");
            
            mysql_query("DELETE FROM T001 WHERE T001_T007_Id = '{$T007_Id}'");
            if (mysql_error()) {
                mysql_query("ROLLBACK");
                return "Erro: " . mysql_error();
            }

            // deletando os registros da tabela estendida T008A vinculado ao T008
            mysql_query("DELETE T008A FROM T008A LEFT JOIN T008 ON T008_Id = T008A_T008_Id WHERE T008_T007_Id = '{$T007_Id}'");
            if (mysql_error()) {
                mysql_query("ROLLBACK");
                return "Erro: " . mysql_error();
            }

            // Selecionando os T008 Antes da serem excluídos para serem usados na chamada do reprocessa histórico.
            $sqlT008 = mysql_query("SELECT T008_D009_Id, T008_Id, T008_T008_Id, T008_Quantidade FROM T008 WHERE T008_T007_Id = '{$T007_Id}'");
            
            mysql_query("DELETE FROM T008 WHERE T008_T007_Id = '{$T007_Id}'");
            if (mysql_error()) {
                mysql_query("ROLLBACK");
                return "Erro: " . mysql_error();
            }
            
            $sqlT002 = mysql_query("SELECT DISTINCT T002_T117_Id FROM T002 WHERE T002_T007_Id = '{$T007_Id}' AND T002_T117_Id > 0");
            while ($T002 = mysql_fetch_array($sqlT002)) {
                mysql_query("DELETE FROM T117 WHERE T117_Id = '{$T002['T002_T117_Id']}'");
                if (mysql_error()) {
                    mysql_query("ROLLBACK");
                    return "Erro: " . mysql_error();
                }
            }
            
            mysql_query("DELETE FROM T002 WHERE T002_T007_Id = '{$T007_Id}'");
            if (mysql_error()) {
                mysql_query("ROLLBACK");
                return "Erro: " . mysql_error();
            }

            mysql_query("DELETE FROM T015 WHERE T015_T007_Id = '{$T007_Id}'");
            if (mysql_error()) {
                mysql_query("ROLLBACK");
                return "Erro: " . mysql_error();
            }
            
            mysql_query("DELETE FROM T019 WHERE T019_T007_Id = '{$T007_Id}'");
            if (mysql_error()) {
                mysql_query("ROLLBACK");
                return "Erro: " . mysql_error();
            }
            
            mysql_query("DELETE FROM T007 WHERE T007_Id = '{$T007_Id}'");
            if (mysql_error()) {
                mysql_query("ROLLBACK");
                return "Erro: " . mysql_error();
            }

            $C004 = mysql_query("SELECT C004_Ultimo_Numero_Nota_Fiscal_Eletronica,
                                        C004_Ultimo_Numero_NFCe,
                                        C004_Ultimo_Numero_ACP,
                                        C004_Ultimo_Numero_Cupom_Fiscal
                                   FROM C004
                                  WHERE C004_Id = {$mT007['T007_C004_Id']}");
            $mC004 = mysql_fetch_array($C004);
            if (mysql_error()) {
                mysql_query("ROLLBACK");
                return "Erro: " . mysql_error();
            }

            if($T005_Id > 0){
                // Acabou de fazer o lançamento no T007_trigger_antes_exclusao 
                $T178 = mysql_query("SELECT T178_Id
                                       FROM T178
                                      WHERE T178_T005_Id = '{$T005_Id}'
                                        AND T178_Descricao = 'Nota fiscal excluída.'
                                   ORDER BY T178_Id DESC LIMIT 1");
                
                $mT178 = mysql_fetch_array($T178);
                mysqli_query("UPDATE T178 SET T178_C007_Id = '{$g['usuarioAtual']}' WHERE T178_Id = '{$mT178['T178_Id']}'");

            }

            if($mT007['T007_Flag_ACP'] == 3 && $mT007['T007_Numero_Nota_Fiscal'] == $mC004['C004_Ultimo_Numero_ACP']){

                $numeroAnterior = str_replace('A','',$mT007['T007_Numero_Nota_Fiscal']) - 1;
                $numeroAnterior = 'A'.$numeroAnterior;
                mysql_query("UPDATE C004 SET C004_Ultimo_Numero_ACP = '{$numeroAnterior}' WHERE C004_Id={$mT007['T007_C004_Id']}");

            } else if ($mT007['T007_Flag_ACP'] == 4 && $mT007['T007_Numero_Nota_Fiscal'] == $mC004['C004_Ultimo_Numero_Cupom_Fiscal']){

                $numeroAnterior = $mT007['T007_Numero_Nota_Fiscal'] - 1;
                mysql_query("UPDATE C004 SET C004_Ultimo_Numero_Cupom_Fiscal = '{$numeroAnterior}' WHERE C004_Id={$mT007['T007_C004_Id']}");

            } else if ($mT007['T007_Flag_ACP'] == 6 && $mT007['T007_Numero_Nota_Fiscal'] == $mC004['C004_Ultimo_Numero_Nota_Fiscal_Eletronica']){

                $numeroAnterior = $mT007['T007_Numero_Nota_Fiscal'] - 1;
                mysql_query("UPDATE C004 SET C004_Ultimo_Numero_Nota_Fiscal_Eletronica = '{$numeroAnterior}' WHERE C004_Id={$mT007['T007_C004_Id']}");

            } else if ($mT007['T007_Flag_ACP'] == 8 && $mT007['T007_Numero_Nota_Fiscal'] == $mC004['C004_Ultimo_Numero_NFCe']){

                $numeroAnterior = $mT007['T007_Numero_Nota_Fiscal'] - 1;
                mysql_query("UPDATE C004 SET C004_Ultimo_Numero_NFCe = '{$numeroAnterior}' WHERE C004_Id={$mT007['T007_C004_Id']}");
            }
            if (mysql_error()) {
                mysql_query("ROLLBACK");
                return "Erro: " . mysql_error();
            }

            /*
            if($T005_Id > 0){

                mysql_query("DELETE FROM T238 WHERE T238_T005_Id='{$T005_Id}'");
                if (mysql_error()) {
                    mysql_query("ROLLBACK");
                    return "Erro: " . mysql_error();
                }

                mysql_query("UPDATE T006 SET T006_Quantidade_Separacao=0 WHERE T006_T005_Id='{$T005_Id}'");
                if (mysql_error()) {
                    mysql_query("ROLLBACK");
                    return "Erro: " . mysql_error();
                }
            }*/
            
            /*
            * INICIANDO AS VERIFICAÇÕES PARA VER SE REALMENTE EXCLUIU OS REGISTROS.
            */

            // Verificando os hitóricos
            $T001 = mysql_query("SELECT * FROM T001 WHERE T001_T007_Id='{$T007_Id}'");
            $rT001 = mysql_num_rows($T001);
            if($rT001 > 0){
                mysql_query("ROLLBACK");
                return "Os registros referente ao histórico do produto (T001) não foram removidos. Por favor, contato o suporte técnico.";
            }

            // Verificando os itens da nota (T008)
            $T008 = mysql_query("SELECT * FROM T008 WHERE T008_T007_Id='{$T007_Id}'");
            
            $rT008 = mysql_num_rows($T008);
            if($rT008 > 0){
                mysql_query("ROLLBACK");
                return "Os registros referente aos produtos (T008) não foram removidos. Por favor, contato o suporte técnico.";
            }

            // Verificando os títulos e boletos
            $T002 = mysql_query("SELECT * FROM T002 WHERE T002_T007_Id='{$T007_Id}'");
            $rT002 = mysql_num_rows($T002);
            if($rT002 > 0){
                $erroT117=0;
                while($mT002=mysql_fetch_array($T002)){
                    $T117=mysql_query("SELECT * FROM T117 WHERE T117_T002_Id='{$mT002['T002_Id']}'");
                    $rT117=mysql_num_rows($T117);
                    if($rT117>0){
                        $erroT117++;
                    }
                }
                if($erroT117>0){
                    mysql_query("ROLLBACK");
                    return "o registros referente aos boletos (T117) e aos títulos a receber (T002) não foram removidos. Por favor, contato o suporte técnico.";
                }else{
                    mysql_query("ROLLBACK");
                    return "os registros referente aos títulos a receber (T002) não foram removidos. Por favor, contato o suporte técnico.";
                }
            }

            // Verificando os lançamentos bancários (T019)
            $T019 = mysql_query("SELECT * FROM T019 WHERE T019_T007_Id='{$T007_Id}'");
            $rT019 = mysql_num_rows($T019);
            if($rT019 > 0){
                mysql_query("ROLLBACK");
                return "o registros referente lançamentos financeiros (T019) não foram removidos. Por favor, contato o suporte técnico.";
            }

            // Verificando o resgitro da nota (T007)
            $T007 = mysql_query("SELECT * FROM T007 WHERE T007_Id='{$T007_Id}'");
            $rT007 = mysql_num_rows($T007);
            if($rT007 > 0){
                mysql_query("ROLLBACK");
                return "O registro referente a nota fiscal (T007) não foi removido. Por favor, contato o suporte técnico.";
            }

            if ($PDV === true) {
                mysql_query("update C007 set C007_T007_Id_PDV = '0' where C007_Id = '{$g['usuarioAtual']}' and C007_T007_Id_PDV='{$T007_Id}'");
            }


            while($mT008 = mysql_fetch_array($sqlT008)){
                // Retornando o Saldo no FIFO
                $T290 = mysql_query("SELECT T290_Quantidade,
                                            T290_T289_Id 
                                       FROM T290 
                                      WHERE T290_T008_Id='{$mT008['T008_Id']}'");

                
                while($mT290 = mysql_fetch_array($T290)){
                    mysql_query("UPDATE T289 SET 
                                        T289_Quantidade_Saldo = T289_Quantidade_Saldo + {$mT290['T290_Quantidade']}  
                                        WHERE T289_Id='{$mT290['T290_T289_Id']}'");
                }

                mysql_query("DELETE FROM T290 WHERE T290_T008_Id = '{$mT008['T008_Id']}'");

                $CAD002->D001_reprocessa_historico(0, $mT008['T008_D009_Id'],5,true);

                if($mT008['T008_T008_Id'] > 0 && $mT007['T007_Flag_Finalidade_NFe'] == 4){
                    //caso seja uma nota de devolução que está sendo excluída, reabre o FIFO                    
                    require_once("bibliotecas/classes/CAD002.php");
                    $CAD002 = new CAD002();                        
                    $CAD002->populaT290($mT008['T008_D009_Id'], $mT008['T008_T008_Id'], '','C', '', $mT008['T008_Quantidade'], '');
                }
            
            }

            mysql_query("COMMIT");

            return true;
        }
        
        /**
         * percentualDescontoCupom
         *
         * @param String $T007_Id
         * @return String
         */        
        function percentualDescontoCupom($T007_Id)
        {
            $T007_Id    = mysql_real_escape_string($T007_Id);
            $percentual = 0;
            $sql        = <<<EOT
SELECT 
	T007_Id, T007_Valor_Total, T007_Valor_Desconto
FROM T007
WHERE
	T007_Id = '{$T007_Id}'
EOT;
            $res        = mysql_query($sql);
            $row        = mysql_fetch_assoc($res);
            if ($row['T007_Valor_Desconto'] > 0) {
                $percentual = $row['T007_Valor_Desconto'] / ($row['T007_Valor_Desconto'] + $row['T007_Valor_Total']) * 100;
            }
            return $percentual;
        }
        
        /**
         * verificaAlcada
         *
         * @param String $T007_Id
         * @param bool $pedirLiberacao
         * @return String/bool
         */        
        public function verificaAlcada($T007_Id, $pedirLiberacao = false)
        {
            global $g;
            
            $sql     = "SELECT * FROM T007 WHERE T007_Id = '{$T007_Id}'";
            $resT007 = mysql_query($sql);
            $rowT007 = mysql_fetch_assoc($resT007);
            
            if ($rowT007['T007_Flag_Analise_Credito'] == 1) {
                if ($pedirLiberacao) {
                    mysql_query("UPDATE T007 SET T007_Flag_Analise_Credito = 0 WHERE T007_Id = '{$T007_Id}'");
                }
                return 'Nota já está aguardando liberação.<br/>Deseja cancelar pedido de liberação?';
            } else if ($rowT007['T007_Flag_Analise_Credito'] == 2) {
                return true;
            }
            
            // Verificação de alçada (personalizavél por empresa)
            //return true;
            
            $msg = '';
            
            if ($rowT007['T007_Pgto_Parcelas'] > 1) {
                if ($pedirLiberacao) {
                    mysql_query("UPDATE T007 SET T007_Flag_Analise_Credito = 1 WHERE T007_Id = '{$T007_Id}'");
                }
                $msg .= "- Número de parcelas<br/>";
            }
            
            if ($msg) {
                $msg = 'Existem restrições:<br/><br/>' . $msg . '<br/>Deseja pedir liberação?';
            }
            
            return !empty($msg) ? $msg : true;
        }
        
        /**
         * gerarDevolucaoNotaRecebida
         *
         * @param String $T013_Id
         * @param String $listaT013s
         * @param String $D024_Id
         * @param String $D006_Id
         * @param String $Observacao
         * @return String/bool
         */
        public function gerarDevolucaoNotaRecebida($T013_Id, $listaT013s, $D024_Id, $D006_Id, $Observacao, $T007_Flag_Indicador_Presenca,  $ipiNotaEspelho = false)
        {
            global $g;
            require_once('bibliotecas/classes/VEN001.php');
            $VEN001 = new VEN001();
            
            if ($T013_Id <= 0) {
                return gGeraAlertMsg("Atenção", "Selecione uma Nota Fiscal");
            }

            if ($D024_Id <= 0) {
                return gGeraAlertMsg("Atenção", "Selecione um Cliente");
            }
            
            if ($D006_Id <= 0) {
                $D006 = mysql_query("select D006_D006_Id 
                                       from T014 
                                  left join D006 on D006_Id=T014_D006_Id
                                      where T014_T013_Id={$T013_Id}");
                $mD006 = mysql_fetch_assoc($D006);
                $D006_Id = $mD006['D006_D006_Id'];
                $recebeuD006_Id = false;
            } else {
                $recebeuD006_Id = true;;
            }
            
            if (empty($Observacao)) {
                //return gGeraAlertMsg("Atenção", "Informe a observação que será impressa na Nota Fiscal");
            }
            
            $cClausula = " SELECT * FROM T013 WHERE T013_Id='{$T013_Id}'";
            $cSql_T013 = mysql_query($cClausula);
            $cErro     = mysql_error();
            if (!empty($cErro)) {
                return gGeraAlertMsg("Atenção", "Erro: " . str_replace(array("'",'"'), "", $cErro) . "\n" . str_replace(array("'",'"'), "", $cClausula));
            }

            // seleciona os dados da nota de devolução para inserir na nota fiscal
            $T007_Nota_Fiscal_Devolucao="";
            $T007_Nota_Fiscal_Devolucao_Data="";
            $idDevolucao=0;
            while($idDevolucao <  count($listaT013s)){
                $dadosDevolucao = mysql_query("SELECT T013_Numero_Nota_Fiscal, T013_Data_Emissao FROM T013 WHERE T013_Id='{$listaT013s[$idDevolucao]}'");
                $mDadosDevolucao = mysql_fetch_array($dadosDevolucao);
                $produtosDevolucao = mysql_query("SELECT T014_Quantidade_Devolucao FROM T014 WHERE T014_T013_Id='{$listaT013s[$idDevolucao]}'");
                $quantidadeProdutos=0;
                while($mProdutosDevolucao = mysql_fetch_array($produtosDevolucao)){
                    if($quantidadeProdutos <= 0){
                        if($mProdutosDevolucao['T014_Quantidade_Devolucao'] > 0.00){
                            $T007_Nota_Fiscal_Devolucao .= $mDadosDevolucao['T013_Numero_Nota_Fiscal'].";";
                            $T007_Nota_Fiscal_Devolucao_Data .= substr(gCorrigeData($mDadosDevolucao['T013_Data_Emissao']), 0, 10).";"; 
                            $quantidadeProdutos++;
                        }
                    }
                }                
                $idDevolucao++;
            }
            $mT013 = mysql_fetch_array($cSql_T013);
            
            $cClausula = "SELECT * FROM C004 LEFT JOIN D020 ON D020_Id=C004_D020_Id LEFT JOIN D018 ON D018_Id=D020_D018_Id WHERE C004_Id = '{$mT013['T013_C004_Id']}'";
            $cSql_C004 = mysql_query($cClausula);
            $cErro     = mysql_error();
            if (!empty($cErro)) {
                return gGeraAlertMsg("Atenção", "Erro: " . str_replace(array("'",'"'), "", $cErro) . "\n" . str_replace(array("'",'"'), "", $cClausula));
            }
            $mC004 = mysql_fetch_array($cSql_C004);
            
            $cClausula = "SELECT * FROM D024 LEFT JOIN D020 ON D020_Id=D024_D020_Id LEFT JOIN D018 ON D018_Id=D020_D018_Id LEFT JOIN D030 ON D030_Id=D024_D030_Id WHERE D024_Id='{$D024_Id}'";
            $cSql_D024 = mysql_query($cClausula);
            $cErro     = mysql_error();
            if (!empty($cErro)) {
                return gGeraAlertMsg("Atenção", "Erro: " . str_replace(array("'",'"'), "", $cErro) . "\n" . str_replace(array("'",'"'), "", $cClausula));
            }
            $mD024 = mysql_fetch_array($cSql_D024);
            
            $cClausula = "SELECT * FROM D006 LEFT JOIN D059 ON D059_Id=D006_D059_Id WHERE D006_Id='{$D006_Id}'";
            $cSql_D006 = mysql_query($cClausula);
            $cErro     = mysql_error();
