        /**
         * reimportarCupomFiscal
         *
         * @param String $T007_Id
         * @return String/bool
         */
        public function reimportarCupomFiscal($T007_Id)
        {
            global $g;
            $sqlT007 = mysql_query("SELECT * FROM T007 WHERE T007_Id = '{$T007_Id}'");
            $rowT007 = mysql_fetch_assoc($sqlT007);

            //C:\sgerp\exportacao\27112015\012711201500005725.txt
            $caminhoArquivo = explode("\\", $rowT007['T007_Nome_Arquivo_PDV']);
            $arquivo = $g['pathDados']."/PDV/{$caminhoArquivo[3]}/{$caminhoArquivo[4]}";
            $conteudo = file_get_contents($arquivo);

            $arrayDados = explode("\n", $conteudo);
            foreach ($arrayDados as $key => $linha) {
                $arrayDados[$key] = explode("|", trim($linha, '|'));
            }

            $C004_Id = '2'; //Fixo empresa 2 pois no programa PDV só existe uma filial
            mysql_query("SET AUTOCOMMIT=0");
            mysql_query("START TRANSACTION");
            /************** CABEÇALHO DO CUPOM FISCAL
            --------------------     regsai       ---------------------
            Nº Campo      Denominação do Campo             Tam Dec Tipo
            01 01         TIPO DO REGISTRO                 002 000    N
            02 CODFIL83   FILIAL                           002 000    N
            03 LANSAI83   CHAVE DO SITEMA                  009 000    N
            04 CLIFOR83   CLIENTE OU FORNECEDOR            001 000    C
            05 FORNCLI83  CODIGO CLIENTE OU FORNECEDOR     006 000    N
            06 NUMPDV83   NUMERO DO PDV                    003 000    N
            07 SERNOTA83  SERIE DA NOTA/CUPOM              003 000    C
            08 NUMNOTA83  NUMERO DA NOTA/CUPOM             008 000    N
            09 DATEMIS83  DATA EMISSAO                     008 000    D
            10 DATASAI83  DATA SAIDA                       008 000    D
            11 HORARIO83  HORA EMISSAO                     005 000    C
            12 VALCON83   VALOR TOTAL COM DESCONTO         013 002    N
            13 TOTDESC83  VALOR DESCONTO SUBTOTAL          013 002    N
            14 USUARIO83  USUARIO                          010 000    C
            15 AVISPRAZ83 (A)VISTA (P)RAZO                 001 000    C
            16 SITNOTA83  SITUACAO (N)ORMAL (C)ANCELADA    001 000    C
            17 PEDIDO     NUMERO DO PEDIDO                 006 000    N
            18 COO        COO                              006 000    N
            19 CPFCLIENTE CPF DO CLIENTE                   014 000    C
            20 TIPOPED    TIPO DO PEDIDO (D)AV (P)RE-VENDA 001 000    C
            21 OPERADOR83 OPERADOR                         003 000    N
            ***********************************************************/

            //Percentual comissao é zerado para que a comissao seja calculada corretamente
            $cab = $arrayDados[0];
            $valorProdutosSemDesconto = $cab[11] + $cab[12];
            $sql = <<<EOT
                UPDATE T007 SET
                    T007_Valor_Total = '{$cab[11]}',
                    T007_Valor_Total_Produtos = '{$cab[11]}',
                    T007_Valor_Total_Produtos_Sem_Desconto = '{$valorProdutosSemDesconto}',
                    T007_Valor_Desconto = '{$cab[12]}'
                WHERE T007_Id = '{$T007_Id}'
EOT;
            mysql_query($sql);
            $erro = mysql_error();
            if (!empty($erro)) {
                mysql_query("ROLLBACK");
                return "Erro: " . $erro;
            }

            /***************** ITENS DO CUPOM FISCAL
            ---------------------     movpro      ---------------------
            Nº Campo      Denominação do Campo             Tam Dec Tipo
            01 02         TIPO DO REGISTRO                 002 000    N
            02 N/C        SITUACAO PRODUTO (N)ORMAL (C)ANC.001 000    C
            03 CODPRO05   CODIGO PRODUTO                   006 000    N
            04 QTDEMOV05  QUANTIDADE PRODUTO               011 003    N
            05 PRECO05    VALOR DO PRODUTO                 013 006    N
            06 DESCNOTA05 DESCONTO NO PROTUDO              009 005    N
            07 PRECONOT05 VALOR DO PRODUTO COM DESCONTO    009 005    N
            08 QTDEEMB05  QUANTIDADE EMBALAGEM             009 003    N
            09 ORDPROD05  ORDEM PRODUTO                    003 000    N
            10 CODVEND05  VENDEDOR                         003 000    N
            11 ALIQICM05  ALIQUOTA ICMS                    005 002    N
            12 UNIDADE05  UNIDADE PRODUTO                  002 000    C
            13 CODBARRAS  CODIGO DE BARRAS DO PRODUTO      014 000    N
            **********************************************************/
            $sqlT008 = mysql_query("SELECT T008_Id, D001_Id, T008_Quantidade FROM T008
                                                  LEFT JOIN D009 ON D009_Id=T008_D009_Id
                                                  LEFT JOIN D049 ON D049_Id=D009_D049_Id
                                                  LEFT JOIN D001 ON D001_Id=D049_D001_Id
                                                  WHERE T008_T007_Id = '{$T007_Id}'");
            while($rowT008 = mysql_fetch_array($sqlT008)){
                foreach ($arrayDados as $key => $linha) {
                    if($linha[0] != '02') { continue; }
                    if($linha[3] != $rowT008['T008_Quantidade'] || $linha[2] != $rowT008['D001_Id']) { continue; }

                    $linha[10] = ($linha[10] == 99.99) ? 0 : $linha[10];
                    $desc = (100-$linha[5]);
                    //$percentualDesconto = (($linha[6]-$linha[8])/$linha[6])*100;
                    mysql_query("UPDATE T008 SET
                            T008_Quantidade = '{$linha[3]}',
                            T008_Valor_Preco_Sem_Desconto_Unitario = '{$linha[6]}',
                            T008_Valor_Desconto_Unitario = '{$desc}',
                            T008_Valor_Preco_Unitario = '{$linha[6]}',
                            T008_Aliquota_ICMS = '{$linha[10]}',
                            T008_Valor_Preco_Original = '{$linha[4]}',
                            T008_Percentual_Desconto = '{$linha[5]}'
                        WHERE T008_Id = '{$rowT008['T008_Id']}'");
                    $erro = mysql_error();
                    if (!empty($erro)) {
                        mysql_query("ROLLBACK");
                        return "Erro: " . $erro;
                    }

                    mysql_query("call T008_Gravar_Totalizacao_4('{$rowT008['T008_Id']}');");
                    break;
                }
            }
            mysql_query("UPDATE T007 SET T007_Percentual_Comissao = '0' WHERE T007_Id = '{$T007_Id}'");
            mysql_query("COMMIT");
            mysql_query("SET AUTOCOMMIT=1");
            mysql_query("CALL T007_Gravar_Totalizacao_4('{$T007_Id}');");
            return true;
        }

        /**
         * corrigirDiferencaDesconto
         *
         * @param String $T007_Id
         * @return String/bool
         */
        public function corrigirDiferencaDesconto($T007_Id)
        {
            $sqlDesc = mysql_query("SELECT round(SUM(T008_Valor_Total_Desconto),2) as somaDesconto, round(T007_Valor_Desconto,2) as totalDesconto FROM T008 LEFT JOIN T007 ON T007_Id = T008_T007_Id WHERE T007_Id='{$T007_Id}';");
            $rowDesc = mysql_fetch_assoc($sqlDesc);

            if($rowDesc['somaDesconto'] != $rowDesc['totalDesconto']){
                $diferenca = $rowDesc['somaDesconto'] - $rowDesc['totalDesconto'];

                $sqlT008 = mysql_query("SELECT T008_Id FROM T008 WHERE T008_T007_Id = '{$T007_Id}' ORDER BY T008_Valor_Total_Preco DESC LIMIT 1");
                $rowT008 = mysql_fetch_assoc($sqlT008);
                mysql_query("UPDATE T008 SET T008_Valor_Total_Desconto = T008_Valor_Total_Desconto - ({$diferenca}) WHERE T008_Id = '{$rowT008['T008_Id']}'", false);
            }
            return true;
        }

