            } else if($mT007['T007_Versao_NFe'] == '4.00'){
                if($mT007['T007_Flag_ACP'] == 8){
                    require_once("class/nfc400.php");
                    $data="Entrou IF NFC.\n";
                    log($data);
                    $r = fwrite($h, $data);
                } else {
                    // personalização do danfe
                    $danfe = "hardness/dados_usuarios/$bd/danfe400.php";
                    if (file_exists($danfe)) {
                        require_once $danfe;
                    } else {
