            $r = fwrite($h, $data);

            $data="Caminho html:{$cArquivos}/{$id}.html  \n";
            log($data);
            $r = fwrite($h, $data);

            $output = ob_get_contents();

            $data ="HTML CRIADO:{$output} \n";
            // log($data);
            $r = fwrite($h, $data);

            ob_end_clean();
            $retornoHTML = file_put_contents("{$cArquivos}/{$id}.html", $output);
            
            $data ="retorno função file_put_content html:{$retornoHTML} \n";
            log($data);
            $r = fwrite($h, $data);

            $cmd = "xvfb-run --server-num ".mt_rand(0,98)." -s \"-screen 0 640x480x16\" wkhtmltopdf --quiet  --enable-local-file-access --margin-left 6 --margin-right 6 --margin-top 6 --margin-bottom 3 \"{$cArquivos}/{$id}.html\" {$cArquivoPDF}";

            $data ="Montou comando SSH:{$cmd} \n";
            log($data);
            $r = fwrite($h, $data);

            if(file_exists("{$cArquivos}/{$id}.html")){
                $data ="Gerou html de caminho {$cArquivos}/{$id}.html\n";
                log($data);
                $r = fwrite($h, $data);
            }
            
            $retornoComando = shell_exec($cmd);
            
            chdir($g['pathRaiz']);

            if(file_exists("{$cArquivoPDF}")){
                $data ="Gerou PDF de caminho {$cArquivoPDF}\n";
                log($data);
                $r = fwrite($h, $data);
            }

            $data ="return da função :{$cArquivoPDF} \n";
            log($data);
            $r = fwrite($h, $data);

            $data ="return da shell_exec :{$retornoComando} \n";
            log($data);
            $r = fwrite($h, $data);

            unlink("/tmp/{$id}.{$cExtensao_Arquivo}");
            unlink("/tmp/{$id}.html");
            unlink("/tmp/{$id}.pdf");
            unlink("{$cArquivos}/{$id}.{$cExtensao_Arquivo}");
            unlink("{$cArquivos}/{$id}.html");
            unlink("/tmp/{$id}.barcode.png");
            unlink("{$cArquivos}/{$id}.barcode.png");

            fclose($h);
            return $cArquivoPDF;
        }

