            $cClausula .= " T001_Flag_Operacao, ";
            $cClausula .= " T001_Valor_Preco_Unitario, ";
            $cClausula .= " T001_Observacao, ";
            $cClausula .= " T001_Valor_Custo_Unitario, ";
