            $cClausula .= " '{$mT008['T008_T055_Id']}', ";
            $cClausula .= " '{$mT008['T008_Codigo_Produto']}', ";
            //$cClausula .= " current_date(), ";
            $cClausula .= " '{$mT008['T007_Data_Emissao']}', ";
