        public function ven003AssociacaoVendaCompra($dataInicial = '', $dataFinal = ''){
            global $g;
           
            $filtroDataInicial = '';
            $filtroDataFinal   = '';

            if($dataInicial != ''){
                $filtroDataInicial = "AND T001_Data_Lancamento >='".$dataInicial."'";
            }
            if($dataFinal != ''){
                $filtroDataFinal = "AND T001_Data_Lancamento <='".$dataFinal."'";
            }
            
            $resT008 =  mysql_query("SELECT T008_Id,
                                            T001_Id,
                                            D001_Codigo_Produto,
                                            T001_D009_Id                                            
                                       FROM T008
                                  LEFT JOIN T001 ON T001_T008_Id=T008_Id
                                  LEFT JOIN T007 ON T007_Id=T008_T007_Id
                                  LEFT JOIN D009 ON D009_Id=T001_D009_Id
                                  LEFT JOIN D049 ON D049_Id=D009_D049_Id
                                  LEFT JOIN D001 ON D001_Id=D049_D001_Id
                                      WHERE T007_C004_Id = '{$g['empresaAtual']}'
                                        AND T001_Id IS NOT NULL
                                        AND (T008_Compra_T001_Id IS NULL OR T008_Compra_T001_Id = 0)
                                            $filtroDataInicial
                                            $filtroDataFinal
                                   GROUP BY T001_Id");
                        
            $error = mysql_error();
            if(!empty($error)){
                return $error;
            }

            $encontrado = 0;
            while ($rowT008 = mysql_fetch_assoc($resT008)) {
                // echo "D001_Codigo_Produto: {$rowT008['D001_Codigo_Produto']} T008_Id: {$rowT008['T008_Id']} T001_Id: {$rowT008['T001_Id']} ...\n";

                $resT001 = mysql_query("SELECT T001_Id,
                                               T001_T014_Id
                                          FROM T001
                                         WHERE T001_Id < {$rowT008['T001_Id']}
                                           AND T001_Flag_Operacao = 'E'
                                           AND IFNULL(T001_T014_Id,0) > 0
                                           AND T001_D009_Id = '{$rowT008['T001_D009_Id']}'
                                      ORDER BY T001_Id DESC
                                         LIMIT 1");

                if (mysql_num_rows($resT001) > 0) {
                    $rowT001 = mysql_fetch_assoc($resT001);
                    $sql = "UPDATE T008 SET T008_Compra_T001_Id = '{$rowT001['T001_Id']}' WHERE T008_Id = '{$rowT008['T008_Id']}'";
                    mysqli_query($sql);
                    $encontrado ++;
                } else {
                    // echo "\tCompra não encontrada!\n";
                }
            }

            if($encontrado == 0){
                return 'As notas do período ja foram processadas';
            }
            
            return true;
        }

        public function gerarACP($T007_Id)
        {
            global $g;
            
            $cClausula = " SELECT ";
            $cClausula .= " * ";
            $cClausula .= " FROM T007 ";
            $cClausula .= " LEFT JOIN C004 ON C004_Id=T007_C004_Id ";
            $cClausula .= " WHERE T007_Id='$T007_Id' ";
            $cSql_T007 = mysql_query("$cClausula");
            echo mysql_error();
            $T007 = mysql_fetch_array($cSql_T007);
            
            $r_link = 'ven/ven003/outro/imprimirACP/?ajax=true&T007_Id=' . $T007_Id;
            $dir    = $g['pathDados'] . 'pdf/'; 
            is_dir($dir) or mkdir($dir, 0777, true);
            $filename = 'acp_' . $T007['T007_Numero_Nota_Fiscal'] . '.pdf';
            $file     = $dir . $filename;
            $fileFull = $g['pathRaiz'] . '/' . $file;
            
            $r_link = $g['urlRaiz'] . str_replace(' ', '+', $r_link);
    
            shell_exec("xvfb-run --server-num " . mt_rand(0, 98) . " -s \"-screen 0 640x480x16\" wkhtmltopdf --quiet --margin-left 1 --margin-right 1 --margin-top 1 --margin-bottom 1 \"{$r_link}&noEmp=true&p={$g['empresaAtual']}&u={$g['usuarioAtual']}&db={$confUsuario['dbDatabase']}\" \"{$fileFull}\"");
    
            return $fileFull;
        }    
    
        /**
         * Denegar nota fiscal
         *
         * @param int T007_Id
         * @return String/bool
         */     	
        public function denegarNFe($T007_Id)
        {
            set_time_limit(0);

            require_once('bibliotecas/classes/CAD002.php');
            $CAD002 = new CAD002();

            if (empty($T007_Id)) {
                return "Falta o Parametro T007_Id";
            }

            $T007=mysql_query("select T007_Id, T007_D024_Id, T007_Flag_ACP from T007 left join C004 on C004_Id=T007_C004_Id where T007_Id='$T007_Id'");
            $mT007=mysql_fetch_array($T007);

            if (mysql_num_rows($T007)==0)
            {
                return "T007_Id não existe: {$T007_Id}";
            }
            if ($mT007[T007_Flag_ACP]!='6')
            {
                return "O Tipo do documento não é NF-e. Verifique!!!<BR><BR>Tipo: {$mT007[T007_Flag_ACP]}";
            }

            mysql_query("SET AUTOCOMMIT=0");
            mysql_query("START TRANSACTION");

            //-- Cancelando Nota Fiscal
            mysql_query("update T007 
                            set T007_Flag_Cancelada='S',
                                T007_Flag_Classificacao=0,
                                T007_Observacao_Cancelamento='NOTA FISCAL DENEGADA',
                                T007_Flag_Denegado='S',
                                T007_Valor_Total=0
                          where T007_Id='{$mT007['T007_Id']}'");

            //-- Limpa o Flag de classificacao do item
            $sql=mysql_query("update T008 set T008_Flag_Classificacao=0 where T008_T007_Id='{$mT007['T007_Id']}'");

            //-- Cancelando Contas a Receber 
            mysql_query("update T002 set T002_Flag_Cancelada='S',
                                         T002_Data_Recebimento=current_date(),
                                         T002_Observacao_2='*** NF DENEGADA ***',
                                         T002_Valor_Duplicata=0,
                                         T002_Valor_Total=0
                                   where T002_T007_Id='{$mT007['T007_Id']}'");

            //-- Cancelando Contas a Pagar
            mysql_query("update T015 set T015_Flag_Cancelada='S',
                                         T015_Data_Pagamento=current_date(),
                                         T015_Observacao_2='*** NF DENEGADA ***',
                                         T015_Valor_Duplicata=0,
                                         T015_Valor_Total=0
                                   where T015_T007_Id='{$mT007['T007_Id']}'");

            mysql_query("update T001 set T001_Flag_Operacao='C' where T001_T007_Id='{$mT007['T007_Id']}'");

            $T008=mysql_query("select D006_Flag_Estoque,
                                           T008_D009_Id,
                                           T008_Quantidade,
                                           T007_D024_Id,
                                           T008_Id,
                                           T007_Id,
                                           T008_C004_Id,
                                           T007_D006_Id,
                                           T008_Codigo_Produto,
                                           T007_Numero_Nota_Fiscal,
                                           D049_D001_Id 
                                      from T008 
