        /**
         * corrigeNFCe
         *
         * @return String/bool
         */	
        function corrigeNFCe($numeroNota,$numeroProtocolo,$dataAutorizacao,$horaAutorizacao,$numeroChaveAcesso,$serie)
        {
            global $g;

            if(empty($numeroNota)){
                return 'Preencha o numero da nota';
            }
            
            if(empty($numeroProtocolo)){
                return 'Preencha o numero do protocolo';
            }

            if(empty($numeroChaveAcesso)){
                return 'Preencha o numero da chave de acesso';
            }

            if(empty($serie)){
                return 'Preencha o numero da série';
            }

            if(empty($dataAutorizacao) || $dataAutorizacao == '0000-00-00' || $horaAutorizacao == '00:00'){
                return 'Preencha data/hora da autorização';
            }

            $T007 = mysql_query("SELECT T007_Id,
                                        T007_Data_Emissao,
                                        T007_Chave_Acesso_Nfe,
                                        T007_Numero_Protocolo_Nfe
                                   FROM T007
                                  WHERE T007_Numero_Nota_Fiscal = '{$numeroNota}'
                                    AND T007_Serie = '{$serie}'
                                    AND T007_C004_Id = '{$g['empresaAtual']}'
                                    AND T007_Flag_ACP = '8' ");
            
            if(mysql_num_rows($T007) > 1){
                return "Foi encontrado mais de uma NFC-e com o número {$numeroNota} na empresa {$g['empresaAtual']}, por favor verifique";
            } else if(mysql_num_rows($T007) < 1){
                return "Não foi encontrado nenhuma NFC-e com a numeração {$numeroNota} na empresa {$g['empresaAtual']}, por favor verifique";
            }

            $mT007 = mysql_fetch_array($T007);

            if(!empty($mT007['T007_Numero_Protocolo_Nfe']) || $mT007['T007_Numero_Protocolo_Nfe'] > 0){
                return "A NFC-e {$numeroNota} já possui protocolo, operação não pode ser realizada";
            }

            $anoMesNFCe = substr($mT007['T007_Data_Emissao'],0,7);

            if (!is_dir($g['pathDadosAntigo'].'/nfe/xml/autorizado/'.$anoMesNFCe)) {
                mkdir($g['pathDadosAntigo'].'/nfe/xml/autorizado/'.$anoMesNFCe, 0777);
            }

            $dataHoraAutorizacao = gCorrigeDataInverte($dataAutorizacao).' '.$horaAutorizacao.':00';
            $xmlAutorizado = $g['pathDadosAntigo'] . "nfe/xml/autorizado/".$anoMesNFCe."/".$numeroProtocolo. ".xml";

            // Só entra se não existir o XML autorizado no servidor
            if (!file_exists($xmlAutorizado)){

                if (!is_dir($g['pathDadosAntigo'].'/nfe/xml/assinado/')) {
                    mkdir($g['pathDadosAntigo'].'/nfe/xml/assinado/',0777);
                }

                $xmlAssinado  = $g['pathDadosAntigo'] . "nfe/xml/assinado/NFe" . $numeroChaveAcesso . ".xml";
                $diretorioXmlAssinado = dirname($xmlAssinado);
                if(file_exists($xmlAssinado)){
                    @chmod($xmlAssinado, 0777);
                } else {
                    return 'Não existe o arquivo XML assinado com esta chave de acesso';
                }

    
                // Monta os dados para insetrir no XML
                $dadosAutorizacao   = '<protNFe versao="4.00">';
                $dadosAutorizacao  .= '<infProt Id="ID'.$numeroProtocolo.'">';
                $dadosAutorizacao  .= '<tpAmb>1</tpAmb>';
                $dadosAutorizacao  .= '<verAplic>SVRSnfce202209061344</verAplic>';
                $dadosAutorizacao  .= '<chNFe>'.$numeroChaveAcesso.'</chNFe>';
                $dadosAutorizacao  .= '<dhRecbto>'.$dataHoraAutorizacao.'</dhRecbto>';
                $dadosAutorizacao  .= '<nProt>'.$numeroProtocolo.'</nProt>';
                $dadosAutorizacao  .= '<digVal>UnWnRklL6YAWcfsk02+M3Jmyk6w</digVal>';
                $dadosAutorizacao  .= '<cStat>100</cStat>';
                $dadosAutorizacao  .= '<xMotivo>Autorizado o uso da NF-e</xMotivo>';
                $dadosAutorizacao  .= '</infProt>';
                $dadosAutorizacao  .= '</protNFe>';

                $cConteudo = file_get_contents($xmlAssinado);

                if($cConteudo === false){
                    return 'Não foi possível ler o arquivo XML';
                }

                //Retirda a primeira a linha do XML, será incluido novamente logo abaixo
                $cConteudo = substr($cConteudo,38,strlen($cConteudo)-38);

                ?><?php
                $cAutorizado = '<?xml version="1.0" encoding="UTF-8"?>';
                ?><?php
                $cAutorizado .= '<nfeProc versao="4.00" xmlns="http://www.portalfiscal.inf.br/nfe">';
                $cAutorizado .= $cConteudo;
                $cAutorizado .= $dadosAutorizacao;
                $cAutorizado .= '</nfeProc>';

                $arquivoTemporarioXml = tempnam($diretorioXmlAssinado, 'nfce_');
                if($arquivoTemporarioXml === false){
                    return 'Não foi possível criar o arquivo temporário para corrigir o XML';
                }

                $salvaAlteracao = file_put_contents($arquivoTemporarioXml, $cAutorizado, LOCK_EX);

                if($salvaAlteracao === false){
                    @unlink($arquivoTemporarioXml);
                    return 'Não foi possível salvar as alterações no arquivo XML temporário';
                }

                @chmod($arquivoTemporarioXml, 0777);

                if(!@rename($arquivoTemporarioXml, $xmlAssinado)){
                    @unlink($arquivoTemporarioXml);
                    return 'Não foi possível substituir o arquivo XML assinado, verifique as permissões do diretório';
                }

                // Move o XML para a pasta de autorizado
                $movendoXML = rename("{$g['pathDadosAntigo']}/nfe/xml/assinado/NFe{$numeroChaveAcesso}.xml","{$g['pathDadosAntigo']}/nfe/xml/autorizado/{$anoMesNFCe}/{$numeroProtocolo}.xml");
                
                if($movendoXML !== true){
                    return "Não foi possível mover o arquivo XML para a pasta de autorizado";
                }
            } 

            //$chaveAcesso = (empty($mT007['T007_Chave_Acesso_Nfe'])) ? $numeroChaveAcesso : $mT007['T007_Chave_Acesso_Nfe'];
            
            // Inserir o protocolo e data na nota
            mysql_query("UPDATE T007 SET T007_Numero_Protocolo_Nfe    = '{$numeroProtocolo}',
                                         T007_Data_Hora_Protocolo_Nfe = '{$dataHoraAutorizacao}',
                                         T007_Chave_Acesso_Nfe        = '{$numeroChaveAcesso}'
                                   WHERE T007_Id = '{$mT007['T007_Id']}'");

            $T127 = mysql_query("SELECT T127_Id 
                                   FROM T127
                                  WHERE T127_T007_Id = '{$mT007['T007_Id']}'
                               ORDER BY T127_Id DESC LIMIT 1");

            $mT127 = mysql_fetch_array($T127);

            // Atualizado para aautorizado para conseguir imprimir a danfe
            mysql_query("UPDATE T127 SET T127_Codigo_Retorno   = '100',
                                         T127_Retorno_Sefaz    = '100-Autorizado o uso da NF-e',
                                         T127_Chave_Acesso_Nfe = '{$numeroChaveAcesso}'
                                   WHERE T127_Id = '{$mT127['T127_Id']}'");           

            return true;             
        }

