    function VEN003AtualizarObservacoes($T007_Id) {
        if (empty($T007_Id)) {
            return 'Nota fiscal inválida';
        }

        $observacoes = mysql_query("SELECT D188.D188_Id
            FROM T008
            INNER JOIN D006 ON D006.D006_Id = T008.T008_D006_Id
            INNER JOIN D188 ON D188.D188_Id = D006.D006_D188_Id
            LEFT JOIN T297 ON T297.T297_T007_Id = '{$T007_Id}' AND T297.T297_D188_Id = D188.D188_Id
            WHERE T008.T008_T007_Id = '{$T007_Id}' AND T297.T297_Id IS NULL
            GROUP BY D188.D188_Id");
        while ($observacao = mysql_fetch_array($observacoes)) {
            mysql_query("INSERT INTO T297 (T297_T007_Id, T297_D188_Id) VALUES ('{$T007_Id}', '{$observacao['D188_Id']}')");
        }

        $itens = mysql_query("SELECT T008.T008_Id, D189.D189_Id, T297.T297_Id, T298.T298_Id
            FROM T008
            INNER JOIN D006 ON D006.D006_Id = T008.T008_D006_Id
            INNER JOIN D188 ON D188.D188_Id = D006.D006_D188_Id
            INNER JOIN D189 ON D189.D189_Id = D188.D188_D189_Id
            INNER JOIN T297 ON T297.T297_T007_Id = '{$T007_Id}' AND T297.T297_D188_Id = D188.D188_Id
            LEFT JOIN T298 ON T298.T298_T297_Id = T297.T297_Id AND T298.T298_T008_Id = T008.T008_Id
            WHERE T008.T008_T007_Id = '{$T007_Id}'");
        while ($item = mysql_fetch_array($itens)) {
            if (empty($item['T298_Id'])) {
                mysql_query("INSERT INTO T298 (T298_T008_Id, T298_D189_Id, T298_T297_Id) VALUES ('{$item['T008_Id']}', '{$item['D189_Id']}', '{$item['T297_Id']}')");
            } else {
                mysql_query("UPDATE T298 SET T298_D189_Id = '{$item['D189_Id']}' WHERE T298_Id = '{$item['T298_Id']}'");
            }
        }
        return true;
    }

